const RAW_BANK = {
  knowledge: [
    {id:'k1',module:'必修一·基本概念',q:'下列反应属于氧化还原反应的是？',options:['CaO+H₂O=Ca(OH)₂','2Na+Cl₂=2NaCl','NaOH+HCl=NaCl+H₂O','CuSO₄+BaCl₂=BaSO₄↓+CuCl₂'],answer:1,explain:'有元素化合价升降的反应才是氧化还原反应。2Na+Cl₂=2NaCl 中 Na 由 0 价升为 +1，Cl 由 0 价降为 -1。'},
    {id:'k2',module:'必修一·基本概念',q:'下列各组离子在水溶液中能大量共存的是？',options:['H⁺、Na⁺、CO₃²⁻、Cl⁻','Ag⁺、Cl⁻、K⁺、NO₃⁻','Na⁺、K⁺、Cl⁻、NO₃⁻','Ba²⁺、SO₄²⁻、H⁺、Na⁺'],answer:2,explain:'A 中 H⁺与 CO₃²⁻反应；B 中 Ag⁺与 Cl⁻生成沉淀；D 中 Ba²⁺与 SO₄²⁻生成沉淀；C 各离子互不反应。'},
    {id:'k3',module:'必修一·基本概念',q:'1 mol H₂O 的质量约为？',options:['18 g','18','9 g','20 g'],answer:0,explain:'水的摩尔质量 M=18 g/mol，m=n·M=1 mol×18 g/mol=18 g。'},
    {id:'k4',module:'必修一·基本概念',q:'下列物质属于电解质的是？',options:['铜','蔗糖','NaCl','酒精'],answer:2,explain:'电解质是化合物（酸碱盐等），NaCl 在水溶液或熔融态能导电；铜是单质，蔗糖、酒精是非电解质。'},
    {id:'k5',module:'必修一·基本概念',q:'下列离子方程式正确的是？',options:['铁与盐酸：Fe+2H⁺=Fe³⁺+H₂↑','氢氧化钠与盐酸：OH⁻+H⁺=H₂O','碳酸钙与盐酸：CO₃²⁻+2H⁺=CO₂↑+H₂O','铜与稀硫酸：Cu+2H⁺=Cu²⁺+H₂↑'],answer:1,explain:'A 铁与盐酸生成 Fe²⁺而非 Fe³⁺；C 碳酸钙难溶应写化学式 CaCO₃；D 铜不与稀硫酸反应；B 正确。'},
    {id:'k6',module:'必修二',q:'同周期主族元素从左到右，最外层电子数变化是？',options:['逐渐增多','逐渐减少','不变','不确定'],answer:0,explain:'同周期从左到右原子序数增大，最外层电子数从 1 递增到 7（稀有气体为 8）。'},
    {id:'k7',module:'必修二',q:'¹²C 与 ¹⁴C 互为？',options:['同位素','同素异形体','同分异构体','同系物'],answer:0,explain:'质子数相同、中子数不同的同一元素原子互称同位素。¹²C、¹⁴C 质子数都是 6。'},
    {id:'k8',module:'必修二',q:'NaCl 晶体中的化学键类型是？',options:['共价键','离子键','金属键','氢键'],answer:1,explain:'Na⁺与 Cl⁻通过静电作用形成离子键。'},
    {id:'k9',module:'必修二',q:'第三周期第ⅠA族元素是？',options:['Na','Mg','Al','Cl'],answer:0,explain:'第三周期第ⅠA族（碱金属）是钠 Na。'},
    {id:'k10',module:'选择性必修1·反应原理',q:'可逆反应达到化学平衡的标志是？',options:['正、逆反应速率相等','反应完全停止','各物质浓度相等','容器压强不变'],answer:0,explain:'平衡时 v正=v逆≠0，反应仍在进行（动态平衡）；各物质浓度不一定相等。'},
    {id:'k11',module:'选择性必修1·反应原理',q:'升高温度，化学反应速率通常？',options:['加快','减慢','不变','先快后慢'],answer:0,explain:'升温使活化分子百分数增大，有效碰撞增多，反应速率加快。'},
    {id:'k12',module:'选择性必修1·反应原理',q:'在其他条件不变时，增大反应物浓度，平衡将？',options:['正向移动','逆向移动','不移动','无法确定'],answer:0,explain:'根据勒夏特列原理，增大反应物浓度，平衡向减弱该改变的方向（正向）移动。'},
    {id:'k13',module:'选择性必修1·反应原理',q:'下列溶液酸性最强（pH 最小）的是？',options:['pH=1','pH=3','pH=7','pH=13'],answer:0,explain:'pH 越小，c(H⁺)越大，酸性越强。'},
    {id:'k14',module:'选择性必修3·有机化学',q:'下列物质分子中含有与烃基直接相连的羟基（—OH）的是？',options:['乙醇','乙酸','苯','乙烷'],answer:0,explain:'乙醇 CH₃CH₂—OH，羟基直接连在乙基上，属于醇羟基；乙酸的羟基连在羰基上（羧基）。'},
    {id:'k15',module:'选择性必修3·有机化学',q:'CH₂=CH₂ + H₂ → CH₃CH₃ 的反应类型是？',options:['取代反应','加成反应','消去反应','氧化反应'],answer:1,explain:'不饱和键（双键）两端的碳原子直接加上 H 原子，属于加成反应。'},
    {id:'k16',module:'选择性必修3·有机化学',q:'分子式为 C₄H₁₀ 的同分异构体有几种？',options:['1 种','2 种','3 种','4 种'],answer:1,explain:'丁烷有正丁烷 CH₃CH₂CH₂CH₃ 和异丁烷 (CH₃)₂CHCH₃ 两种同分异构体。'},
    {id:'k17',module:'选择性必修3·有机化学',q:'下列物质能使酸性 KMnO₄ 溶液褪色的是？',options:['甲烷','乙烷','乙烯','苯'],answer:2,explain:'乙烯含碳碳双键，易被酸性 KMnO₄ 氧化而使其褪色；甲烷、乙烷、苯通常不能。'},
    {id:'k20',module:'选择性必修2·物质结构与性质',q:'下列能级符号书写正确的是？',options:['1p','2d','3f','4s'],answer:3,explain:'能层 n 对应的能级为 s、p、d、f…，存在条件 l≤n-1。n=1 只有 s；n=2 有 s、p；n=3 有 s、p、d；n=4 才有 f。故 1p、2d、3f 均不存在，4s 正确。'},
    {id:'k21',module:'选择性必修2·物质结构与性质',q:'基态碳原子（₆C）的核外电子排布式正确的是？',options:['1s²2s²2p²','1s²2s²2p⁶','1s²2s¹2p³','1s²2s²2p¹3s¹'],answer:0,explain:'按能量最低、泡利不相容、洪特规则，碳（6 电子）为 1s²2s²2p²。'},
    {id:'k22',module:'选择性必修2·物质结构与性质',q:'同一主族从上到下，元素的第一电离能一般如何变化？',options:['增大','减小','不变','先增后减'],answer:1,explain:'同主族自上而下原子半径增大，原子失电子越来越易，第一电离能总体减小。'},
    {id:'k23',module:'选择性必修2·物质结构与性质',q:'下列分子中，含有 π 键的是？',options:['H₂','HCl','N₂','NaCl'],answer:2,explain:'N₂ 含氮氮三键（1 个 σ 键+2 个 π 键）；H₂、HCl 只含 σ 键；NaCl 为离子键。'},
    {id:'k24',module:'选择性必修2·物质结构与性质',q:'关于 H₂O 分子，下列说法正确的是？',options:['O 原子 sp 杂化','分子为直线形','O 原子 sp³ 杂化，分子为 V 形','分子是非极性分子'],answer:2,explain:'O 采取 sp³ 杂化，含 2 对孤电子对，空间构型为 V 形（角形），是极性分子。'},
    {id:'k25',module:'选择性必修2·物质结构与性质',q:'下列物质沸点最高的是？',options:['H₂S','H₂Se','H₂O','CH₄'],answer:2,explain:'H₂O 分子间存在氢键，沸点反常地高，高于同族 H₂S、H₂Se 及 CH₄。'},
    {id:'k26',module:'选择性必修2·物质结构与性质',q:'下列晶体中，属于原子晶体（共价晶体）的是？',options:['NaCl','干冰（CO₂）','金刚石','冰'],answer:2,explain:'金刚石由 C—C 共价键构成空间网状结构，是原子晶体；NaCl 是离子晶体，干冰、冰是分子晶体。'},
    {id:'k27',module:'选择性必修2·物质结构与性质',q:'BF₃ 分子的空间构型是？',options:['三角锥形','平面三角形','直线形','正四面体'],answer:1,explain:'B 原子 sp² 杂化，无孤电子对，3 个 F 均匀分布在平面内，为平面三角形。'},
    {id:'k28',module:'选择性必修2·物质结构与性质',q:'配合物 [Cu(NH₃)₄]SO₄ 的中心离子是？',options:['Cu','Cu²⁺','NH₃','SO₄²⁻'],answer:1,explain:'中心离子是提供空轨道的 Cu²⁺，NH₃ 是配体，SO₄²⁻ 是外界离子。'},
    {id:'k29',module:'选择性必修2·物质结构与性质',q:'关于氢键，下列说法正确的是？',options:['氢键属于化学键','氢键只存在于水分子之间','氢键是一种特殊的分子间作用力','氢键一定使物质熔沸点降低'],answer:2,explain:'氢键是分子间的特殊作用力（非化学键），存在于 HF、H₂O、NH₃ 等含 N、O、F 的物质之间，通常使熔沸点升高。'},
    {id:'k30',module:'选择性必修2·物质结构与性质',q:'下列物质熔点由高到低的顺序合理的是？',options:['金刚石 > NaCl > 干冰','干冰 > NaCl > 金刚石','NaCl > 金刚石 > 干冰','干冰 > 金刚石 > NaCl'],answer:0,explain:'原子晶体（金刚石）熔点最高，离子晶体（NaCl）次之，分子晶体（干冰）最低。'},
    {id:'k31',module:'选择性必修2·物质结构与性质',q:'CH₄ 分子中 C 原子的杂化方式是？',options:['sp','sp²','sp³','dsp²'],answer:2,explain:'C 形成 4 个 σ 键、无孤电子对，采取 sp³ 杂化，分子为正四面体。'},
  {id:'k34',module:'必修一·基本概念',q:'寻找含氧酸对应的酸性氧化物（酸酐）时，中心原子化合价要求？',options:['升高','降低','不变','一定改变'],answer:2,explain:'酸酐与对应含氧酸中中心元素化合价相同（不变）。如 H₂SO₄（S +6）→ SO₃（S +6）；H₂CO₃（C +4）→ CO₂（C +4）。'},
  {id:'k36',module:'必修一·基本概念',q:'碱性氧化物的定义是？',options:['和碱反应只生成盐和水的氧化物','和酸反应只生成盐和水的氧化物','金属元素形成的氧化物就是碱性氧化物','含有金属元素和氧元素的化合物'],answer:1,explain:'碱性氧化物：能与酸反应只生成盐和水的氧化物（如 Na₂O+2HCl=2NaCl+H₂O）。A 是酸性氧化物的特征；C、D 不对，如 Al₂O₃ 两性、Mn₂O₇ 酸性、Na₂O₂ 过氧化物。'},
  {id:'k38',module:'必修一·基本概念',q:'判断：碱性氧化物与金属氧化物的关系，正确的是？',options:['碱性氧化物一定是金属氧化物；金属氧化物不一定是碱性氧化物','碱性氧化物不一定是金属氧化物；金属氧化物一定是碱性氧化物','碱性氧化物一定是金属氧化物；金属氧化物一定是碱性氧化物','碱性氧化物不一定是金属氧化物；金属氧化物不一定是碱性氧化物'],answer:0,explain:'碱性氧化物一定是金属氧化物（如 Na₂O、CuO）；但金属氧化物不一定是碱性氧化物，如 Mn₂O₇ 酸性、Al₂O₃ 两性、Na₂O₂ 过氧化物。'},
  {id:'k39',module:'必修一·基本概念',q:'Mn₂O₇ 属于酸性氧化物，该实例可以说明？',options:['酸性氧化物一定是非金属氧化物','酸性氧化物不一定是非金属氧化物','金属氧化物一定是碱性氧化物','非金属氧化物一定是酸性氧化物'],answer:1,explain:'Mn 是金属元素，Mn₂O₇ 却是酸性氧化物，说明酸性氧化物不一定是非金属氧化物（也可由金属元素形成）。'},
  {id:'k40',module:'必修一·基本概念',q:'CO、NO 是非金属氧化物，但不属于酸性氧化物，该例子说明？',options:['非金属氧化物一定是酸性氧化物','非金属氧化物不一定是酸性氧化物','酸性氧化物一定是非金属氧化物','金属氧化物一定不是酸性氧化物'],answer:1,explain:'CO、NO 是非金属氧化物却不与碱反应生成盐和水，说明非金属氧化物不一定是酸性氧化物。'},
  {id:'k42',module:'必修一·基本概念',q:'金属氧化物是否一定为碱性氧化物？',options:['一定','不一定'],answer:1,explain:'不一定。如 Mn₂O₇ 酸性、Al₂O₃ 两性、Na₂O₂ 过氧化物，都不是碱性氧化物。'},
  {id:'k43',module:'必修一·基本概念',q:'碱性氧化物是否一定是金属氧化物？',options:['一定','不一定'],answer:0,explain:'一定。碱性氧化物定义为能与酸反应生成盐和水的氧化物，全部由金属元素与氧组成，故一定是金属氧化物。'},
  {id:'k44',module:'必修一·基本概念',q:'酸性氧化物是否一定是非金属氧化物？',options:['一定','不一定'],answer:1,explain:'不一定。如 Mn₂O₇（Mn 为金属元素）却是酸性氧化物，说明酸性氧化物也可由金属元素形成。'},
  {id:'k45',module:'必修一·基本概念',q:'非金属氧化物是否一定是酸性氧化物？',options:['一定','不一定'],answer:1,explain:'不一定。如 CO、NO 等不与碱反应生成盐和水，不属于酸性氧化物。'},
  {id:'k46',module:'必修一·基本概念',q:'下列关于电解质的定义，说法正确的是？',options:['水溶液中能导电的物质就是电解质','熔融状态下能导电的化合物是电解质','水溶液中或熔融状态能导电的化合物','所有能导电的化合物都是电解质'],answer:2,explain:'电解质是指在水溶液中或熔融状态下能够导电的化合物。A未限定“化合物”（金属等单质也能导电）；B只说了熔融状态，缺“或水溶液”；D表述不严谨。C为标准定义。'},
  {id:'k47',module:'必修一·基本概念',q:'下列物质属于非电解质的是？',options:['NaCl','NaOH','蔗糖','H₂SO₄'],answer:2,explain:'非电解质是在水溶液中和熔融状态下都不能导电的化合物。蔗糖是有机物，溶于水不电离、不导电，属非电解质；NaCl、NaOH为强电解质，H₂SO₄为强酸（强电解质）。'},
  {id:'k48',module:'必修一·基本概念',q:'强电解质的特点是？',options:['水溶液中部分电离，存在电离平衡','水溶液中完全电离，无电离平衡','熔融状态下一定不能导电','主要包括弱酸、弱碱和水'],answer:1,explain:'强电解质在水溶液中完全电离，不存在电离平衡（用“=”）。弱电解质才部分电离、存在电离平衡；弱酸、弱碱和水是弱电解质。'},
  {id:'k49',module:'必修一·基本概念',q:'下列电离方程式书写正确的是？',options:['H₂SO₄=2H⁺+SO₄²⁻','CH₃COOH=H⁺+CH₃COO⁻','NH₃·H₂O=NH₄⁺+OH⁻','NaCl⇌Na⁺+Cl⁻'],answer:0,explain:'A正确：H₂SO₄为强酸，完全电离，用“=”，H₂SO₄=2H⁺+SO₄²⁻。B错误：CH₃COOH是弱酸，应写可逆符号“⇌”。C错误：NH₃·H₂O是弱碱，应写“⇌”而非“=”。D错误：NaCl是强电解质，应写“=”而非“⇌”。故唯一正确的是A。'},
  {id:'k50',module:'必修一·基本概念',q:'关于酸式盐的电离，下列说法错误的是？',options:['弱酸式盐完全电离出阳离子，保留酸式根','NaHCO₃的电离方程式为 NaHCO₃=Na⁺+HCO₃⁻','强酸式盐在水溶液中电离出 H⁺、酸根离子和阳离子','NaHSO₄在熔融状态下电离为 Na⁺+H⁺+SO₄²⁻'],answer:3,explain:'A正确：弱酸式盐（如NaHCO₃）溶于水完全电离为阳离子+酸式根，保留酸式根。B正确：NaHCO₃=Na⁺+HCO₃⁻。C正确：强酸式盐（如NaHSO₄）在水溶液中电离出H⁺、酸根和阳离子。D错误：NaHSO₄在熔融状态下只断裂离子键，电离为Na⁺+HSO₄⁻，不释放H⁺（H⁺的释放需要水）。故D说法错误。'},
  {id:'k51',module:'必修一·基本概念',q:'下列物质中属于弱电解质的是？',options:['HCl','NaOH','H₂O','NaCl'],answer:2,explain:'弱电解质是在水溶液中部分电离的电解质。H₂O能极微弱电离（H₂O⇌H⁺+OH⁻），属弱电解质。HCl（强酸）、NaOH（强碱）、NaCl（盐）均为强电解质。'},
  {id:'k52',module:'必修一·基本概念',q:'弱电解质在水溶液中是否存在电离平衡？',options:['是','否'],answer:0,explain:'弱电解质部分电离，存在电离平衡（可逆），故选“是”。'},
  {id:'k54',module:'必修一·基本概念',q:'非电解质在水溶液中或熔融状态下能否导电？',options:['能','不能'],answer:1,explain:'非电解质在水溶液和熔融状态均不导电，故选“不能”。'},
  {id:'k56',module:'必修一·基本概念',q:'强酸式盐在水溶液和熔融状态下的电离产物是否相同？',options:['相同','不同'],answer:1,explain:'强酸式盐NaHSO₄：水溶液中=Na⁺+H⁺+SO₄²⁻；熔融状态下=Na⁺+HSO₄⁻（只断离子键，HSO₄⁻不拆）。产物不同，故选“不同”。'},
  {id:'k57',module:'必修一·基本概念',q:'金属导电的本质是？',options:['自由离子定向移动','自由电子定向移动','分子定向移动','原子定向移动'],answer:1,explain:'金属中存在大量自由电子，导电依靠自由电子定向移动，属于物理变化。'},
  {id:'k58',module:'必修一·基本概念',q:'下列关于金属导电的说法正确的是？',options:['导电过程伴随化学变化','升温导电性增强','升温导电性减弱','导电本质是离子定向移动'],answer:2,explain:'金属导电靠自由电子定向移动，是物理变化（无化学变化）；升温使金属阳离子热振动加剧，阻碍电子运动，导电性减弱。'},
  {id:'k59',module:'必修一·基本概念',q:'电解质溶液导电的本质是？',options:['自由电子定向移动','自由离子定向移动','分子定向移动','原子定向移动'],answer:1,explain:'电解质溶液中存在自由移动的离子，导电依靠阴、阳离子定向移动，并在电极发生电解（化学变化）。'},
  {id:'k60',module:'必修一·基本概念',q:'溶液导电性强弱的决定因素是？',options:['电解质的强弱','离子浓度和离子所带电荷数','溶液的体积','溶质的质量'],answer:1,explain:'导电性强弱取决于单位体积内自由移动离子的数目（离子浓度）和离子所带电荷数，与电解质强弱无必然关系。'},
  {id:'k62',module:'必修一·基本概念',q:'以液体为分散剂时，胶体的粒子直径范围是？',options:['＜1nm','1~100nm','＞100nm','＞1nm'],answer:1,explain:'胶体分散质粒子直径在 1~100nm 之间，介于溶液与浊液之间。'},
  {id:'k63',module:'必修一·基本概念',q:'下列分散系中，粒子直径小于 1nm 的是？',options:['溶液','胶体','浊液','悬浊液'],answer:0,explain:'溶液分散质粒子直径＜1nm；胶体 1~100nm；浊液（含悬浊液）＞100nm。'},
  {id:'k64',module:'必修一·基本概念',q:'金属导电过程是否属于物理变化？',options:['是','否'],answer:0,explain:'金属导电只是自由电子定向移动，没有新物质生成，属于物理变化。'},
  {id:'k65',module:'必修一·基本概念',q:'电解质溶液导电过程是否伴随化学变化？',options:['是','否'],answer:0,explain:'电解质溶液导电时，阴、阳离子分别在两极放电，发生电解反应，因此伴随化学变化。'},
  {id:'k66',module:'必修一·基本概念',q:'升温时，弱电解质溶液的导电性是否变强？',options:['是','否'],answer:0,explain:'升温促进弱电解质电离，溶液中离子浓度增大，故导电性增强。'},
  {id:'k67',module:'必修一·基本概念',q:'溶液导电性强弱与电解质强弱是否有必然关系？',options:['是','否'],answer:1,explain:'很稀的强电解质溶液导电性可能弱于较浓的弱电解质溶液，导电性取决于离子浓度与电荷数，与电解质强弱无必然关系。'},
  {id:'k69',module:'必修一·基本概念',q:'制备 Fe(OH)₃ 胶体的正确操作是？',options:['向沸水中滴加饱和 FeCl₃ 溶液，持续煮沸至红褐色','向冷水中滴加饱和 FeCl₃ 溶液，加热煮沸','向沸水中滴加稀 FeCl₃ 溶液，煮沸至沉淀生成','向常温水中滴加饱和 FeCl₃ 溶液，搅拌均匀'],answer:0,explain:'应将饱和 FeCl₃ 溶液滴入沸水，继续煮沸至液体呈红褐色；不能久煮至生成沉淀（那会聚沉）。'},
  {id:'k70',module:'必修一·基本概念',q:'制备 Fe(OH)₃ 胶体的化学方程式书写正确的是？',options:['FeCl₃+3H₂O = Fe(OH)₃↓+3HCl','FeCl₃+3H₂O =(加热)= Fe(OH)₃(胶体)+3HCl','FeCl₃+3H₂O =(加热)= Fe(OH)₃↓+3HCl','FeCl₃+3H₂O = Fe(OH)₃(胶体)+3HCl'],answer:1,explain:'反应需加热条件，产物 Fe(OH)₃ 是胶体应标"(胶体)"而非"↓"：FeCl₃+3H₂O =(加热)= Fe(OH)₃(胶体)+3HCl。'},
  {id:'k71',module:'必修一·基本概念',q:'区分胶体与溶液的常用方法是？',options:['观察颜色','丁达尔效应','过滤','静置分层'],answer:1,explain:'胶体对光有散射作用而产生丁达尔效应，溶液无此现象，是最常用的区分方法。'},
  {id:'k72',module:'必修一·基本概念',q:'下列关于胶体性质的说法错误的是？',options:['丁达尔效应属于物理变化','胶粒会做无规则热运动（布朗运动）','胶体整体显电性','加热可使胶体聚沉'],answer:2,explain:'胶体整体呈电中性（胶粒带电、分散剂带相反电荷）；丁达尔效应是物理散射，布朗运动、加热聚沉均正确。'},
  {id:'k73',module:'必修一·基本概念',q:'Fe(OH)₃ 胶粒的带电情况是？',options:['带正电','带负电','不带电','无法确定'],answer:0,explain:'Fe(OH)₃ 胶粒吸附溶液中的 Fe³⁺ 而带正电，电泳时向阴极移动。'},
  {id:'k74',module:'必修一·基本概念',q:'下列方法不能使胶体发生聚沉的是？',options:['加入电解质','加热搅拌','加入带相反电荷的胶体','静置冷却'],answer:3,explain:'聚沉方法：加电解质、加热、加带相反电荷的胶体、搅拌等；静置冷却不会破坏胶体稳定性，不能聚沉。'},
  {id:'k77',module:'必修一·基本概念',q:'硅酸胶粒是否带负电？',options:['是','否'],answer:0,explain:'硅酸(H₂SiO₃)胶粒吸附阴离子而带负电，与 Fe(OH)₃ 胶粒电性相反。'},
  {id:'k80',module:'必修一·基本概念',type:'物质判断',q:'关于石灰石（主要成分 CaCO₃），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:1,explain:'石灰石主要成分 CaCO₃ 是离子化合物，固态时不导电，但在水溶液或熔融状态下能电离出离子而导电，属于电解质。只有单质和混合物才“既不是电解质也不是非电解质”。'},
  {id:'k81',module:'必修一·基本概念',type:'物质判断',q:'关于蔗糖（C₁₂H₂₂O₁₁），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:2,explain:'蔗糖是化合物，其水溶液和熔融状态都不能导电，属于非电解质。'},
  {id:'k82',module:'必修一·基本概念',type:'物质判断',q:'关于氯气（Cl₂），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:3,explain:'Cl₂ 是单质，在通常状态下不导电；电解质与非电解质都只针对化合物，单质既不是电解质也不是非电解质。'},
  {id:'k83',module:'必修一·基本概念',type:'物质判断',q:'关于氯化钠固体（NaCl），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:1,explain:'NaCl 是离子化合物，固体中离子被束缚不能自由移动故不导电；但熔融或溶于水时能电离导电，属于电解质。'},
  {id:'k84',module:'必修一·基本概念',type:'物质判断',q:'关于液氨（NH₃），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:2,explain:'NH₃ 自身不能电离出离子（其水溶液导电是因为生成 NH₃·H₂O 电离），故 NH₃ 属于非电解质。'},
  {id:'k85',module:'必修一·基本概念',type:'物质判断',q:'关于金刚石（C），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:3,explain:'金刚石是碳的单质，不导电，且单质既不是电解质也不是非电解质。'},
  {id:'k86',module:'必修一·基本概念',type:'物质判断',q:'关于铜（Cu），下列说法正确的是？',options:['能导电','属于电解质'],answer:0,explain:'铜是金属单质，存在自由电子，能导电；但电解质的前提是化合物，单质既不是电解质也不是非电解质，故"属于电解质"错误。'},
  {id:'k87',module:'必修一·基本概念',type:'物质判断',q:'关于石墨（C），下列说法正确的是？',options:['能导电','属于电解质'],answer:0,explain:'石墨是碳的单质，层内有自由移动的电子，能导电；但单质不是化合物，既不是电解质也不是非电解质。'},
  {id:'k88',module:'必修一·基本概念',type:'物质判断',q:'关于食盐水（NaCl 水溶液），下列说法正确的是？',options:['能导电','属于电解质'],answer:0,explain:'食盐水中有自由移动的 Na⁺ 和 Cl⁻，能导电；但食盐水是混合物（溶液），电解质必须是化合物，混合物既不是电解质也不是非电解质。'},
  {id:'k89',module:'必修一·基本概念',type:'物质判断',q:'铁（Fe）属于下列哪一类物质？',options:['电解质','既不是电解质也不是非电解质'],answer:1,explain:'铁是金属单质，不是化合物，因此既不是电解质也不是非电解质。'},
  {id:'k90',module:'必修一·基本概念',type:'物质判断',q:'稀硫酸（H₂SO₄ 的水溶液）属于下列哪一类物质？',options:['电解质','既不是电解质也不是非电解质'],answer:1,explain:'稀硫酸是 H₂SO₄ 溶于水形成的混合物（溶液），不是化合物，既不是电解质也不是非电解质；纯 H₂SO₄ 本身才是电解质。'},
  {id:'k91',module:'必修一·基本概念',type:'物质判断',q:'盐酸（HCl 的水溶液）属于下列哪一类物质？',options:['电解质','既不是电解质也不是非电解质'],answer:1,explain:'盐酸是 HCl 气体溶于水形成的混合物，不是化合物，既不是电解质也不是非电解质；气态 HCl 或纯液态 HCl 才是电解质。'},
  {id:'k92',module:'必修一·基本概念',type:'物质判断',q:'关于 Ba(OH)₂ 晶体，下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:1,explain:'Ba(OH)₂ 是离子化合物（强碱），属于电解质；其晶体中离子被束缚不能自由移动，故固体不导电。'},
  {id:'k93',module:'必修一·基本概念',type:'物质判断',q:'关于硫酸（H₂SO₄），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:1,explain:'H₂SO₄ 是强酸，属于电解质；纯 H₂SO₄ 以分子形式存在，不导电（其水溶液能导电）。'},
  {id:'k94',module:'必修一·基本概念',type:'物质判断',q:'关于 NaHSO₄ 晶体，下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:1,explain:'NaHSO₄ 是离子化合物，属于电解质；固态时离子不能自由移动，不导电（溶于水或熔融才导电）。'},
  {id:'k95',module:'必修一·基本概念',type:'物质判断',q:'关于氢氧化钠固体，下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:1,explain:'NaOH 是离子化合物（强碱），属于电解质；固体中离子不能自由移动，不导电。'},
  {id:'k96',module:'必修一·基本概念',type:'物质判断',q:'关于氯化氢（HCl），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:1,explain:'HCl 是化合物，溶于水完全电离，属于电解质；气态或纯液态 HCl 不导电（其水溶液盐酸才导电）。'},
  {id:'k97',module:'必修一·基本概念',type:'物质判断',q:'关于十水合碳酸钠（Na₂CO₃·10H₂O），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:1,explain:'Na₂CO₃ 是离子化合物，属于电解质；结晶水合物固体中离子不能自由移动，不导电。'},
  {id:'k98',module:'必修一·基本概念',type:'物质判断',q:'关于明矾（KAl(SO₄)₂·12H₂O），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:1,explain:'明矾是离子化合物，溶于水能电离，属于电解质；其固体中离子不能自由移动，不导电。'},
  {id:'k99',module:'必修一·基本概念',type:'物质判断',q:'关于硫酸铜晶体（CuSO₄·5H₂O），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:1,explain:'CuSO₄ 是离子化合物，属于电解质；晶体中离子不能自由移动，不导电。'},
  {id:'k101',module:'必修一·基本概念',type:'物质判断',q:'关于纯磷酸（H₃PO₄），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:1,explain:'H₃PO₄ 是中强酸，溶于水部分电离，属于弱电解质；纯磷酸分子不能自由移动，不导电。'},
  {id:'k102',module:'必修一·基本概念',type:'物质判断',q:'关于硫化氢（H₂S），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:1,explain:'H₂S 是化合物，溶于水部分电离，属于弱电解质；气态 H₂S 不导电。'},
  {id:'k103',module:'必修一·基本概念',type:'物质判断',q:'关于固态苛性钾（KOH），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:1,explain:'KOH 是离子化合物（强碱），属于电解质；固体中离子不能自由移动，不导电。'},
  {id:'k104',module:'必修一·基本概念',type:'物质判断',q:'关于熟石灰固体（Ca(OH)₂），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:1,explain:'Ca(OH)₂ 是离子化合物（中强碱），属于电解质；固体不导电。'},
  {id:'k105',module:'必修一·基本概念',type:'物质判断',q:'关于液态氯化氢，下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:1,explain:'液态 HCl 是共价化合物，属于电解质（溶于水完全电离）；纯液态 HCl 无自由离子，不导电。'},
  {id:'k106',module:'必修一·基本概念',type:'物质判断',q:'关于液态乙酸（CH₃COOH），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:1,explain:'CH₃COOH 是弱酸，属于弱电解质；纯液态乙酸分子不能自由移动，几乎不导电。'},
  {id:'k107',module:'必修一·基本概念',type:'物质判断',q:'关于甲烷（CH₄），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:2,explain:'CH₄ 是共价化合物，水溶液和熔融态均不电离，属于非电解质。'},
  {id:'k108',module:'必修一·基本概念',type:'物质判断',q:'关于酒精（C₂H₅OH），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:2,explain:'酒精是共价化合物，水溶液和熔融态均不电离，属于非电解质。'},
  {id:'k109',module:'必修一·基本概念',type:'物质判断',q:'关于三氧化硫（SO₃），下列说法正确的是？',options:['能导电','属于电解质','属于非电解质','既不是电解质，也不是非电解质'],answer:2,explain:'SO₃ 自身不能电离，溶于水生成 H₂SO₄ 才导电，故 SO₃ 属于非电解质（不是电解质）。'},
  {id:'k110',module:'必修一·基本概念',type:'物质判断',q:'关于硫酸钠溶液（Na₂SO₄ 水溶液），下列说法正确的是？',options:['能导电','属于电解质'],answer:0,explain:'硫酸钠溶液中有自由移动的 Na⁺ 和 SO₄²⁻，能导电；但溶液是混合物，电解质必须是化合物，混合物既不是电解质也不是非电解质。'},
  {id:'k111',module:'必修一·基本概念',type:'物质判断',q:'关于铝丝（Al），下列说法正确的是？',options:['能导电','属于电解质'],answer:0,explain:'铝是金属单质，有自由电子，能导电；但单质既不是电解质也不是非电解质。'},
  {id:'k113',module:'必修一·基本概念',type:'物质判断',q:'关于金属镁（Mg），下列说法正确的是？',options:['能导电','属于电解质'],answer:0,explain:'镁是金属单质，有自由电子，能导电；但单质既不是电解质也不是非电解质。'},
  {id:'k114',module:'必修一·基本概念',type:'物质判断',q:'关于氨水（NH₃ 的水溶液），下列说法正确的是？',options:['能导电','属于电解质'],answer:0,explain:'氨水中有 NH₄⁺ 和 OH⁻（NH₃·H₂O 部分电离），能导电；但氨水是混合物，既不是电解质也不是非电解质（NH₃ 本身是非电解质）。'},
  {id:'k115',module:'必修一·基本概念',type:'物质判断',q:'关于熔融的氯化钾（KCl），下列说法正确的是？',options:['属于电解质','既不是电解质也不是非电解质'],answer:0,explain:'KCl 是离子化合物，熔融态有自由移动的 K⁺ 和 Cl⁻，能导电，且属于电解质（只有单质和混合物才"既不是"）。'},
  {id:'k116',module:'必修一·基本概念',q:'澄清石灰水中通入少量 CO₂，反应的主要产物是？',options:['Ca(HCO₃)₂','CaCO₃↓+H₂O','CaO+H₂O','Ca(OH)₂+CO'],answer:1,explain:'少量 CO₂ 与 Ca(OH)₂ 反应生成碳酸钙沉淀和水：Ca(OH)₂+CO₂=CaCO₃↓+H₂O。只有当 CO₂ 过量时才会进一步生成可溶的 Ca(HCO₃)₂。'},
  {id:'k117',module:'必修一·基本概念',q:'澄清石灰水中通入过量 CO₂，最终产物为？',options:['CaCO₃','Ca(HCO₃)₂','CaSO₃','Ca(HSO₃)₂'],answer:1,explain:'过量 CO₂ 时，先生成的 CaCO₃ 沉淀继续与 CO₂、H₂O 反应生成可溶的碳酸氢钙：CaCO₃+CO₂+H₂O=Ca(HCO₃)₂，沉淀溶解，故最终产物是 Ca(HCO₃)₂。'},
  {id:'k122',module:'必修一·基本概念',q:'澄清石灰水中通入少量 SO₂，反应的主要产物是？',options:['CaSO₃↓+H₂O','Ca(HSO₃)₂','CaSO₄+H₂O','CaCO₃↓+H₂O'],answer:0,explain:'少量 SO₂ 与 Ca(OH)₂ 生成亚硫酸钙沉淀和水：Ca(OH)₂+SO₂=CaSO₃↓+H₂O，与 CO₂ 的情况类似。'},
  {id:'k123',module:'必修一·基本概念',q:'澄清石灰水中通入过量 SO₂，最终产物为？',options:['CaSO₃','Ca(HSO₃)₂','Ca(HCO₃)₂','CaSO₄'],answer:1,explain:'过量 SO₂ 时，CaSO₃ 沉淀继续与 SO₂、H₂O 生成可溶的亚硫酸氢钙：CaSO₃+SO₂+H₂O=Ca(HSO₃)₂，沉淀溶解。'},
  {id:'k132',module:'必修一·基本概念',q:'H₂S 溶液中加入少量 NaOH，发生反应的生成物是？',options:['NaHS+H₂O','Na₂S+2H₂O','S+H₂O','Na₂SO₃+H₂O'],answer:0,explain:'少量 NaOH 时，二元弱酸 H₂S 只中和第一个 H⁺，生成酸式盐 NaHS 和水：H₂S+NaOH=NaHS+H₂O。'},
  {id:'k133',module:'必修一·基本概念',q:'H₂S 溶液中加入过量 NaOH，最终产物为？',options:['NaHS','Na₂S+2H₂O','H₂S','SO₂'],answer:1,explain:'过量 NaOH 时，H₂S 两个 H⁺ 均被中和，生成正盐 Na₂S 和水：H₂S+2NaOH=Na₂S+2H₂O。'},
  {id:'k136',module:'必修一·基本概念',q:'向 Na₂CO₃ 溶液滴加少量稀盐酸，生成物正确的是？',options:['NaHCO₃+NaCl','2NaCl+H₂O+CO₂↑','NaOH+NaHCO₃','CO₂+NaCl'],answer:0,explain:'少量盐酸时，CO₃²⁻ 只结合一个 H⁺ 生成 HCO₃⁻，得到 NaHCO₃ 和 NaCl：Na₂CO₃+HCl=NaHCO₃+NaCl，不产生 CO₂。'},
  {id:'k137',module:'必修一·基本概念',q:'向 Na₂CO₃ 溶液滴加过量稀盐酸，产物为？',options:['NaHCO₃','2NaCl+H₂O+CO₂↑','Na₂O+CO₂','NaHCO₃+CO₂'],answer:1,explain:'过量盐酸时，HCO₃⁻ 继续与 H⁺ 反应生成 CO₂ 和水：Na₂CO₃+2HCl=2NaCl+H₂O+CO₂↑。'},
  {id:'k142',module:'必修一·基本概念',q:'向漂白粉溶液中通入少量 CO₂，反应产物正确的是？',options:['Ca(HCO₃)₂ + 2HClO','CaCO₃↓ + 2HClO','CaO + CO₂ + HClO','CaCl₂ + HClO'],answer:1,explain:'漂白粉有效成分是 Ca(ClO)₂，少量 CO₂ 时：Ca(ClO)₂+CO₂+H₂O=CaCO₃↓+2HClO（酸性 H₂CO₃>HClO，生成正盐与沉淀）。'},
  {id:'k143',module:'必修一·基本概念',q:'向漂白粉溶液中通入过量 CO₂，最终产物为？',options:['CaCO₃↓ + 2HClO','Ca(HCO₃)₂ + 2HClO','CaCO₃ + CO₂','CaCl₂ + H₂CO₃'],answer:1,explain:'过量 CO₂ 时生成的 CaCO₃ 会继续与 CO₂、H₂O 反应生成可溶的 Ca(HCO₃)₂：CaCO₃+CO₂+H₂O=Ca(HCO₃)₂，最终得 Ca(HCO₃)₂+2HClO。'},
  {id:'k144',module:'必修一·基本概念',q:'向 NaClO 溶液中通入 CO₂，下列说法正确的是？',options:['少量 CO₂ 生成 Na₂CO₃','存在少量、过量不同产物','无论少量过量均生成 NaHCO₃ + HClO','不发生反应'],answer:2,explain:'酸性：H₂CO₃>HClO>HCO₃⁻。CO₂ 通入 NaClO 只能将 ClO⁻ 转化为 HClO，且因 HClO 酸性比 HCO₃⁻ 强，只能生成 HCO₃⁻ 而不能生成 CO₃²⁻，故少量、过量产物相同：NaClO+CO₂+H₂O=NaHCO₃+HClO。'},
  {id:'k145',module:'必修一·基本概念',q:'向 NaAlO₂ 溶液中通入少量 CO₂，产物为？',options:['Al(OH)₃↓ + Na₂CO₃','Al(OH)₃↓ + NaHCO₃','Al₂O₃ + Na₂CO₃','Al(OH)₃↓ + CO₂'],answer:0,explain:'少量 CO₂ 时：2NaAlO₂+CO₂+3H₂O=2Al(OH)₃↓+Na₂CO₃（生成正盐与 Al(OH)₃ 沉淀）。'},
  {id:'k146',module:'必修一·基本概念',q:'向 NaAlO₂ 溶液中通入过量 CO₂，最终产物为？',options:['Al(OH)₃↓ + Na₂CO₃','Al(OH)₃↓ + NaHCO₃','AlO₂⁻ + CO₃²⁻','Al₂(CO₃)₃'],answer:1,explain:'过量 CO₂ 时：NaAlO₂+CO₂+2H₂O=Al(OH)₃↓+NaHCO₃（Al(OH)₃ 不溶于过量碳酸，故沉淀不溶解，且生成酸式盐）。'},
  {id:'k149',module:'必修一·基本概念',q:'SO₂ 通入少量 NaClO 溶液，反应的离子产物正确的是？',options:['Cl⁻ + SO₄²⁻ + 2H⁺','Cl⁻ + SO₄²⁻ + 2HClO','ClO⁻ + SO₃²⁻','HClO + SO₃²⁻'],answer:0,explain:'SO₂ 被 ClO⁻ 氧化：SO₂+ClO⁻+H₂O=SO₄²⁻+Cl⁻+2H⁺。少量 NaClO 时 ClO⁻ 消耗完，产物在酸性环境中为 Cl⁻、SO₄²⁻ 和 H⁺，不是 HClO。'},
  {id:'k150',module:'必修一·基本概念',q:'SO₂ 通入过量 NaClO 溶液，最终产物为？',options:['Cl⁻ + SO₄²⁻ + 2H⁺','Cl⁻ + SO₄²⁻ + 2HClO','SO₃²⁻ + HClO','Cl₂ + SO₄²⁻'],answer:1,explain:'过量 NaClO 时溶液呈碱性，SO₂ 仍被氧化为 SO₄²⁻、ClO⁻ 还原为 Cl⁻，但环境中 ClO⁻ 充足、H⁺ 被中和，最终以 HClO 形式存在：产物 Cl⁻+SO₄²⁻+2HClO。'},
  {id:'k156',module:'必修一·基本概念',q:'SO₂ 与次氯酸盐反应，是否属于氧化还原反应？',options:['是','否'],answer:0,explain:'是。次氯酸盐中 Cl 为 +1 价、SO₂ 中 S 为 +4 价，二者发生价态变化（Cl→Cl⁻、S→+6），属于氧化还原反应。'},
  {id:'k158',module:'必修一·基本概念',q:'向 AlCl₃ 溶液中滴入少量 NaOH 溶液，反应产物为？',options:['Al(OH)₃↓ + 3NaCl','Na[Al(OH)₄] + 3NaCl','AlCl₃ + Na₂O','Al₂O₃ + NaCl'],answer:0,explain:'少量 NaOH 时 Al³⁺ 只结合少量 OH⁻ 生成 Al(OH)₃ 沉淀：AlCl₃+3NaOH=Al(OH)₃↓+3NaCl。'},
  {id:'k159',module:'必修一·基本概念',q:'向 AlCl₃ 溶液中滴入过量 NaOH 溶液，最终产物为？',options:['Al(OH)₃↓','Na[Al(OH)₄] + 3NaCl','AlCl₃ + NaOH','Al₂(SO₄)₃ + NaCl'],answer:1,explain:'过量 NaOH 时，生成的 Al(OH)₃ 继续与 OH⁻ 反应生成可溶的 Na[Al(OH)₄]（四羟基合铝酸钠）：Al(OH)₃+NaOH=Na[Al(OH)₄]。'},
  {id:'k160',module:'必修一·基本概念',q:'向 NaAlO₂ 溶液中滴入少量稀盐酸，反应产物正确的是？',options:['AlCl₃ + NaCl + H₂O','Al(OH)₃↓ + NaCl + 2H₂O','Al₂O₃ + HCl','Na[Al(OH)₄] + H₂O'],answer:1,explain:'少量盐酸时，AlO₂⁻ 结合 H⁺ 和 H₂O 生成 Al(OH)₃ 沉淀：NaAlO₂+HCl+H₂O=Al(OH)₃↓+NaCl。'},
  {id:'k161',module:'必修一·基本概念',q:'向 NaAlO₂ 溶液中滴入过量稀盐酸，最终产物为？',options:['Al(OH)₃↓ + NaCl','NaCl + AlCl₃ + 4H₂O','AlCl₃ + HCl','Na₂O + AlCl₃'],answer:1,explain:'过量盐酸时 AlO₂⁻ 先转化为 Al(OH)₃，随后 Al(OH)₃+3H⁺=Al³⁺+3H₂O 溶解，最终得 AlCl₃ 和 NaCl：NaAlO₂+4HCl=AlCl₃+NaCl+2H₂O。'},
  {id:'k162',module:'必修一·基本概念',q:'向 AlCl₃ 溶液中滴加氨水，下列说法正确的是？',options:['少量氨水生成沉淀，过量氨水沉淀溶解','无少量、过量区别，只生成 Al(OH)₃ 沉淀','过量氨水生成 Na[Al(OH)₄]','不发生化学反应'],answer:1,explain:'氨水为弱碱，只能将 Al³⁺ 沉淀为 Al(OH)₃，且过量氨水不能溶解 Al(OH)₃（与 NaOH 不同）。'},
  {id:'k163',module:'必修一·基本概念',q:'Fe 粉与少量稀硝酸反应（硝酸少量、铁过量），铁的产物为？',options:['Fe(NO₃)₂ + NO↑','Fe(NO₃)₃ + NO↑','FeO + NO₂↑','Fe(NO₃)₃ + NO₂↑'],answer:0,explain:'硝酸少量、铁过量：先发生 Fe+4HNO₃(稀)=Fe(NO₃)₃+NO↑+2H₂O，但过量 Fe 将 Fe³⁺ 还原为 Fe²⁺（2Fe³⁺+Fe=3Fe²⁺），故最终产物为 Fe(NO₃)₂（Fe²⁺）。注：原文件答案标为 Fe(NO₃)₃，化学上不正确，已按正确结论修正。'},
  {id:'k164',module:'必修一·基本概念',q:'Fe 粉与过量稀硝酸反应（硝酸过量、铁不足），最终生成物为？',options:['Fe(NO₃)₂ + NO↑','Fe(NO₃)₃ + NO↑','Fe(NO₃)₂ + NO₂↑','Fe₂O₃ + NO↑'],answer:1,explain:'硝酸过量、铁不足：Fe 被氧化至最高价 Fe³⁺，产物为 Fe(NO₃)₃（稀硝酸还原产物为 NO）：Fe+4HNO₃(稀)=Fe(NO₃)₃+NO↑+2H₂O。注：原文件答案标为 Fe(NO₃)₂，化学上不正确，已按正确结论修正。'},
  {id:'k165',module:'必修一·基本概念',q:'Na₂S 少量溶液与 FeCl₃ 溶液反应，产物正确的是？',options:['2NaCl + 2FeCl₂ + S↓','6NaCl + 2FeS↓ + S↓','FeS↓ + Na₂SO₃','FeCl₂ + Na₂SO₄'],answer:0,explain:'Fe³⁺ 具有氧化性，与 S²⁻ 发生氧化还原而非复分解：2Fe³⁺+S²⁻=2Fe²⁺+S↓，故得 FeCl₂、NaCl 和单质硫沉淀（S²⁻ 不足且 Fe³⁺ 氧化性占主导，得不到 FeS）。'},
  {id:'k166',module:'必修一·基本概念',q:'Na₂S 过量溶液与 FeCl₃ 溶液反应，最终产物为？',options:['2NaCl + 2FeCl₂ + S↓','6NaCl + 2FeS↓ + S↓','FeS + Na₂S','FeCl₃ + S↓'],answer:1,explain:'S²⁻ 过量时：先 2Fe³⁺+S²⁻=2Fe²⁺+S↓，随后过量 S²⁻ 与 Fe²⁺ 结合生成 FeS 沉淀：Fe²⁺+S²⁻=FeS↓，总反应 2FeCl₃+3Na₂S=2FeS↓+S↓+6NaCl。'},
  {id:'k167',module:'必修一·基本概念',q:'AlCl₃ 与氨水反应，过量氨水能否溶解氢氧化铝沉淀？',options:['能','不能'],answer:1,explain:'不能。氨水是弱碱，只能将 Al³⁺ 沉淀为 Al(OH)₃，过量氨水不能溶解 Al(OH)₃（只有强碱 NaOH 等才能溶解）。'},
  {id:'k172',module:'必修一·基本概念',q:'氯水与少量 Na₂SO₃ 溶液反应，生成物为？',options:['2NaCl + H₂SO₄','2NaCl + Na₂SO₄ + SO₂↑','NaCl + SO₂↑ + H₂O','Na₂SO₄ + HCl'],answer:0,explain:'少量 Na₂SO₃ 时，Cl₂ 将其氧化为硫酸盐：Cl₂+Na₂SO₃+H₂O=Na₂SO₄+2HCl（即 2NaCl+H₂SO₄），SO₃²⁻ 不足故无 SO₂ 逸出。'},
  {id:'k173',module:'必修一·基本概念',q:'氯水与过量 Na₂SO₃ 溶液反应，生成物为？',options:['2NaCl + H₂SO₄','2NaCl + Na₂SO₄ + SO₂↑','NaCl + H₂SO₄','Na₂SO₄ + SO₂↑'],answer:1,explain:'过量 Na₂SO₃ 时，Cl₂ 被完全还原为 Cl⁻，氧化 1 mol SO₃²⁻ 为 SO₄²⁻ 的同时生成的酸再与剩余 SO₃²⁻ 反应放出 SO₂：Cl₂+2Na₂SO₃+H₂O=Na₂SO₄+2NaCl+SO₂↑。'},
  {id:'k176',module:'必修一·基本概念',q:'少量 Cl₂ 通入 Na₂CO₃ 溶液，反应产物为？',options:['2NaHCO₃ + NaCl + NaClO','2NaCl + CO₂↑ + 2HClO','NaCl + Na₂CO₃ + HClO','NaHCO₃ + CO₂↑'],answer:0,explain:'少量 Cl₂ 时，Cl₂ 在碱性溶液中歧化：Cl₂+H₂O=HCl+HClO，生成的酸被 CO₃²⁻ 中和生成 HCO₃⁻，产物为 NaCl、NaClO 与 NaHCO₃：2Cl₂+2Na₂CO₃+H₂O=2NaCl+2NaClO+2NaHCO₃。'},
  {id:'k177',module:'必修一·基本概念',q:'过量 Cl₂ 通入 Na₂CO₃ 溶液，反应产物为？',options:['2NaHCO₃ + NaCl + NaClO','2NaCl + CO₂↑ + 2HClO','NaCl + HClO + Na₂CO₃','CO₂↑ + NaHCO₃'],answer:1,explain:'过量 Cl₂ 时溶液酸性增强，Na₂CO₃ 被完全中和为 CO₂：2Cl₂+Na₂CO₃+H₂O=2NaCl+2HClO+CO₂↑，故产物为 NaCl、HClO 与 CO₂。'},
  {id:'k178',module:'必修一·基本概念',q:'Ca(OH)₂ 溶液中加入少量 NaHCO₃，反应产物为？',options:['H₂O + CaCO₃↓ + NaOH','2H₂O + CaCO₃↓ + Na₂CO₃','CaCO₃↓ + NaHCO₃','Na₂CO₃ + H₂O'],answer:0,explain:'少量 NaHCO₃ 时，HCO₃⁻ 与 OH⁻ 反应生成 CO₃²⁻ 和 H₂O，CO₃²⁻ 与 Ca²⁺ 结合成 CaCO₃ 沉淀：Ca(OH)₂+NaHCO₃=CaCO₃↓+NaOH+H₂O。'},
  {id:'k180',module:'必修一·基本概念',q:'Ca(HCO₃)₂ 溶液中加入少量 NaOH，反应产物为？',options:['CaCO₃↓ + NaHCO₃ + H₂O','CaCO₃↓ + Na₂CO₃ + 2H₂O','Na₂CO₃ + H₂O','Ca(HCO₃)₂ + Na₂CO₃'],answer:0,explain:'少量 NaOH 时，仅 1 个 HCO₃⁻ 被 OH⁻ 中和为 CO₃²⁻ 和 H₂O，CO₃²⁻ 立即与 Ca²⁺ 生成 CaCO₃ 沉淀，剩余 HCO₃⁻ 留在溶液中：Ca(HCO₃)₂+NaOH=CaCO₃↓+NaHCO₃+H₂O。'},
  {id:'k181',module:'必修一·基本概念',q:'Ba(OH)₂ 溶液中加入过量 NaHCO₃，反应产物为？',options:['BaCO₃↓ + NaOH + H₂O','BaCO₃↓ + Na₂CO₃ + 2H₂O','Na₂CO₃ + Ba(OH)₂','BaCO₃↓ + NaHCO₃'],answer:1,explain:'过量 NaHCO₃ 时，Ba(OH)₂ 中 2 个 OH⁻ 分别与 2 个 HCO₃⁻ 反应：Ba(OH)₂+2NaHCO₃=BaCO₃↓+Na₂CO₃+2H₂O。'},
  {id:'k182',module:'必修一·基本概念',q:'Ca(OH)₂ 与 Ca(HCO₃)₂ 溶液反应，产物特点为？',options:['少量生成沉淀，过量沉淀溶解','无少量过量区别，只生成 2H₂O + 2CaCO₃↓','过量反应不生成沉淀','少量反应无现象'],answer:1,explain:'二者按 1:1 反应：Ca(OH)₂+Ca(HCO₃)₂=2CaCO₃↓+2H₂O，Ca²⁺ 来自两边、比例固定，无论少量过量产物均为 CaCO₃ 沉淀和水，没有少量过量差异。'},
  {id:'k183',module:'必修一·基本概念',q:'明矾与 Ba(OH)₂ 反应，当 Al³⁺ 恰好完全沉淀时，产物为？',options:['2Al(OH)₃↓ + 3BaSO₄↓ + K₂SO₄','2BaSO₄↓ + KAlO₂ + 2H₂O','BaSO₄↓ + Al(OH)₃↓','K₂SO₄ + BaSO₄↓'],answer:0,explain:'2 mol 明矾含 2 Al³⁺ 与 4 SO₄²⁻；Al³⁺ 完全沉淀需 3 mol Ba(OH)₂（提供 6 OH⁻ 与 3 Ba²⁺），此时 3 个 SO₄²⁻ 沉淀为 BaSO₄，剩 1 个 SO₄²⁻ 与 K⁺ 成 K₂SO₄：2KAl(SO₄)₂+3Ba(OH)₂=2Al(OH)₃↓+3BaSO₄↓+K₂SO₄。'},
  {id:'k184',module:'必修一·基本概念',q:'明矾与 Ba(OH)₂ 反应，当 SO₄²⁻ 恰好完全沉淀时，产物为？',options:['2Al(OH)₃↓ + 3BaSO₄↓ + K₂SO₄','2BaSO₄↓ + KAlO₂ + 2H₂O','Al(OH)₃↓ + BaSO₄↓','KAlO₂ + BaSO₄↓'],answer:1,explain:'SO₄²⁻ 完全沉淀需 Ba²⁺ 等量：2 mol 明矾需 4 mol Ba(OH)₂（提供 4 Ba²⁺ 与 8 OH⁻），8 OH⁻ 将 2 Al³⁺ 全部转化为 AlO₂⁻：2KAl(SO₄)₂+4Ba(OH)₂=4BaSO₄↓+2KAlO₂+4H₂O，化简为 KAl(SO₄)₂+2Ba(OH)₂=2BaSO₄↓+KAlO₂+2H₂O。'},
  {id:'k185',module:'必修一·基本概念',q:'少量 Cl₂ 通入 FeBr₂ 溶液，反应产物为？',options:['2FeCl₃ + 2Br₂','2FeCl₃ + 4FeBr₃','FeCl₂ + Br₂','FeBr₃ + Cl₂'],answer:1,explain:'还原性 Fe²⁺ 强于 Br⁻，少量 Cl₂ 先氧化 Fe²⁺ 而不氧化 Br⁻：6FeBr₂+3Cl₂=2FeCl₃+4FeBr₃（即 Fe²⁺ 全变为 Fe³⁺，Br⁻ 全部保留）。'},
  {id:'k186',module:'必修一·基本概念',q:'过量 Cl₂ 通入 FeBr₂ 溶液，反应产物为？',options:['2FeCl₃ + 2Br₂','2FeCl₃ + 4FeBr₃','FeCl₂ + I₂','FeBr₃ + Br₂'],answer:0,explain:'过量 Cl₂ 时 Fe²⁺ 与 Br⁻ 均被完全氧化：2FeBr₂+3Cl₂=2FeCl₃+2Br₂。'},
  {id:'k187',module:'必修一·基本概念',q:'少量 Cl₂ 通入 FeI₂ 溶液，反应产物为？',options:['FeCl₂ + I₂','2FeCl₃ + 2I₂','FeI₃ + Cl₂','FeCl₃ + I⁻'],answer:0,explain:'还原性 I⁻ 强于 Fe²⁺，少量 Cl₂ 先氧化 I⁻ 而不氧化 Fe²⁺：FeI₂+Cl₂=FeCl₂+I₂。'},
  {id:'k188',module:'必修一·基本概念',q:'过量 Cl₂ 通入 FeI₂ 溶液，反应产物为？',options:['FeCl₂ + I₂','2FeCl₃ + 2I₂','FeCl₃ + I⁻','FeI₃ + Cl₂'],answer:1,explain:'过量 Cl₂ 时 I⁻ 与 Fe²⁺ 均被完全氧化：2FeI₂+3Cl₂=2FeCl₃+2I₂。'},
  {id:'k189',module:'必修一·基本概念',q:'水溶液中 Fe²⁺ 的颜色为？',options:['棕黄色','浅绿色','蓝色','紫红色'],answer:1,explain:'Fe²⁺ 在水溶液中呈浅绿色；Fe³⁺ 才呈棕黄色，Cu²⁺ 呈蓝色，MnO₄⁻ 呈紫红色。'},
  {id:'k190',module:'必修一·基本概念',q:'MnO₄⁻ 在溶液中呈现的颜色是？',options:['橙红色','黄色','紫红色','绿色'],answer:2,explain:'MnO₄⁻（高锰酸根）在水溶液中呈紫红色；Cr₂O₇²⁻ 呈橙红色，CrO₄²⁻ 呈黄色。'},
  {id:'k191',module:'必修一·基本概念',q:'Cr₂O₇²⁻ 的溶液颜色为？',options:['黄色','橙红色','绿色','蓝色'],answer:1,explain:'Cr₂O₇²⁻（重铬酸根）在水溶液中呈橙红色；其共轭碱 CrO₄²⁻ 呈黄色，二者在酸碱中可相互转化。'},
  {id:'k192',module:'必修一·基本概念',q:'实验室用 MnO₂ 与浓盐酸加热制备 Cl₂，该反应中 MnO₂ 的还原产物是？',options:['Mn','MnCl₂','K₂MnO₄','KMnO₄'],answer:1,explain:'MnO₂ 中 Mn 为 +4 价，在反应 MnO₂+4HCl(浓)=MnCl₂+Cl₂↑+2H₂O 中被还原为 Mn²⁺（以 MnCl₂ 形式存在）。'},
  {id:'k193',module:'必修一·基本概念',q:'Cu 和稀硝酸反应，硝酸被还原得到的气体产物为？',options:['NO₂','NO','N₂O','NH₄⁺'],answer:1,explain:'铜与稀硝酸反应：3Cu+8HNO₃(稀)=3Cu(NO₃)₂+2NO↑+4H₂O，硝酸被还原为 NO（无色气体）；与浓硝酸才生成 NO₂。'},
  {id:'k194',module:'必修一·基本概念',q:'在酸性条件下 KI 与 KIO₃ 发生归中反应，生成的氧化还原共同产物是？',options:['K₂SO₄','I₂','KOH','H₂'],answer:1,explain:'酸性下 I⁻（-1）与 IO₃⁻（+5）归中生成 I₂（0）：5KI+KIO₃+3H₂SO₄=3K₂SO₄+3I₂+3H₂O，共同产物为 I₂。'},
  {id:'k195',module:'必修一·基本概念',q:'硫单质和热的强碱溶液发生歧化反应，反应得到的含硫产物是？',options:['K₂S 和 K₂SO₃','K₂SO₄ 和 K₂S','K₂SO₃ 和 K₂SO₄','SO₂ 和 K₂S'],answer:0,explain:'3S+6KOH(热)=2K₂S+K₂SO₃+3H₂O，硫发生歧化：一部分被还原为 S²⁻（K₂S），一部分被氧化为 SO₃²⁻（K₂SO₃）。'},
  {id:'k196',module:'必修一·基本概念',q:'(NH₄)₂Cr₂O₇ 分解反应，铬元素对应的产物为？',options:['Cr³⁺','CrO₄²⁻','Cr₂O₃','Cr'],answer:2,explain:'(NH₄)₂Cr₂O₇ 受热分解：(NH₄)₂Cr₂O₇=Cr₂O₃+N₂↑+4H₂O，Cr 由 +6 价降至 +3 价，产物为 Cr₂O₃（三氧化二铬）。'},
  {id:'k197',module:'必修一·基本概念',q:'Cl₂ 作氧化剂时，对应的还原产物为？',options:['Cl⁻','ClO⁻','Cl₂O','HClO'],answer:0,explain:'Cl₂ 作氧化剂时被还原，氯元素化合价由 0 降为 -1，还原产物为 Cl⁻（如与金属、与 Fe²⁺、与 I⁻/Br⁻ 反应均生成 Cl⁻）。'},
  {id:'k198',module:'必修一·基本概念',q:'Fe²⁺ 作为还原剂，被氧化后的产物是？',options:['Fe','Fe³⁺','Fe₃O₄','Fe(OH)₃'],answer:1,explain:'Fe²⁺ 处于中间价态，作还原剂时被氧化为 Fe³⁺：2Fe²⁺-2e=2Fe³⁺（如被 Cl₂、O₂、HNO₃ 等氧化）。'},
  {id:'k199',module:'必修一·基本概念',q:'酸性环境中 KMnO₄ 作氧化剂，其还原产物为？',options:['MnO₂','MnO₄²⁻','Mn²⁺','Mn'],answer:2,explain:'酸性条件下 MnO₄⁻ 得 5 个电子被还原为 Mn²⁺：MnO₄⁻+8H⁺+5e⁻=Mn²⁺+4H₂O，溶液由紫红褪色为近无色。'},
  {id:'k200',module:'必修一·基本概念',q:'H₂O₂ 作为绿色氧化剂，对应的还原产物是？',options:['O₂','H₂O','OH⁻','H₂'],answer:1,explain:'H₂O₂ 作氧化剂时 O 由 -1 降为 -2，还原产物为 H₂O：H₂O₂+2H⁺+2e⁻=2H₂O。'},
  {id:'k201',module:'必修一·基本概念',q:'稀硝酸作氧化剂时，还原产物为？',options:['NO₂','NO','N₂','NH₄⁺'],answer:1,explain:'稀硝酸作氧化剂通常被还原为 NO（无色）：如 Cu+稀HNO₃→Cu(NO₃)₂+NO↑+H₂O；浓硝酸才主要生成 NO₂。'},
  {id:'k202',module:'必修一·基本概念',q:'CrO₄²⁻ 在溶液中显黄色，这一说法是否正确？',options:['是','否'],answer:0,explain:'是。CrO₄²⁻（铬酸根）在水溶液中呈黄色；Cr₂O₇²⁻ 则呈橙红色，二者在酸碱中可相互转化。'},
  {id:'k203',module:'必修一·基本概念',q:'Cu²⁺ 在水溶液中为棕黄色，这一说法是否正确？',options:['是','否'],answer:1,explain:'否。Cu²⁺ 在水溶液中呈蓝色（如 CuSO₄ 溶液为蓝色），棕黄色是 Fe³⁺ 的特征颜色。'},
  {id:'k204',module:'必修一·基本概念',q:'H₂O₂ 只能作氧化剂，不能作还原剂，这一说法是否正确？',options:['能','不能'],answer:1,explain:'不能。H₂O₂ 中 O 为 -1 价（中间价态），既可作氧化剂（被还原为 H₂O），也可作还原剂（被氧化为 O₂），例如遇强氧化剂 KMnO₄ 时显还原性。'},
  {id:'k205',module:'必修一·基本概念',q:'浓 H₂SO₄ 做氧化剂时，还原产物可以为 SO₂，这一说法是否正确？',options:['是','否'],answer:0,explain:'是。浓硫酸中 S 为 +6 价，作氧化剂时通常被还原为 SO₂（S 降至 +4），如与 Cu、C 等反应均生成 SO₂。'},
  {id:'k206',module:'必修一·基本概念',q:'阿伏加德罗常数的近似值为？',options:['6.02×10²³','6.02×10²³ mol⁻¹','22.4 L·mol⁻¹','12 g'],answer:1,explain:'阿伏加德罗常数 N_A ≈ 6.02×10²³ mol⁻¹，单位是 mol⁻¹，不是纯数。'},
  {id:'k208',module:'必修一·基本概念',q:'物质的量 n、质量 m、摩尔质量 M 三者关系式正确的是？',options:['n = m·M','n = m / M','n = M / m','m = n / M'],answer:1,explain:'质量 m = 物质的量 n × 摩尔质量 M，移项可得 n = m / M。'},
  {id:'k210',module:'必修一·基本概念',q:'标准状况下，气体摩尔体积 V_m 约为？',options:['22.4 L','22.4 L·mol⁻¹','6.02×10²³ mol⁻¹','1 mol'],answer:1,explain:'标准状况下气体摩尔体积 V_m ≈ 22.4 L·mol⁻¹，必须带单位 mol⁻¹。'},
  {id:'k211',module:'必修一·基本概念',q:'气体体积 V、物质的量 n、气体摩尔体积 V_m 三者关系式正确的是？',options:['V = n·V_m','V = n / V_m','V = V_m / n','V = n + V_m'],answer:0,explain:'V = n·V_m，由此可推导 n = V / V_m。'},
  {id:'k214',module:'必修一·基本概念',q:'已知粒子数之比等于物质的量之比，则 N₁ : N₂ 等于？',options:['n₂ : n₁','n₁ : n₂','M₁ : M₂','V₁ : V₂'],answer:1,explain:'N₁/N₂ = n₁/n₂，故 N₁ : N₂ = n₁ : n₂。'},
  {id:'k215',module:'必修一·基本概念',q:'关于金属钠的物理性质，正确的是？',options:['密度比水大','熔点很高','银白色柔软金属，密度 0.97 g/cm³（比水小、比煤油大）','热和电的不良导体'],answer:2,explain:'钠软、银白、密度 0.97 介于水与煤油之间，是热和电的良导体，熔点较低。'},
  {id:'k216',module:'必修一·基本概念',q:'实验室中金属钠通常保存在？',options:['蒸馏水中','煤油或石蜡油中','敞口广口瓶','酒精中'],answer:1,explain:'钠与水、空气都反应；其密度 0.97 比煤油大，沉于煤油下可隔绝空气，故存于煤油/石蜡油；剩余钠放回原瓶。'},
  {id:'k217',module:'必修一·基本概念',q:'常温下钠在空气中缓慢氧化，产物与现象是？',options:['Na₂O₂（淡黄色）','Na₂O（白色固体，新切面变暗）','NaOH','Na₂CO₃'],answer:1,explain:'4Na+O₂=2Na₂O，白色固体使新切开面变暗。'},
  {id:'k218',module:'必修一·基本概念',q:'钠在空气中加热燃烧，现象与产物是？',options:['黄色火焰，生成淡黄色 Na₂O₂ 固体','苍白色火焰','生成白色 Na₂O','火星四射'],answer:0,explain:'2Na+O₂ △ Na₂O₂，黄色火焰、淡黄色固体。'},
  {id:'k219',module:'必修一·基本概念',q:'将一小块钠投入 CuSO₄ 溶液中，正确的是？',options:['直接置换出金属 Cu','先与水生成 NaOH 和 H₂，再与 CuSO₄ 生成蓝色 Cu(OH)₂ 沉淀','无明显现象','生成红色 Cu'],answer:1,explain:'钠先与水反应，产物 NaOH 再与 CuSO₄ 复分解：2Na+2H₂O+CuSO₄=Na₂SO₄+Cu(OH)₂↓+H₂↑。'},
  {id:'k220',module:'必修一·基本概念',q:'Na₂O 与 Na₂O₂ 的颜色，正确的是？',options:['都是白色','都是淡黄色','Na₂O 白色、Na₂O₂ 淡黄色','Na₂O 淡黄色、Na₂O₂ 白色'],answer:2,explain:'氧化钠白色固体，过氧化钠淡黄色固体。'},
  {id:'k221',module:'必修一·基本概念',q:'Na₂O₂ 与水反应的产物是？',options:['只有 NaOH','NaOH 和 O₂','Na₂CO₃','Na 和 O₂'],answer:1,explain:'2Na₂O₂+2H₂O=4NaOH+O₂↑。'},
  {id:'k222',module:'必修一·基本概念',q:'Na₂O₂ 与 CO₂ 反应的产物是？',options:['只有 Na₂CO₃','Na₂CO₃ 和 O₂','NaHCO₃','Na₂O 和 CO₂'],answer:1,explain:'2Na₂O₂+2CO₂=2Na₂CO₃+O₂，故 Na₂O₂ 可作供氧剂。'},
  {id:'k223',module:'必修一·基本概念',q:'Na₂O₂ 中氧元素的化合价是？',options:['−2','−1','0','+1'],answer:1,explain:'过氧根 O₂²⁻ 中氧为 −1 价（Na₂O 中才是 −2）。'},
  {id:'k224',module:'必修一·基本概念',q:'关于 Na₂CO₃ 与 NaHCO₃ 的热稳定性，正确的是？',options:['NaHCO₃ 稳定不分解','2NaHCO₃ 加热分解为 Na₂CO₃+CO₂+H₂O','Na₂CO₃ 受热分解','二者都不分解'],answer:1,explain:'NaHCO₃ 受热易分解，Na₂CO₃ 稳定。'},
  {id:'k225',module:'必修一·基本概念',q:'鉴别 Na₂CO₃ 与 NaHCO₃，不可行的是？',options:['加热看是否放出 CO₂','加同浓度盐酸看气泡快慢','加 BaCl₂ 看是否沉淀','加 NaOH 溶液'],answer:3,explain:'加热（小苏打分解）、盐酸（小苏打气泡更快）、BaCl₂（碳酸钠生成 BaCO₃ 沉淀）均可鉴别；加 NaOH 二者均无明显区别，不能鉴别。'},
  {id:'k226',module:'必修一·基本概念',q:'除去 Na₂CO₃ 固体中混有的少量 NaHCO₃，方法是？',options:['加盐酸','加热','加 NaOH','通入 CO₂'],answer:1,explain:'2NaHCO₃ △ Na₂CO₃+CO₂↑+H₂O，杂质转化为目标物。'},
  {id:'k227',module:'必修一·基本概念',q:'侯氏制碱法中，向饱和食盐水中通气的顺序是？',options:['先通 CO₂ 再通 NH₃','先通 NH₃ 再通 CO₂','同时通入','先通 HCl 再通 NH₃'],answer:1,explain:'先通 NH₃ 使溶液呈碱性，能吸收更多 CO₂，再通 CO₂ 使 NaHCO₃（溶解度较小）析出；若先通 CO₂ 因其溶解度小吸收少。'},
  {id:'k228',module:'必修一·基本概念',q:'碱金属元素在周期表中的位置是？',options:['第 IA 族','第 IIA 族','第 VIIA 族','第 0 族'],answer:0,explain:'碱金属（Li、Na、K、Rb、Cs）均在第 IA 族，最外层 1 个电子。'},
  {id:'k229',module:'必修一·基本概念',q:'关于碱金属单质物理性质的递变，正确的是？',options:['从 Li 到 Cs 密度一直增大','熔沸点逐渐升高','ρ(Na)＞ρ(K)（反常）','都是金黄色'],answer:2,explain:'密度总体增大但 Na＞K 反常；熔沸点降低；Cs 略带金色光泽，其余银白。'},
  {id:'k230',module:'必修一·基本概念',q:'锂（Li）与氧气反应，无论常温还是加热，产物是？',options:['Li₂O','Li₂O₂','KO₂','LiO₂'],answer:0,explain:'Li 与 O₂ 只能生成 Li₂O；Na 可生成 Na₂O₂；K 可生成 KO₂。'},
  {id:'k231',module:'必修一·基本概念',q:'关于碱金属性质的递变，正确的是？',options:['从 Li 到 Cs 金属性减弱','CsOH 碱性最强','还原性减弱','原子半径减小'],answer:1,explain:'从 Li 到 Cs 原子半径增大、金属性/还原性增强、最高价氢氧化物碱性增强（CsOH 最强）。'},
  {id:'k232',module:'必修一·基本概念',q:'下列俗称对应正确的是？',options:['碳酸氢钠—纯碱','碳酸钠—小苏打','氢氧化钠—烧碱、火碱、苛性钠','硫代硫酸钠—明矾'],answer:2,explain:'纯碱/苏打是 Na₂CO₃，小苏打是 NaHCO₃，明矾是 KAl(SO₄)₂·12H₂O；大苏打/海波才是 Na₂S₂O₃·5H₂O。'},
  {id:'k233',module:'必修一·基本概念',q:'将 a g H₂ 在 O₂ 中完全燃烧，产物通过足量 Na₂O₂ 固体，Na₂O₂ 增重为？',options:['a g','大于 a g','小于 a g','0'],answer:0,explain:'2H₂O+2Na₂O₂=4NaOH+O₂，净增重恰为 H₂ 的质量 a g；凡符合 (CO)ₘ(H₂)ₙ 的物质增重均等于原质量。'},
  {id:'k234',module:'必修一·基本概念',q:'关于 Cl₂ 的物理性质，正确的是？',options:['黄绿色、有刺激性气味、有毒','无色无味','密度比空气小','难溶于水'],answer:0,explain:'Cl₂ 黄绿色、刺激性、有毒，密度比空气大，1 体积水约溶 2 体积 Cl₂。'},
  {id:'k235',module:'必修一·基本概念',q:'铁丝在 Cl₂ 中燃烧，现象与产物是？',options:['苍白色火焰、生成 HCl','棕黄色烟、生成 FeCl₃','剧烈爆炸','白色烟（NaCl）'],answer:1,explain:'2Fe+3Cl₂ 点燃 2FeCl₃，变价金属 Fe 被 Cl₂ 氧化到 +3，棕黄色烟。'},
  {id:'k236',module:'必修一·基本概念',q:'铜丝在 Cl₂ 中燃烧，产物是？',options:['CuCl','CuCl₂','Cu₂Cl','CuO'],answer:1,explain:'Cu+Cl₂ 点燃 CuCl₂，棕黄色烟。'},
  {id:'k237',module:'必修一·基本概念',q:'H₂ 在 Cl₂ 中点燃燃烧的现象是？',options:['苍白色火焰、瓶口有白雾','剧烈爆炸','黄色火焰','蓝色火焰'],answer:0,explain:'H₂ 在 Cl₂ 中安静燃烧，苍白色火焰，HCl 遇水蒸气成白雾；光照混合气才爆炸。'},
  {id:'k238',module:'必修一·基本概念',q:'关于卤素单质物理性质的递变，正确的是？',options:['从 F₂ 到 I₂ 颜色变浅','熔沸点降低','密度增大、水中溶解度减小','都是气体'],answer:2,explain:'F₂ 淡黄绿气体→Cl₂ 黄绿气体→Br₂ 深红棕液体→I₂ 紫黑固体，颜色加深、熔沸点升高、密度增大、水中溶解度减小。'},
  {id:'k239',module:'必修一·基本概念',q:'关于卤族元素性质的递变，正确的是？',options:['从 F 到 I 单质氧化性增强','卤离子还原性减弱','HF 稳定性最弱','HClO₄ 是已知含氧酸中酸性最强的'],answer:3,explain:'从 F 到 I 氧化性减弱、卤离子还原性增强、氢化物稳定性减弱；HClO₄ 酸性最强。'},
  {id:'k240',module:'必修一·基本概念',q:'关于氟元素，正确的是？',options:['F 有 +7 最高正价','F₂ 氧化性最强','HF 最不稳定','F₂ 与水反应生成 O₂'],answer:1,explain:'F 无正价；F₂ 氧化性最强；HF 最稳定；2F₂+2H₂O=4HF+O₂。'},
  {id:'k241',module:'必修一·基本概念',q:'新制氯水中含有的分子（包括水）是？',options:['Cl₂、HClO','Cl₂、H₂O、HClO','H⁺、Cl⁻、ClO⁻','Cl₂、NaCl'],answer:1,explain:'Cl₂+H₂O⇌HCl+HClO，三种分子为 Cl₂、H₂O、HClO；四种离子为 H⁺、Cl⁻、ClO⁻、OH⁻（极少量）。'},
  {id:'k242',module:'必修一·基本概念',q:'向氯水中滴加紫色石蕊试液，现象是？',options:['变红不褪','先变红后褪色','变蓝','不变色'],answer:1,explain:'H⁺ 使石蕊变红，HClO 强氧化性使红色褪去。'},
  {id:'k243',module:'必修一·基本概念',q:'检验氯水中的 Cl⁻，可加入？',options:['AgNO₃ 溶液（白色沉淀）','BaCl₂','淀粉-KI','酚酞'],answer:0,explain:'Cl⁻+Ag⁺=AgCl↓ 白色沉淀。'},
  {id:'k244',module:'必修一·基本概念',q:'铁粉与硫粉混合加热，产物是？',options:['Fe₂S₃','FeS','FeS₂','Fe₃S₄'],answer:1,explain:'Fe+S △ FeS，S 氧化性弱只能将 Fe 氧化到 +2。'},
  {id:'k245',module:'必修一·基本概念',q:'常温下，铁遇冷的浓硫酸、浓硝酸会发生？',options:['完全溶解','钝化（表面形成致密氧化膜）','不反应','爆炸'],answer:1,explain:'冷浓硫酸/浓硝酸使 Fe、Al 钝化，表面氧化成致密膜阻止进一步反应（加热可反应）。'},
  {id:'k246',module:'必修一·基本概念',q:'铁与水蒸气在高温下反应的产物是？',options:['Fe(OH)₂+H₂','Fe₃O₄+H₂','Fe₂O₃+H₂','FeO+H₂'],answer:1,explain:'3Fe+4H₂O(g) 高温 Fe₃O₄+4H₂。'},
  {id:'k247',module:'必修一·基本概念',q:'下列关于铁的氧化物，说法正确的是？',options:['FeO 红棕色','Fe₂O₃ 黑色','Fe₃O₄ 俗称磁性氧化铁、有磁性','FeO 很稳定'],answer:2,explain:'FeO 黑色、Fe₂O₃ 红棕色（铁红）、Fe₃O₄ 黑色晶体有磁性；FeO 不稳定易氧化为 Fe₃O₄。'},
  {id:'k248',module:'必修一·基本概念',q:'Fe₃O₄ 溶于盐酸，生成的金属阳离子是？',options:['只有 Fe²⁺','只有 Fe³⁺','Fe²⁺ 和 Fe³⁺','Fe'],answer:2,explain:'Fe₃O₄+8HCl=FeCl₂+2FeCl₃+4H₂O，含 +2、+3 价铁。'},
  {id:'k249',module:'必修一·基本概念',q:'Fe(OH)₂ 在空气中被氧化的特征现象是？',options:['白色直接变黑','白色迅速变灰绿色、最终变红褐色','红褐色变白色','不变色'],answer:1,explain:'4Fe(OH)₂+O₂+2H₂O=4Fe(OH)₃，现象白→灰绿→红褐。'},
  {id:'k250',module:'必修一·基本概念',q:'检验 Fe³⁺ 常用的试剂是？',options:['KSCN 溶液（血红色）','淀粉-KI','铁氰化钾','酚酞'],answer:0,explain:'Fe³⁺+3SCN⁻=Fe(SCN)₃ 血红色；铁氰化钾检验 Fe²⁺。'},
  {id:'k251',module:'必修一·基本概念',q:'检验 Fe²⁺，加入铁氰化钾 K₃[Fe(CN)₆] 溶液，现象是？',options:['血红色','蓝色沉淀','白色沉淀','无明显'],answer:1,explain:'3Fe²⁺+2[Fe(CN)₆]³⁻=Fe₃[Fe(CN)₆]₂↓ 蓝色沉淀（滕氏蓝）。'},
  {id:'k252',module:'必修一·基本概念',q:'制备 Fe(OH)₃ 胶体，方法是？',options:['FeCl₃ 溶液加 NaOH','饱和 FeCl₃ 溶液滴入沸水','Fe(OH)₃ 加盐酸','Fe₂O₃ 加水'],answer:1,explain:'FeCl₃+3H₂O(沸水)=Fe(OH)₃(胶体)+3HCl。'},
  {id:'k253',module:'必修一·基本概念',q:'镁条在 CO₂ 中点燃，反应与产物是？',options:['2Mg+CO₂ 点燃 2MgO+C','MgO+C（不反应）','生成 MgCO₃','不反应'],answer:0,explain:'2Mg+CO₂ 点燃 2MgO+C，剧烈燃烧生成白色粉末（MgO）和黑色固体（C）。'},
  {id:'k254',module:'必修一·基本概念',q:'镁与氮气反应的产物是？',options:['Mg₃N₂','MgN₂','Mg(NO₃)₂','Mg(NO₂)₂'],answer:0,explain:'3Mg+N₂ 点燃 Mg₃N₂。'},
  {id:'k255',module:'必修一·基本概念',q:'下列关于 MgO 的叙述，正确的是？',options:['易溶于水','熔点低','白色固体、难溶、熔点高、作耐火材料','是一种酸'],answer:2,explain:'MgO 白色难溶、熔点高，是优良耐火材料；缓慢与水生成 Mg(OH)₂。'},
  {id:'k256',module:'必修一·基本概念',q:'铝热剂是指？',options:['铝粉与某些金属氧化物的混合物','铝与水的混合物','铝与酸','纯铝粉'],answer:0,explain:'铝粉与 Fe₂O₃、Cr₂O₃、V₂O₅ 等金属氧化物混合成铝热剂，Al 作还原剂。'},
  {id:'k257',module:'必修一·基本概念',q:'关于合金的性质，正确的是？',options:['合金熔点比各成分金属都高','合金硬度一般比各成分金属大','合金都是化合物','合金不能导电'],answer:1,explain:'多数合金熔点比成分金属低、硬度更大；具有金属特性（能导电）。'},
  {id:'k258',module:'必修一·基本概念',q:'下列金属的冶炼适合用热分解法的是？',options:['Na','Fe','Hg、Ag','Al'],answer:2,explain:'不活泼金属 Hg、Ag 氧化物受热分解（2HgO △ 2Hg+O₂↑）；Na/Al 用电解，Fe 用热还原。'},
  {id:'k259',module:'必修一·基本概念',q:'冶炼活泼金属 K、Na、Mg、Al，采用的方法是？',options:['热分解','热还原','电解熔融盐/氧化物','物理提取'],answer:2,explain:'K~Al 还原性强、阳离子氧化性弱，用电解熔融化合物（如 2NaCl(熔) 电解 2Na+Cl₂↑）。'},
  {id:'k260',module:'必修一·基本概念',q:'用铝热法冶炼金属，利用的是？',options:['Al 的还原性','Al 的氧化性','Al 的两性','Al 的导电性'],answer:0,explain:'铝热反应中 Al 作还原剂，将氧化物中的金属（如 Cr、V、Mn）置换出来。'},
  {id:'k261',module:'必修一·基本概念',q:'铜与浓硝酸反应的产物是？',options:['NO','NO₂','N₂O','NH₃'],answer:1,explain:'Cu+4HNO₃(浓)=Cu(NO₃)₂+2NO₂↑+2H₂O。'},
  {id:'k262',module:'必修一·基本概念',q:'铜与浓硫酸共热的产物是？',options:['SO₂','H₂S','S','SO₃'],answer:0,explain:'Cu+2H₂SO₄(浓) △ CuSO₄+SO₂↑+2H₂O。'},
  {id:'k263',module:'必修一·基本概念',q:'无水 CuSO₄ 为白色粉末，遇水变蓝，可用于？',options:['检验水的存在','检验 CO₂','消毒','漂白'],answer:0,explain:'无水 CuSO₄ 遇水生成蓝色 CuSO₄·5H₂O，可检验水（如检验酒精是否含水）。'},
  {id:'k264',module:'必修一·基本概念',q:'铜在潮湿空气中生锈生成的铜绿，主要成分是？',options:['CuO','Cu(OH)₂','Cu₂(OH)₂CO₃','CuS'],answer:2,explain:'2Cu+O₂+CO₂+H₂O=Cu₂(OH)₂CO₃（碱式碳酸铜，绿色）。'},
  {id:'k265',module:'必修二',q:'若某原子的质量数为 A、质子数为 Z，则中子数 N 为？',options:['A+Z','A−Z','Z−A','A×Z'],answer:1,explain:'质量数 A=质子数 Z+中子数 N，故 N=A−Z。'},
  {id:'k266',module:'必修二',q:'某阳离子 Rⁿ⁺ 质子数为 Z，其核外电子数为？',options:['Z+n','Z−n','Z','n'],answer:1,explain:'阳离子失电子，核外电子数=质子数−电荷数=Z−n（阴离子为 Z+n）。'},
  {id:'k267',module:'必修二',q:'同周期主族元素从左到右（稀有气体除外），原子半径变化是？',options:['逐渐增大','逐渐减小','不变','先增后减'],answer:1,explain:'同周期核电荷数增大，原子半径减小（稀有气体反常）。'},
  {id:'k268',module:'必修二',q:'同主族元素从上到下，金属性的变化是？',options:['增强','减弱','不变','先强后弱'],answer:0,explain:'同主族自上而下原子半径增大、失电子能力增强，金属性增强、非金属性减弱。'},
  {id:'k269',module:'必修二',q:'同周期主族元素从左到右，最高价氧化物对应水化物的酸性变化是？',options:['逐渐增强','逐渐减弱','不变','先强后弱'],answer:0,explain:'同周期非金属性增强，最高价含氧酸酸性增强（如 HClO₄ 最强）。'},
  {id:'k270',module:'必修一·基本概念',q:'除去 N₂ 中混有的少量 O₂，可采用的方法是？',options:['通过灼热的铜网','通入 NaOH','通入水','点燃'],answer:0,explain:'2Cu+O₂ △ 2CuO，灼热铜网吸收 O₂，N₂ 不反应。'},
  {id:'k271',module:'必修一·基本概念',q:'除去 CO 中混有的 CO₂，试剂是？',options:['灼热的 CuO','NaOH 溶液','浓硫酸','饱和食盐水'],answer:1,explain:'CO₂+2NaOH=Na₂CO₃+H₂O，NaOH 吸收 CO₂ 而 CO 不反应，洗气。'},
  {id:'k272',module:'必修一·基本概念',q:'除去 CO₂ 中混有的少量 CO，应采用的方法是？',options:['通入 NaOH','通过灼热的 CuO','通入水','加 Ca(OH)₂'],answer:1,explain:'CO+CuO △ Cu+CO₂，用固体 CuO 将 CO 转化为 CO₂；CO₂ 不被 CuO 还原。'},
  {id:'k273',module:'必修一·基本概念',q:'除去 H₂ 中混有的 NH₃，可用？',options:['浓硫酸','饱和食盐水','NaOH','水'],answer:0,explain:'NH₃ 被浓硫酸吸收（生成铵盐），H₂ 不反应；H₂ 不能用碱吸收。'},
  {id:'k274',module:'必修二',q:'铜粉与硫粉共热，生成的黑色固体是？',options:['CuS','CuSO₄','CuO','Cu₂S'],answer:3,explain:'硫的氧化性较弱，与铜反应只能将铜氧化为+1价，生成 Cu₂S（黑色固体，不溶于水）。'},
  {id:'k275',module:'必修二',q:'实验室不慎洒落少量汞，正确的处理方法是？',options:['撒上硫粉','用大量水冲洗','用扫帚清扫','用稀盐酸处理'],answer:0,explain:'Hg + S = HgS，汞蒸气有毒，撒硫粉可将其转化为无毒硫化汞。'},
  {id:'k276',module:'必修二',q:'下列反应中，硫单质表现出氧化性（硫得电子、化合价降低）的是？',options:['2Na + S = Na₂S','S + O₂ = SO₂','S + 2H₂SO₄(浓) = 3SO₂ + 2H₂O','3S + 6NaOH = 2Na₂S + Na₂SO₃ + 3H₂O'],answer:0,explain:'2Na + S = Na₂S 中 S 由 0 价降到 −2 价，作氧化剂表现氧化性；S 与 O₂、与浓 H₂SO₄ 的反应中 S 被氧化；S 与 NaOH 的反应为歧化（既氧化又还原）。'},
  {id:'k277',module:'必修二',q:'制取 Al₂S₃ 的唯一途径是？',options:['硫酸铝与硫化钠溶液复分解','氯化铝与硫化氢反应','铝粉与硫共热','氧化铝与硫反应'],answer:2,explain:'Al₂S₃ 遇水会水解，不能用复分解法制取，只能通过 2Al + 3S = Al₂S₃ 直接化合（这也是制 Al₂S₃ 的唯一途径）。'},
  {id:'k279',module:'必修二',q:'硫与热的浓氢氧化钠溶液反应：3S + 6NaOH = 2Na₂S + Na₂SO₃ + 3H₂O，硫在此反应中的作用是？',options:['只作氧化剂','既作氧化剂又作还原剂','只作还原剂','既非氧化剂也非还原剂'],answer:1,explain:'S 一部分由 0 价降到 −2 价（Na₂S），一部分升到 +4 价（Na₂SO₃），属歧化反应。'},
  {id:'k280',module:'必修二',q:'下列反应中硫体现还原性（硫被氧化）的是？',options:['Fe + S = FeS','2Al + 3S = Al₂S₃','Hg + S = HgS','S + 2H₂SO₄(浓) = 3SO₂ + 2H₂O'],answer:3,explain:'S 与浓 H₂SO₄ 反应时 S 由 0 价升高到 +4 价（生成 SO₂），体现还原性；其余反应（与 Fe、Al、Hg 化合）中 S 得电子表现氧化性。'},
  {id:'k282',module:'必修二',q:'将 SO₂ 通入紫色石蕊试液中，观察到的现象是？',options:['溶液褪色','溶液先变红后褪色','溶液变红','无明显现象'],answer:2,explain:'SO₂ 是酸性氧化物，溶于水生成亚硫酸使石蕊变红；SO₂ 不能漂白石蕊，故只变红不褪色。'},
  {id:'k283',module:'必修二',q:'向 NaOH 溶液中通入过量 SO₂，主要产物是？',options:['Na₂SO₃','NaHSO₃','Na₂SO₄','Na₂S'],answer:1,explain:'SO₂少量时 2NaOH + SO₂ = Na₂SO₃ + H₂O；SO₂过量时 NaOH + SO₂ = NaHSO₃。'},
  {id:'k284',module:'必修二',q:'除去 CO₂ 中混有的少量 SO₂，可选用的试剂是？',options:['饱和 Na₂CO₃ 溶液','澄清石灰水','BaCl₂ 溶液','饱和 NaHCO₃ 溶液'],answer:3,explain:'饱和 NaHCO₃ 与 SO₂ 反应 SO₂ + NaHCO₃ = NaHSO₃ + CO₂，既除 SO₂ 又生成 CO₂；CO₂ 不与 NaHCO₃ 反应。'},
  {id:'k285',module:'必修二',q:'将 SO₂ 通入 BaCl₂ 溶液中未见沉淀，原因是？',options:['SO₂ 不溶于水','BaSO₃ 可溶于水','弱酸不能制强酸','反应生成可溶物'],answer:2,explain:'亚硫酸（H₂SO₃）酸性弱于盐酸，违背“弱酸不能制强酸”，故 SO₂ 与 BaCl₂ 不反应。'},
  {id:'k286',module:'必修二',q:'下列现象中，能同时体现 SO₂ 的还原性的是？',options:['SO₂ 使品红褪色','SO₂ 使石蕊变红','SO₂ 使溴水褪色（SO₂ + Br₂ + 2H₂O = H₂SO₄ + 2HBr）','SO₂ 作漂白剂'],answer:2,explain:'SO₂ 使溴水褪色（S 由 +4 升高到 +6 被氧化）体现还原性；使品红褪色、作漂白剂体现的是漂白性；使石蕊变红体现的是酸性。'},
  {id:'k295',module:'必修二',q:'常温下可用铁制或铝制容器盛装浓硫酸，原因是？',options:['常温下发生钝化形成致密氧化膜','铁、铝与浓硫酸不反应','浓硫酸浓度低','铁、铝为惰性金属'],answer:0,explain:'常温下铁、铝被浓硫酸氧化形成致密氧化膜（钝化，化学变化），阻止内层金属进一步反应。'},
  {id:'k296',module:'必修二',q:'1 mol Cu 与含 2 mol H₂SO₄ 的浓硫酸充分反应，生成 SO₂ 的物质的量？',options:['等于 1 mol','大于 1 mol','等于 2 mol','小于 1 mol'],answer:3,explain:'随反应进行硫酸变稀，稀硫酸不与 Cu 反应，故 SO₂ 小于理论值 1 mol。'},
  {id:'k297',module:'必修二',q:'锌与浓硫酸反应，开始时产生 SO₂，后来产生 H₂，原因是？',options:['锌过量','温度升高','硫酸浓度变小后表现酸性生成 H₂','锌被氧化'],answer:2,explain:'浓时还原产物为 SO₂；变稀后稀硫酸与 Zn 反应放出 H₂。'},
  {id:'k298',module:'必修二',q:'浓硫酸与铁共热：2Fe + 6H₂SO₄(浓) = Fe₂(SO₄)₃ + 3SO₂↑ + 6H₂O，还原产物是？',options:['Fe₂(SO₄)₃','H₂O','SO₂','Fe'],answer:2,explain:'S 由 +6 降到 +4，SO₂ 为还原产物。'},
  {id:'k299',module:'必修二',q:'检验溶液中是否含有 SO₄²⁻，正确的操作是？',options:['直接滴加 BaCl₂ 溶液','先加 AgNO₃ 溶液','先加 Ba(NO₃)₂ 溶液','先加稀盐酸酸化，无现象后再加 BaCl₂'],answer:3,explain:'先加 HCl 排除 CO₃²⁻、SO₃²⁻、Ag⁺ 等干扰（酸化无沉淀无气体），再加 BaCl₂ 看白色沉淀。'},
  {id:'k300',module:'必修二',q:'若不加稀盐酸直接加 BaCl₂，可能导致误检的离子是？',options:['Na⁺','CO₃²⁻','Cl⁻','K⁺'],answer:1,explain:'CO₃²⁻ 也会与 Ba²⁺ 生成 BaCO₃ 白色沉淀，造成假阳性。'},
  {id:'k301',module:'必修二',q:'关于 H₂S 的物理性质，正确的是？',options:['无色无味','密度比空气小','有臭鸡蛋气味、剧毒','不溶于水'],answer:2,explain:'H₂S 为无色、有臭鸡蛋气味的剧毒气体，密度比空气大，能溶于水（约 1:2.6）。'},
  {id:'k302',module:'必修二',q:'H₂S 与 Cl₂ 反应：H₂S + Cl₂ = S↓ + 2HCl，该反应中 H₂S 表现？',options:['氧化性','还原性','酸性','漂白性'],answer:1,explain:'S 由 −2 升到 0 被氧化，H₂S 作还原剂。'},
  {id:'k303',module:'必修二',q:'H₂S 在少量 O₂ 中燃烧：2H₂S + O₂(少量) = 2H₂O + 2S，该反应的产物是？',options:['SO₂','SO₃','S 和 H₂O','H₂S'],answer:2,explain:'氧气少量时 H₂S 不完全燃烧生成 S 和 H₂O；氧气过量才生成 SO₂。'},
  {id:'k308',module:'必修二',q:'常温下 N₂ 化学性质很稳定，主要原因是？',options:['氮原子半径大','氮气密度小','氮的非金属性弱','N≡N 键键能很大'],answer:3,explain:'N₂ 分子中存在 N≡N 三键，键能很大，难断裂，故常温下稳定。'},
  {id:'k309',module:'必修二',q:'下列反应在闪电或汽车引擎中发生的是？',options:['N₂ + 3H₂ = 2NH₃','3Mg + N₂ = Mg₃N₂','N₂ + O₂ = 2NO','2NO + O₂ = 2NO₂'],answer:2,explain:'放电或高温下 N₂ 与 O₂ 化合生成 NO（闪电固氮、汽车引擎）。'},
  {id:'k310',module:'必修二',q:'氮化镁与水反应：Mg₃N₂ + 6H₂O = 3Mg(OH)₂ + 2NH₃↑，该反应属于？',options:['水解反应','氧化还原反应','置换反应','分解反应'],answer:0,explain:'金属氮化物易水解，生成氨气和相应的碱，属水解反应（各元素化合价不变，非氧化还原）。'},
  {id:'k311',module:'必修二',q:'3Mg + N₂ = Mg₃N₂ 中，N₂ 表现？',options:['还原性','酸性','氧化性','漂白性'],answer:2,explain:'N 由 0 价降到 −3 价，N₂ 作氧化剂。'},
  {id:'k312',module:'必修二',q:'关于 NO 的物理性质，正确的是？',options:['无色、无味、有毒、难溶于水','红棕色','易溶于水','有刺激性气味'],answer:0,explain:'NO 是无色无味有毒气体，难溶于水，只能用排水法收集。'},
  {id:'k313',module:'必修二',q:'实验室用 Cu 与稀 HNO₃ 制取 NO，收集 NO 只能用？',options:['排空气法','排水法','向上排空气法','向下排空气法'],answer:1,explain:'NO 与 O₂ 迅速反应生成 NO₂，故不能用排空气法，只能用排水法。'},
  {id:'k315',module:'必修二',q:'NO 与酸性 KMnO₄ 反应被氧化为 NO₃⁻，体现 NO 的？',options:['氧化性','酸性','漂白性','还原性'],answer:3,explain:'N 由 +2 升高到 +5，NO 作还原剂。'},
  {id:'k316',module:'必修二',q:'关于 NO₂ 的物理性质，正确的是？',options:['无色气体','无色无味','密度比空气小','红棕色、有刺激性气味、有毒'],answer:3,explain:'NO₂ 是红棕色有刺激性气味的有毒气体，易溶于水且与水和反应。'},
  {id:'k317',module:'必修二',q:'实验室用 Cu 与浓 HNO₃ 制 NO₂，收集只能用？',options:['排水法','排空气法','向下排空气法','排饱和食盐水'],answer:1,explain:'NO₂ 与水反应（3NO₂ + H₂O = 2HNO₃ + NO），不能用排水法，用向上排空气法。'},
  {id:'k318',module:'必修二',q:'NO₂ 与水反应：3NO₂ + H₂O = 2HNO₃ + NO，NO₂ 的作用是？',options:['只作氧化剂','只作还原剂','既作氧化剂又作还原剂','只作酸'],answer:2,explain:'N 由 +4 歧化为 +5（HNO₃）和 +2（NO）。'},
  {id:'k319',module:'必修二',q:'NO₂ 能使湿润的淀粉-KI 试纸变蓝，是因为 NO₂ 将 I⁻ 氧化为？',options:['I⁻','I₂','HI','IO₃⁻'],answer:1,explain:'NO₂ 氧化 I⁻ 生成 I₂，遇淀粉显蓝色。'},
  {id:'k320',module:'必修二',q:'关于氨气的物理性质，错误的是？',options:['无色、有刺激性气味','密度比空气小','密度比空气大','极易溶于水（约 1:700）'],answer:2,explain:'NH₃ 密度比空气小（分子量 17 < 29），D 错误。'},
  {id:'k321',module:'必修二',q:'氨水呈弱碱性，能使？',options:['无色酚酞试液变浅红','红色石蕊变红','甲基橙变黄','石蕊变红'],answer:0,explain:'氨水弱碱，使酚酞变浅红、使红色石蕊变蓝。'},
  {id:'k322',module:'必修二',q:'关于氨水的说法，正确的是？',options:['氨水浓度越大密度越大','氨水无碱性','加热氨水无氨气逸出','氨水虽以 NH₃·H₂O 为主，但计算时以 NH₃ 为溶质'],answer:3,explain:'氨水大部分以 NH₃·H₂O 存在，但计算浓度以 NH₃ 为溶质；浓度越大密度反而越小。'},
  {id:'k323',module:'必修二',q:'氨气溶于水时易发生倒吸，原因是？',options:['氨气极易溶于水','氨气密度大','氨气有毒','氨气可燃'],answer:0,explain:'NH₃ 极易溶于水（1:700），导致装置内压强骤降而倒吸。'},
  {id:'k324',module:'必修二',q:'蘸有浓盐酸和浓氨水的玻璃棒靠近，产生大量白烟，生成物是？',options:['NH₄Cl 固体小颗粒','(NH₄)₂SO₄','NH₄NO₃','NH₃'],answer:0,explain:'挥发出的 NH₃ 与 HCl 化合生成 NH₄Cl 固体小颗粒（白烟），可用于检验 NH₃。'},
  {id:'k325',module:'必修二',q:'下列酸与浓氨水靠近不能形成白烟的是？',options:['浓硫酸','浓盐酸','浓硝酸','以上均能'],answer:0,explain:'浓硫酸不挥发，不能形成白烟；且浓硫酸不能干燥氨气（两者反应）。'},
  {id:'k327',module:'必修二',q:'2NH₃ + H₂SO₄ = (NH₄)₂SO₄ 体现氨的？',options:['氧化性','碱性','还原性','酸性'],answer:1,explain:'NH₃ 与酸反应生成铵盐，体现碱性。'},
  {id:'k328',module:'必修二',q:'氨的催化氧化：4NH₃ + 5O₂ = 4NO + 6H₂O，该反应？',options:['吸热','是分解反应','是置换反应','放热，是工业制硝酸的基础'],answer:3,explain:'该反应放热，叫接触氧化，是工业制硝酸的第一步。'},
  {id:'k329',module:'必修二',q:'氨气与少量氯气：8NH₃ + 3Cl₂ = N₂ + 6NH₄Cl，该反应中 NH₃？',options:['只作氧化剂','只作碱','部分被氧化（表现还原性）','被还原'],answer:2,explain:'部分 NH₃ 中 N 由 −3 升到 0 生成 N₂，被氧化表现还原性；其余 NH₃ 生成 NH₄Cl 表现碱性。'},
  {id:'k330',module:'必修二',q:'氨气还原 CuO（实验室制 N₂ 之一）：2NH₃ + 3CuO = N₂ + 3Cu + 3H₂O，NH₃ 表现？',options:['还原性','氧化性','酸性','碱性'],answer:0,explain:'N 由 −3 升到 0，NH₃ 作还原剂。'},
  {id:'k332',module:'必修二',q:'关于纯硝酸的物理性质，错误的是？',options:['无色、易挥发','沸点约 83℃','常用浓硝酸质量分数约 69%','密度比水小'],answer:3,explain:'浓硝酸密度约 1.4 g/cm³，比水大。'},
  {id:'k334',module:'必修二',q:'浓硝酸常显黄色，原因是？',options:['含 Fe³⁺','含杂质','光照分解','分解生成的 NO₂ 溶于硝酸'],answer:3,explain:'4HNO₃ = 4NO₂↑ + O₂↑ + 2H₂O，溶解的 NO₂ 使硝酸呈黄色。'},
  {id:'k336',module:'必修二',q:'Cu 与浓 HNO₃：Cu + 4HNO₃(浓) = Cu(NO₃)₂ + 2NO₂↑ + 2H₂O，还原产物是？',options:['NO','N₂O','H₂','NO₂'],answer:3,explain:'浓硝酸还原产物一般为 NO₂。'},
  {id:'k337',module:'必修二',q:'Cu 与稀 HNO₃：3Cu + 8HNO₃(稀) = 3Cu(NO₃)₂ + 2NO↑ + 4H₂O，产生的无色气体遇空气变为？',options:['无色','黄色','白色','红棕色'],answer:3,explain:'NO 遇 O₂ 被氧化为红棕色 NO₂。'},
  {id:'k338',module:'必修二',q:'常温下浓硝酸能使 Fe、Al 钝化，原因是？',options:['不反应','Fe、Al 为惰性','表面形成致密氧化膜','浓度低'],answer:2,explain:'浓硝酸将 Fe、Al 表面氧化成致密氧化物薄膜，阻止反应继续进行。'},
  {id:'k339',module:'必修二',q:'加热时铁与过量浓硝酸反应：Fe + 6HNO₃(浓) = Fe(NO₃)₃ + 3NO₂↑ + 3H₂O，Fe 的化合价变化是？',options:['+2 → +3','被还原','不变','0 → +3'],answer:3,explain:'Fe 由 0 价升高到 +3 价。'},
  {id:'k340',module:'必修二',q:'木炭与浓硝酸：C + 4HNO₃(浓) = CO₂↑ + 4NO₂↑ + 2H₂O，硝酸表现？',options:['只作氧化剂','酸性','只作还原剂','碱性'],answer:0,explain:'非金属与浓硝酸反应时，硝酸只表现出氧化性（N 由 +5 降到 +4）。'},
  {id:'k341',module:'必修二',q:'稀硝酸与 Fe²⁺ 反应：3Fe²⁺ + NO₃⁻ + 4H⁺ = 3Fe³⁺ + NO↑ + 2H₂O，Fe²⁺ 被？',options:['氧化','还原','不变','水解'],answer:0,explain:'Fe²⁺ 升到 Fe³⁺，被稀硝酸氧化。'},
  {id:'k342',module:'必修二',q:'下列物质不能被稀硝酸氧化的是？',options:['NaCl','H₂S','SO₂','Fe²⁺'],answer:0,explain:'NaCl 中 Na、Cl 均处于稳定价态（Cl 为 −1 已最低），稀硝酸一般不氧化 Cl⁻。'},
  {id:'k343',module:'必修二',q:'硝酸与非金属反应的通式（非金属+浓硝酸→最高价氧化物或其含氧酸+NO₂+H₂O）体现硝酸的？',options:['酸性','挥发性','不稳定性','强氧化性'],answer:3,explain:'硝酸将非金属氧化到最高价，自身被还原，体现强氧化性。'},
  {id:'k352',module:'必修二',q:'ΔH 与化学键键能的关系是？',options:['ΔH = 生成物总键能 − 反应物总键能','ΔH = 反应物总能量 − 生成物总能量','ΔH = 反应物总键能 − 生成物总键能','ΔH = 质量差'],answer:2,explain:'断键吸热、成键放热，ΔH = 反应物总键能 − 生成物总键能。'},
  {id:'k353',module:'必修二',q:'ΔH = 生成物总能量 − 反应物总能量，则放热反应 ΔH？',options:['<0','>0','=0','无法确定'],answer:0,explain:'放热时生成物能量低于反应物，ΔH < 0。'},
  {id:'k354',module:'必修二',q:'下列反应属于吸热反应的是？',options:['Ba(OH)₂·8H₂O 与 NH₄Cl 反应','木炭燃烧','酸碱中和','钠与水反应'],answer:0,explain:'大多数分解反应、铵盐与碱的固态反应（如 Ba(OH)₂·8H₂O + 2NH₄Cl）为吸热反应。'},
  {id:'k355',module:'必修二',q:'下列反应属于放热反应的是？',options:['大多数分解反应','C(s) + H₂O(g) = CO + H₂','活泼金属与水反应','煅烧石灰石'],answer:2,explain:'活泼金属与水反应放热；大多数分解反应、C 与水蒸气反应、煅烧石灰石均为吸热反应。'},
  {id:'k356',module:'必修二',q:'原电池中，负极发生的反应是？',options:['还原反应、得电子','不反应','中和反应','氧化反应、失电子'],answer:3,explain:'负极失电子发生氧化反应。'},
  {id:'k357',module:'必修二',q:'原电池外电路中，电子的流向是？',options:['正极 → 导线 → 负极','负极 → 导线 → 正极','正极 → 正极','无定向流动'],answer:1,explain:'电子由负极流出，经外电路流向正极。'},
  {id:'k358',module:'必修二',q:'原电池内电路（电解质溶液）中，阳离子的迁移方向是？',options:['向负极','向正极','不移动','向电极外'],answer:1,explain:'阳离子向正极移动，阴离子向负极移动，形成内电路。'},
  {id:'k359',module:'必修二',q:'锂离子电池负极反应通式为 Li − e⁻ = Li⁺，说明负极材料是？',options:['金属锂','石墨（嵌锂碳）','钴氧化物','铜'],answer:0,explain:'负极失去电子生成 Li⁺，活性物质为锂。'},
  {id:'k360',module:'必修二',q:'两种金属组成原电池电极，一般较活泼的金属作？',options:['正极','负极','阴极','阳极'],answer:1,explain:'较活泼金属更易失电子，作负极（发生氧化反应）。'},
  {id:'k361',module:'必修二',q:'原电池中，发生氧化反应（失电子、化合价升高）的电极是？',options:['负极','正极','阴极','都不'],answer:0,explain:'负极发生氧化，正极发生还原。'},
  {id:'k362',module:'必修二',q:'根据内电路离子迁移方向，阴离子移向？',options:['正极','不移动','负极','电解质外部'],answer:2,explain:'阴离子（带负电）向负极（带正电）移动。'},
  {id:'k363',module:'必修二',q:'原电池中电流方向与电子流向的关系是？',options:['相反','相同','无关','垂直'],answer:0,explain:'电子由负到正，电流由正到负，二者方向相反。'},
  {id:'k364',module:'必修二',q:'反应 N₂(g) + O₂(g) = 2NO(g)，缩小体积增大压强，反应速率？',options:['减小','不变','增大','先增后减'],answer:2,explain:'缩小体积使浓度增大，反应速率增大。'},
  {id:'k365',module:'必修二',q:'恒容条件下充入惰性气体 He，反应速率？',options:['增大','不变','减小','变为零'],answer:1,explain:'恒容充 He 不改变反应物浓度，速率不变。'},
  {id:'k366',module:'必修二',q:'恒压条件下充入 He 使容器体积增大，反应速率？',options:['减小','增大','不变','变为零'],answer:0,explain:'体积增大使反应物浓度减小，速率减小。'},
  {id:'k367',module:'必修二',q:'增加固体 Fe 的用量，反应速率？',options:['增大','减小','加倍','不变'],answer:3,explain:'固体浓度视为常数，改变其量不影响速率。'},
  {id:'k368',module:'必修二',q:'对于 mA + nB = pC + qD，能证明 v(正)=v(逆) 的是？',options:['单位时间内消耗 n mol B 同时消耗 p mol C','单位时间内消耗 m mol A 同时生成 m mol A','速率比 v(A):v(B):v(C):v(D)=m:n:p:q','总压强一定'],answer:1,explain:'消耗 A（正反应）与生成 A（逆反应）等量，说明正逆速率相等，达平衡。'},
  {id:'k369',module:'必修二',q:'当 m+n ≠ p+q 时，恒温恒容下总压强一定（其他条件一定），说明？',options:['不一定平衡','逆向进行','无法判断','一定达到平衡'],answer:3,explain:'气体分子数不等，压强不变意味着总物质的量不变，必为平衡标志。'},
  {id:'k370',module:'必修二',q:'反应体系内有色物质的颜色一定，说明？',options:['不一定平衡','一定达到平衡','速率变化','温度变化'],answer:1,explain:'颜色不变 = 有色物浓度不变 = 达平衡。'},
  {id:'k371',module:'必修二',q:'恒温恒容下，若反应前后气体分子数不变，密度一定时？',options:['不一定平衡','一定平衡','逆向','无法判断'],answer:0,explain:'恒容时体积定、质量守恒定，密度始终不变，不能作为平衡标志。'},
  {id:'k376',module:'必修二',q:'乙烯燃烧的现象是？',options:['淡蓝色火焰','苍白色火焰','火焰明亮且伴有黑烟','黄色火焰'],answer:2,explain:'乙烯含碳量高，燃烧时火焰明亮并伴有黑烟。'},
  {id:'k377',module:'必修二',q:'乙烯能使酸性 KMnO₄ 溶液褪色，体现乙烯的？',options:['还原性','氧化性','漂白性','酸性'],answer:0,explain:'乙烯被 KMnO₄ 氧化，体现还原性。'},
  {id:'k378',module:'必修二',q:'乙烯与溴的 CCl₄ 溶液反应：CH₂=CH₂ + Br₂ = CH₂BrCH₂Br，产物名称是？',options:['1,1-二溴乙烷','1,2-二溴乙烷','溴乙烷','二溴乙烯'],answer:1,explain:'两个溴原子分别加在两个碳上，为 1,2-二溴乙烷。'},
  {id:'k379',module:'必修二',q:'除去乙烷中混有的乙烯，可将混合气体通过？',options:['酸性 KMnO₄ 溶液','氢气','溴水洗气瓶','溴的四氯化碳溶液'],answer:2,explain:'溴水与乙烯加成而乙烷不溶不反应，可除杂；不能用溴的 CCl₄（乙烷溶于 CCl₄），KMnO₄ 会生成 CO₂ 引入新杂质。'},
  {id:'k380',module:'必修二',q:'乙烯与水加成：CH₂=CH₂ + H₂O → CH₃CH₂OH（催化剂），反应类型是？',options:['取代','加成','氧化','聚合'],answer:1,explain:'C=C 双键打开加上 H 和 OH，属加成反应（工业制乙醇）。'},
  {id:'k382',module:'必修二',q:'钠与乙醇反应比钠与水反应缓慢，主要原因是？',options:['乙醇密度大','乙醇不与钠反应','乙醇羟基氢的活泼性弱于水中氢','温度低'],answer:2,explain:'乙醇羟基氢不如水中氢活泼，故反应较缓慢。'},
  {id:'k383',module:'必修二',q:'乙醇与钠：2Na + 2CH₃CH₂OH → 2CH₃CH₂ONa + H₂↑，反应实质是？',options:['羟基氢原子被置换','氢原子被置换','乙基被置换','碳被置换'],answer:0,explain:'断裂 O−H 键，羟基上的氢被钠置换。'},
  {id:'k384',module:'必修二',q:'结构为 R−CH₂OH（−OH 连在链端碳）的醇催化氧化生成？',options:['酮','醛','羧酸','醚'],answer:1,explain:'−OH 连端碳（含 2 个 α-H），催化氧化生成醛（R−CHO）。'},
  {id:'k385',module:'必修二',q:'与 −OH 相连碳原子上无氢原子的醇，催化氧化时？',options:['生成醛','不能被催化氧化','生成酮','生成酸'],answer:1,explain:'相连碳上无 α-H，无法脱氢，不能被催化氧化。'},
  {id:'k386',module:'必修二',q:'乙醇被酸性重铬酸钾溶液氧化为乙酸，溶液颜色变化是？',options:['绿色变为橙色','紫色褪去','变为红色','橙色变为绿色'],answer:3,explain:'橙色 Cr₂O₇²⁻ 被还原为绿色 Cr³⁺，该反应用于检验酒后驾车。'},
  {id:'k387',module:'选择性必修1·反应原理',q:'判断反应放热还是吸热，依据"反应物总焓与生成物总焓"的关系，正确的是？',options:['ΔH＞0 表示放热反应','反应物总焓大于生成物总焓，反应放热','反应物总焓小于生成物总焓，反应放热','新键生成释放的能量小于旧键断裂吸收的能量，反应放热'],answer:1,explain:'反应物总焓＞生成物总焓时，多余能量以热放出，为放热反应；ΔH＜0 才表示放热。'},
  {id:'k388',module:'选择性必修1·反应原理',q:'ΔH＝－285.8 kJ·mol⁻¹ 表示该反应？',options:['不发生反应','无法判断','吸热反应','放热反应'],answer:3,explain:'ΔH 为"－"或 ΔH＜0 是放热反应；ΔH 为"＋"或 ΔH＞0 是吸热反应。'},
  {id:'k389',module:'选择性必修1·反应原理',q:'关于同一物质不同聚集态的能量与稳定性，正确的是？',options:['三者能量相同','气体能量最低、最稳定','能量：气体＞液体＞固体；稳定性：气体＜液体＜固体','固体能量最高、最稳定'],answer:2,explain:'能量越低越稳定；同一物质能量由高到低为 g＞l＞s，稳定性相反。'},
  {id:'k390',module:'选择性必修1·反应原理',q:'下列过程属于吸热反应的是？',options:['酸碱中和','燃烧','浓硫酸稀释','由稳定物质生成不稳定物质的反应'],answer:3,explain:'生成物总能量大于反应物总能量、或由稳定物质生成不稳定物质的反应均为吸热反应。'},
  {id:'k391',module:'选择性必修1·反应原理',q:'中和热的概念中，"生成 1 mol H₂O(l)"是指？',options:['气态水','液态水','固态水','任何状态下的水'],answer:1,explain:'中和热定义——稀溶液中强酸强碱中和生成 1 mol H₂O(l) 时放出的热量。'},
  {id:'k392',module:'选择性必修1·反应原理',q:'中和热数值为 57.3 kJ·mol⁻¹，其条件不包括？',options:['浓酸浓碱','稀溶液','生成 1 mol H₂O(l)','强酸与强碱'],answer:0,explain:'浓酸或浓碱稀释时会放热，故中和热特指稀溶液。'},
  {id:'k393',module:'选择性必修1·反应原理',q:'关于中和热的表述，正确的是？',options:['用 ΔH 表示时带上"－"','用 ΔH 表示时不带"－"','用文字叙述时带"－"','与酸、碱用量有关'],answer:0,explain:'文字叙述为 57.3 kJ·mol⁻¹（不带"－"）；用 ΔH 表示时为 ΔH＝－57.3 kJ·mol⁻¹。'},
  {id:'k394',module:'选择性必修1·反应原理',q:'弱酸与弱碱发生中和反应时，放出的热量与 57.3 kJ 相比？',options:['小于 57.3 kJ','大于 57.3 kJ','等于 57.3 kJ','无法比较'],answer:0,explain:'弱酸弱碱电离要吸收热量，故放出热量小于 57.3 kJ。'},
  {id:'k395',module:'选择性必修1·反应原理',q:'燃烧热是指 25 ℃、101 kPa 时？',options:['1 mol 物质不完全燃烧的热量','1 mol 物质燃烧放出的热量','1 mol 纯物质完全燃烧生成指定产物放出的热量','任意量物质燃烧的热量'],answer:2,explain:'燃烧热定义强调 1 mol 纯物质、完全燃烧、生成指定产物。'},
  {id:'k396',module:'选择性必修1·反应原理',q:'用化学键键能计算 ΔH 的式子是？',options:['ΔH＝生成物总键能－反应物总键能','ΔH＝反应物总能量－生成物总能量','ΔH＝质量差','ΔH＝反应物总键能－生成物总键能'],answer:3,explain:'断键吸热、成键放热，ΔH＝反应物总键能－生成物总键能。'},
  {id:'k397',module:'选择性必修1·反应原理',q:'用物质总能量计算 ΔH 的式子是？',options:['ΔH＝键能差','ΔH＝生成物总能量－反应物总能量','ΔH＝反应物总能量－生成物总能量','ΔH＝压强差'],answer:1,explain:'ΔH＝生成物总能量－反应物总能量；放热时生成物能量低，ΔH＜0。'},
  {id:'k398',module:'选择性必修1·反应原理',q:'化学反应速率通常用什么表示？',options:['反应物质量的变化','温度的变化','单位时间内反应物浓度的减少量或生成物浓度的增加量（取正值）','压强的改变'],answer:2,explain:'速率通常用单位时间浓度变化量表示，且均取正值。'},
  {id:'k399',module:'选择性必修1·反应原理',q:'上述反应中，10 min 内用 N₂ 表示的平均反应速率是？',options:['0.025 mol/(L·min)','0.10 mol/(L·min)','0.05 mol/(L·min)','0.075 mol/(L·min)'],answer:0,explain:'生成 1 mol NH₃ 消耗 N₂ 0.5 mol，v(N₂)＝0.5/(2 L×10 min)＝0.025 mol/(L·min)。'},
  {id:'k400',module:'选择性必修1·反应原理',q:'用 H₂ 表示的平均反应速率是？',options:['0.025 mol/(L·min)','0.05 mol/(L·min)','0.15 mol/(L·min)','0.075 mol/(L·min)'],answer:3,explain:'消耗 H₂ 1.5 mol，v(H₂)＝1.5/(2 L×10 min)＝0.075 mol/(L·min)。'},
  {id:'k401',module:'选择性必修1·反应原理',q:'用 NH₃ 表示的平均反应速率是？',options:['0.05 mol/(L·min)','0.10 mol/(L·min)','0.075 mol/(L·min)','0.025 mol/(L·min)'],answer:0,explain:'v(NH₃)＝1/(2 L×10 min)＝0.05 mol/(L·min)。'},
  {id:'k402',module:'选择性必修1·反应原理',q:'同一反应中，各物质的反应速率之比等于？',options:['随机','化学方程式中各物质的化学计量数之比','反比','分子质量之比'],answer:1,explain:'各物质速率之比等于化学计量数之比，表示同一反应进程。'},
  {id:'k403',module:'选择性必修1·反应原理',q:'一定温度下，一定质量的气体所占体积与压强的关系是？',options:['不确定','正比','反比','无关'],answer:2,explain:'一定质量气体，体积与压强成反比。'},
  {id:'k404',module:'选择性必修1·反应原理',q:'增大压强使气体反应速率加快的主要原因是？',options:['活化能降低','分子总数增多','体积缩小、浓度增大','分子能量升高'],answer:2,explain:'增大压强使气体体积缩小、浓度增大，单位时间有效碰撞次数增加。'},
  {id:'k405',module:'选择性必修1·反应原理',q:'恒温恒容下充入惰性气体，体系总压增大，但反应速率？',options:['不变','减慢','先快后慢','加快'],answer:0,explain:'恒容充惰气，各物质浓度不变，故反应速率不变。'},
  {id:'k406',module:'选择性必修1·反应原理',q:'恒温恒压下充入惰性气体，反应速率？',options:['先增后减','增大','不变','减小'],answer:3,explain:'恒压充惰气使体积增大、各反应物浓度减小，反应速率减小。'},
  {id:'k407',module:'选择性必修1·反应原理',q:'Zn 与足量盐酸反应，速率-时间曲线 AB 段速率增大的原因是？',options:['催化作用','反应放热使溶液温度升高','盐酸浓度增大','压强增大'],answer:1,explain:'AB 段反应放热使温度升高，速率逐渐增大。'},
  {id:'k408',module:'选择性必修1·反应原理',q:'该反应 BC 段速率减小的原因是？',options:['压强减小','温度升高','盐酸浓度逐渐减小','催化'],answer:2,explain:'随着反应进行盐酸浓度减小，速率逐渐减小。'},
  {id:'k409',module:'选择性必修1·反应原理',q:'H₂C₂O₄ 溶液中加入酸性 KMnO₄，AB 段速率增大的主要原因是？',options:['压强','生成的 Mn²⁺ 起催化作用','浓度增大','温度升高'],answer:1,explain:'反应产生的 Mn²⁺ 对该反应起催化作用，使速率增大。'},
  {id:'k410',module:'选择性必修1·反应原理',q:'其他条件一定，反应速率随温度升高而？',options:['增大','减小','先增后减','不变'],answer:0,explain:'升温使活化分子百分数增大，速率增大。'},
  {id:'k411',module:'选择性必修1·反应原理',q:'决定总反应速率的步骤是？',options:['第一步','最后一步','最快的基元反应','最慢的基元反应'],answer:3,explain:'连串反应中，决定速率的是最慢的一个基元步骤（决速步）。'},
  {id:'k412',module:'选择性必修1·反应原理',q:'大多数化学反应经过多个步骤实现，其中每一步反应称为？',options:['基元反应','中间体','总反应','催化剂'],answer:0,explain:'每一步反应都称为基元反应；先后进行的基元反应反映反应历程。'},
  {id:'k413',module:'选择性必修1·反应原理',q:'反应历程又称？',options:['反应机理','中间体','活化能','催化剂'],answer:0,explain:'反应历程又称反应机理。'},
  {id:'k414',module:'选择性必修1·反应原理',q:'发生有效碰撞的条件是？',options:['具有足够的能量且合适的取向','具有足够高的能量','高温','具有合适的取向'],answer:0,explain:'有效碰撞需同时满足足够能量与合适取向。'},
  {id:'k415',module:'选择性必修1·反应原理',q:'活化分子是指？',options:['能够发生有效碰撞的分子','运动最快的分子','所有分子','温度最高的分子'],answer:0,explain:'能发生有效碰撞的分子叫活化分子。'},
  {id:'k416',module:'选择性必修1·反应原理',q:'活化能是指？',options:['键能','活化分子平均能量与反应物分子平均能量之差','反应物总能量','生成物总能量'],answer:1,explain:'活化能＝活化分子平均能量－反应物分子平均能量。'},
  {id:'k417',module:'选择性必修1·反应原理',q:'对于放热反应，正反应活化能 E₁ 与逆反应活化能 E₂ 的大小关系是？',options:['E₁＝E₂','无关','E₁＞E₂','E₁＜E₂'],answer:3,explain:'ΔH＝E₁－E₂＜0，故 E₁＜E₂。'},
  {id:'k418',module:'选择性必修1·反应原理',q:'基元反应过渡状态理论认为，基元反应从反应物到产物要经历？',options:['溶剂','一个中间状态（过渡态）','催化剂','一个稳定分子'],answer:1,explain:'反应过程中要经历一个最高能量的中间状态，称为过渡态。'},
  {id:'k419',module:'选择性必修1·反应原理',q:'过渡态是？',options:['能量最低的分子构型','处在反应过程中具有最高能量的分子构型','最终产物','反应物'],answer:1,explain:'过渡态是反应过程中最高能量的分子构型。'},
  {id:'k420',module:'选择性必修1·反应原理',q:'一溴甲烷与 NaOH 溶液反应的历程 CH₃Br＋OH⁻―→[Br…CH₃…OH]‡―→Br⁻＋CH₃OH 中，[Br…CH₃…OH]‡ 是？',options:['产物','反应物','催化剂','过渡态'],answer:3,explain:'中间状态 [Br…CH₃…OH]‡ 为过渡态。'},
  {id:'k421',module:'选择性必修1·反应原理',q:'增大反应物浓度使速率加快，活化分子百分数？',options:['变为零','不变','增大','减小'],answer:1,explain:'浓度增大使活化分子总数增多，但活化分子百分数不变。'},
  {id:'k422',module:'选择性必修1·反应原理',q:'升高温度使速率加快，主要是因为？',options:['活化分子百分数增大','分子总数增多','体积缩小','压强增大'],answer:0,explain:'升温使部分低能分子变为活化分子，活化分子百分数增大。'},
  {id:'k423',module:'选择性必修1·反应原理',q:'使用催化剂加快反应速率是因为？',options:['降低反应的活化能','增大浓度','增大压强','升高温度'],answer:0,explain:'催化剂改变反应历程、降低活化能，使活化分子百分数增大。'},
  {id:'k424',module:'选择性必修1·反应原理',q:'增大压强（缩小容器体积）使气体速率加快，是因为单位体积内？',options:['温度升高','活化分子百分数增大','分子总数增多','活化分子数增多'],answer:3,explain:'体积缩小使单位体积内活化分子数增多，有效碰撞次数增加。'},
  {id:'k425',module:'选择性必修1·反应原理',q:'升高温度，化学反应速率加快，是因为？',options:['分子总数增多','活化分子百分数增大','压强增大','体积缩小'],answer:1,explain:'升温使活化分子百分数增大，有效碰撞次数增多。'},
  {id:'k426',module:'选择性必修1·反应原理',q:'使用催化剂时，反应的活化能？',options:['升高','变为零','降低','不变'],answer:2,explain:'催化剂降低活化能。'},
  {id:'k427',module:'选择性必修1·反应原理',q:'可逆反应开始时生成物浓度为 0，则逆反应速率 v逆？',options:['等于 v正','不确定','为 0','最大'],answer:2,explain:'开始时无生成物，逆反应速率为 0，v正最大。'},
  {id:'k428',module:'选择性必修1·反应原理',q:'反应达到化学平衡时？',options:['v正＝v逆≠0','v正＝0','v正＞v逆','v逆＝0'],answer:0,explain:'平衡时正逆速率相等且均不为 0。'},
  {id:'k429',module:'选择性必修1·反应原理',q:'对于已达平衡的反应，各物质的物质的量分数一定，说明？',options:['无法判断','一定达到平衡','未平衡','不一定平衡'],answer:1,explain:'各成分含量（物质的量分数）一定，是平衡标志。'},
  {id:'k430',module:'选择性必修1·反应原理',q:'恒温恒容下，体系总压强一定时，是否一定平衡？',options:['一定平衡','不一定平衡','一定未平衡','无法判断'],answer:1,explain:'若反应前后气体分子数相等，总压强始终不变，不能作为平衡标志。'},
  {id:'k431',module:'选择性必修1·反应原理',q:'单位时间内消耗 m mol A 同时生成 m mol A，说明？',options:['速率相等但非平衡','无关','未平衡','v正＝v逆，达平衡'],answer:3,explain:'消耗 A（正反应）与生成 A（逆反应）等量，正逆速率相等。'},
  {id:'k432',module:'选择性必修1·反应原理',q:'当 m＋n≠p＋q 时，恒温恒容下总压强一定，说明？',options:['不一定平衡','一定未平衡','无法判断','一定达到平衡'],answer:3,explain:'气体分子数不等时，压强不变意味着总物质的量不变，必为平衡。'},
  {id:'k433',module:'选择性必修1·反应原理',q:'反应体系内有色物质的颜色一定，说明？',options:['无法判断','一定未平衡','一定达到平衡','不一定平衡'],answer:2,explain:'颜色不变＝有色物浓度不变＝达平衡。'},
  {id:'k434',module:'选择性必修1·反应原理',q:'恒温恒容下加入惰性气体，化学平衡？',options:['逆向移动','不发生移动','发生移动','正向移动'],answer:1,explain:'恒容充惰气，各物质浓度未变，v正、v逆均不变，平衡不移动。'},
  {id:'k435',module:'选择性必修1·反应原理',q:'恒温恒压下加入惰性气体，平衡？',options:['逆向移动','正向移动','等效于降压，向气体总体积增大的方向移动','不移动'],answer:2,explain:'恒压充惰气体积增大，等效于减压。'},
  {id:'k436',module:'选择性必修1·反应原理',q:'对于反应前后气体总体积不变的可逆反应，加入惰性气体？',options:['发生移动','逆向移动','正向移动','不发生移动'],answer:3,explain:'气体体积不变的反应，任何情况下加惰气均不移动。'},
  {id:'k437',module:'选择性必修1·反应原理',q:'对 N₂(g)＋3H₂(g)⇌2NH₃(g)（ΔH＜0）升高温度，平衡？',options:['逆向移动','不移动','无法判断','正向移动'],answer:0,explain:'升温使平衡向吸热方向（逆向）移动。'},
  {id:'k438',module:'选择性必修1·反应原理',q:'平衡常数 K 越大，表示？',options:['反应越不完全','反应越难发生','与转化率无关','反应物转化率越大'],answer:3,explain:'K 越大反应进行越完全，反应物转化率越大。'},
  {id:'k439',module:'选择性必修1·反应原理',q:'平衡常数 K 的影响因素主要是？',options:['催化剂','温度','反应物浓度','压强'],answer:1,explain:'方程式一定时，K 只受温度影响，与浓度、压强无关。'},
  {id:'k440',module:'选择性必修1·反应原理',q:'若两反应相加得总反应，则总反应的 K？',options:['K＝K₁＋K₂','K＝K₁·K₂','无关','K＝K₁/K₂'],answer:1,explain:'反应相加，平衡常数相乘。'},
  {id:'k441',module:'选择性必修1·反应原理',q:'升高温度 K 减小，说明正反应是？',options:['不反应','放热反应','无影响','吸热反应'],answer:1,explain:'升温 K 减小→正反应为放热反应；K 增大→正反应吸热。'},
  {id:'k442',module:'选择性必修1·反应原理',q:'任意时刻浓度商 Q 与 K 比较，当 Q＜K 时，反应？',options:['无法判断','处于平衡','向逆反应方向进行','向正反应方向进行'],answer:3,explain:'Q＜K 时 v正＞v逆，反应正向进行。'},
  {id:'k443',module:'选择性必修1·反应原理',q:'当 Q＝K 时，反应？',options:['向逆反应方向','向正反应方向','无法判断','处于平衡状态'],answer:3,explain:'Q＝K 时 v正＝v逆，达平衡。'},
  {id:'k444',module:'选择性必修1·反应原理',q:'等效平衡是指同一可逆反应不同投料方式达平衡时？',options:['相同组分百分含量相等','物质的量相等','体积相等','浓度相等'],answer:0,explain:'平衡时相同组分的体积分数、物质的量分数或质量分数相等。'},
  {id:'k445',module:'选择性必修1·反应原理',q:'恒温恒容、Δn≠0 的反应，等效平衡的条件是？',options:['量等等效','量比等效','不要求','任意投料'],answer:0,explain:'恒容 Δn≠0 时需"量等等效"（相同物料量）。'},
  {id:'k446',module:'选择性必修1·反应原理',q:'两种反应物达平衡后，增加其中一种反应物浓度，另一种反应物的转化率？',options:['无法判断','不变','提高','降低'],answer:2,explain:'增加一种反应物浓度，其他反应物转化率提高，自身转化率降低。'},
  {id:'k447',module:'选择性必修1·反应原理',q:'恒温恒容、m＋n＞p＋q，按原比例同倍增大 A、B 的量，A、B 转化率？',options:['无法判断','都增大','都减小','都不变'],answer:1,explain:'相当于加压，平衡正向移动，转化率都增大。'},
  {id:'k448',module:'选择性必修1·反应原理',q:'恒温恒压下按原比例同倍增大 A、B 的量，A、B 转化率？',options:['都减小','都不变','都增大','无法判断'],answer:1,explain:'恒压同比例加料，浓度不变，转化率不变。'},
  {id:'k449',module:'选择性必修1·反应原理',q:'熵是描述体系什么的物理量？',options:['压强','温度','混乱度（无序程度）','能量高低'],answer:2,explain:'熵表示体系的混乱或无序程度，S(g)＞S(l)＞S(s)。'},
  {id:'k450',module:'选择性必修1·反应原理',q:'当 ΔG＜0 时，反应？',options:['处于平衡','无法判断','能自发进行','不能自发进行'],answer:2,explain:'ΔG＜0 反应能自发进行。'},
  {id:'k451',module:'选择性必修1·反应原理',q:'ΔH＜0 且 ΔS＞0 时，反应自发进行的温度条件是？',options:['都不能','高温自发','所有温度都自发','低温自发'],answer:2,explain:'ΔG＝ΔH－TΔS，两因子均有利，所有温度自发。'},
  {id:'k452',module:'选择性必修1·反应原理',q:'ΔH＞0 且 ΔS＜0 时，反应？',options:['低温自发','高温自发','所有温度都自发','所有温度都不能自发'],answer:3,explain:'ΔG 恒大于 0，任何温度都不能自发。'},
  {id:'k453',module:'选择性必修1·反应原理',q:'自由能变化与焓变、熵变的关系是？',options:['无关','ΔG＝ΔH－TΔS','ΔG＝TΔS－ΔH','ΔG＝ΔH＋TΔS'],answer:1,explain:'ΔG＝ΔH－TΔS。'},
  {id:'k454',module:'选择性必修1·反应原理',q:'下列属于电解质的是？',options:['氯化钠','葡萄糖','蔗糖','酒精'],answer:0,explain:'电解质是在水溶液或熔融状态能导电的化合物；NaCl 是强电解质，其余为非电解质。'},
  {id:'k455',module:'选择性必修1·反应原理',q:'弱电解质溶液稀释时，电离程度？',options:['不变','变为零','增大','减小'],answer:2,explain:'越稀越电离，稀释使电离平衡正向移动、电离程度增大。'},
  {id:'k456',module:'选择性必修1·反应原理',q:'0.1 mol/L CH₃COOH 溶液加水稀释，c(H⁺)？',options:['变为零','增大','不变','减小'],answer:3,explain:'稀释虽使电离程度增大，但体积增大占主导，c(H⁺) 减小。'},
  {id:'k457',module:'选择性必修1·反应原理',q:'向 CH₃COOH 溶液中加入 CH₃COONa 固体，电离平衡？',options:['不移动','无法判断','正向移动','逆向移动'],answer:3,explain:'同离子效应，CH₃COO⁻ 抑制电离，平衡逆向。'},
  {id:'k458',module:'选择性必修1·反应原理',q:'一元弱酸 CH₃COOH 的电离常数表达式为？',options:['Ka＝c(CH₃COOH)/[c(CH₃COO⁻)·c(H⁺)]','Ka＝c(CH₃COO⁻)/c(H⁺)','Ka＝c(CH₃COO⁻)·c(H⁺)/c(CH₃COOH)','Ka＝c(H⁺)/c(CH₃COOH)'],answer:2,explain:'Ka＝生成离子浓度积/未电离分子浓度。'},
  {id:'k459',module:'选择性必修1·反应原理',q:'多元弱酸分步电离，各级电离常数关系为？',options:['Ka₁＝Ka₂','Ka₁≪Ka₂','Ka₁≫Ka₂','无关'],answer:2,explain:'第一步电离产生的 H⁺ 抑制后续电离，Ka₁≫Ka₂。'},
  {id:'k460',module:'选择性必修1·反应原理',q:'多元弱酸的酸性主要由？',options:['第二步电离决定','各步同等重要','最后一步电离决定','第一步电离决定'],answer:3,explain:'酸性主要由第一步电离决定。'},
  {id:'k461',module:'选择性必修1·反应原理',q:'一元弱碱 NH₃·H₂O 的电离常数表达式为？',options:['Kb＝c(NH₄⁺)·c(OH⁻)/c(NH₃·H₂O)','Kb＝c(NH₄⁺)/c(OH⁻)','Kb＝c(NH₃·H₂O)/[c(NH₄⁺)·c(OH⁻)]','Kb＝c(OH⁻)/c(NH₄⁺)'],answer:0,explain:'Kb＝c(NH₄⁺)·c(OH⁻)/c(NH₃·H₂O)。'},
  {id:'k462',module:'选择性必修1·反应原理',q:'电离平衡常数随温度升高而？',options:['不变','增大','变为零','减小'],answer:1,explain:'电离为吸热过程，升温使 Ka 增大。'},
  {id:'k463',module:'选择性必修1·反应原理',q:'相同条件下，Ka 越大，该弱酸的酸性？',options:['越弱','无法判断','越强','不变'],answer:2,explain:'Ka 越大，酸性（或碱性）越强。'},
  {id:'k464',module:'选择性必修1·反应原理',q:'0.1 mol/L CH₃COOH 加水稀释，比值 c(CH₃COO⁻)/c(CH₃COOH)？',options:['不变','无法判断','减小','增大'],answer:3,explain:'该比＝Ka/c(H⁺)，稀释使 c(H⁺) 减小、Ka 不变，故比值增大。'},
  {id:'k465',module:'选择性必修1·反应原理',q:'电离度 α 与浓度 c 的关系（越稀越电离）为？',options:['α＝√(Ka/c)','α＝√(Ka·c)','α＝Ka·c','α＝Ka/c'],answer:0,explain:'c(H⁺)＝√(Ka·c)，α＝c(H⁺)/c＝√(Ka/c)。'},
  {id:'k466',module:'选择性必修1·反应原理',q:'等物质的量浓度、等体积的 HCl 与 CH₃COOH，c(H⁺) 大小？',options:['HCl＜CH₃COOH','无法判断','HCl＞CH₃COOH','相等'],answer:2,explain:'HCl 完全电离、CH₃COOH 部分电离，故 c(H⁺) 前者大。'},
  {id:'k467',module:'选择性必修1·反应原理',q:'等 pH、等体积的 HCl 与 CH₃COOH，中和所需 NaOH 的物质的量？',options:['无法判断','相等','CH₃COOH 多','HCl 多'],answer:2,explain:'pH 相同时弱酸浓度更大，故 CH₃COOH 消耗更多 NaOH。'},
  {id:'k468',module:'选择性必修1·反应原理',q:'水的电离 H₂O⇌H⁺＋OH⁻（ΔH＞0），升高温度时 Kw？',options:['不变','变为零','增大','减小'],answer:2,explain:'升温促进水电离，c(H⁺)、c(OH⁻)、Kw 均增大。'},
  {id:'k469',module:'选择性必修1·反应原理',q:'向水中加入 HCl 气体，水的电离平衡？',options:['不移动','逆向移动','无法判断','正向移动'],answer:1,explain:'c(H⁺) 增大，抑制水的电离，平衡左移；Kw 不变。'},
  {id:'k470',module:'选择性必修1·反应原理',q:'酸式滴定管不能盛放的是？',options:['碱液','中性溶液','氧化性溶液','酸液'],answer:0,explain:'碱液会腐蚀玻璃活塞，故酸式滴定管装酸、氧化性、中性溶液，不装碱液。'},
  {id:'k471',module:'选择性必修1·反应原理',q:'滴定管的 0 刻度位置在？',options:['下端','中间','无 0 刻度','上端'],answer:3,explain:'滴定管 0 刻度在上，从上往下读。'},
  {id:'k472',module:'选择性必修1·反应原理',q:'强碱滴定弱酸时应选用的指示剂是？',options:['不需指示剂','甲基橙','酚酞','石蕊'],answer:2,explain:'强碱—弱酸用酚酞。'},
  {id:'k473',module:'选择性必修1·反应原理',q:'滴定管的最小分度与读数要求是？',options:['0.1 mL，估读至 0.01 mL','1 mL','0.01 mL，估读至 0.1 mL','0.1 mL 不估读'],answer:0,explain:'常用滴定管最小分度 0.1 mL，读数取小数点后两位（估读 0.01 mL）。'},
  {id:'k474',module:'选择性必修1·反应原理',q:'酸式滴定管未用标准溶液润洗，测得的 c(NaOH)？',options:['无法判断','偏小','偏大','无影响'],answer:2,explain:'未润洗使标准液被稀释，消耗 V 标偏大，c 测偏大。'},
  {id:'k475',module:'选择性必修1·反应原理',q:'锥形瓶用待测液润洗，结果？',options:['无法判断','偏大','无影响','偏小'],answer:1,explain:'润洗使装入的待测物增多，消耗 V 标偏大，结果偏大。'},
  {id:'k476',module:'选择性必修1·反应原理',q:'滴定前仰视读数、滴定后俯视读数，标准液体积 V 标？',options:['无法判断','偏小','偏大','无影响'],answer:1,explain:'V＝后－前，前仰使前读数偏大、后俯使后读数偏小，V 偏小。'},
  {id:'k477',module:'选择性必修1·反应原理',q:'锥形瓶洗净后内壁留有蒸馏水，对结果？',options:['无影响','偏小','无法判断','偏大'],answer:0,explain:'待测物物质的量不变，水不改变结果。'},
  {id:'k478',module:'选择性必修1·反应原理',q:'下列盐溶液呈酸性的是？',options:['KNO₃','CH₃COONa','Na₂CO₃','NH₄Cl'],answer:3,explain:'NH₄Cl 为强酸弱碱盐，NH₄⁺ 水解显酸性。'},
  {id:'k479',module:'选择性必修1·反应原理',q:'"越弱越水解"是指？',options:['浓度越小','生成盐的弱酸/弱碱越难电离，水解程度越大','温度越低','酸碱性越弱'],answer:1,explain:'弱酸（弱碱）越难电离，对应盐水解程度越大。'},
  {id:'k480',module:'选择性必修1·反应原理',q:'升高温度，盐类水解程度？',options:['减小','不变','无法判断','增大'],answer:3,explain:'水解吸热，升温使平衡右移、水解程度增大。'},
  {id:'k481',module:'选择性必修1·反应原理',q:'加水稀释盐溶液，水解平衡与水解程度？',options:['右移、程度增大','不移动','无法判断','左移、程度减小'],answer:0,explain:'稀释使水解平衡右移，水解程度增大。'},
  {id:'k482',module:'选择性必修1·反应原理',q:'Na₂CO₃ 溶液的物料守恒式为？',options:['c(Na⁺)＝c(CO₃²⁻)','c(Na⁺)＝c(H₂CO₃)','c(Na⁺)＝2[c(CO₃²⁻)＋c(HCO₃⁻)＋c(H₂CO₃)]','c(Na⁺)＝c(HCO₃⁻)'],answer:2,explain:'Na 与 C 物料比为 2:1。'},
  {id:'k483',module:'选择性必修1·反应原理',q:'Na₂CO₃ 溶液中离子浓度大小顺序正确的是？',options:['c(CO₃²⁻)＞c(Na⁺)','c(HCO₃⁻)＞c(Na⁺)','c(Na⁺)＞c(CO₃²⁻)＞c(OH⁻)＞c(HCO₃⁻)＞c(H₂CO₃)＞c(H⁺)','c(H⁺)＞c(OH⁻)'],answer:2,explain:'CO₃²⁻ 分步水解，碱性，主序如上。'},
  {id:'k484',module:'选择性必修1·反应原理',q:'NH₄Cl 溶液中浓度大小顺序正确的是？',options:['c(Cl⁻)＞c(NH₄⁺)＞c(H⁺)＞c(NH₃·H₂O)＞c(OH⁻)','c(OH⁻)＞c(H⁺)','c(NH₃·H₂O)＞c(Cl⁻)','c(NH₄⁺)＞c(Cl⁻)'],answer:0,explain:'NH₄⁺ 水解显酸性，Cl⁻ 不水解，故 c(Cl⁻)＞c(NH₄⁺)。'},
  {id:'k485',module:'选择性必修1·反应原理',q:'NaHCO₃ 溶液（显碱性）中 c(H⁺) 与 c(CO₃²⁻) 的关系是？',options:['无法判断','c(CO₃²⁻)＞c(H⁺)','相等','c(H⁺)＞c(CO₃²⁻)'],answer:3,explain:'NaHCO₃ 浓度序为 c(Na⁺)＞c(HCO₃⁻)＞c(OH⁻)＞c(H⁺)＞c(CO₃²⁻)＞c(H₂CO₃)。'},
  {id:'k486',module:'选择性必修1·反应原理',q:'Na₃PO₄ 溶液中浓度最大的微粒是？',options:['c(PO₄³⁻)','c(H⁺)','c(OH⁻)','c(Na⁺)'],answer:3,explain:'Na₃PO₄ 完全电离，c(Na⁺) 最大。'},
  {id:'k487',module:'选择性必修1·反应原理',q:'等浓度 CH₃COOH 与 CH₃COONa 混合，溶液呈？',options:['碱性','酸性','中性','无法判断'],answer:1,explain:'等浓度混合（且 c(CH₃COONa)≤c(CH₃COOH) 时）溶液呈酸性。'},
  {id:'k488',module:'选择性必修1·反应原理',q:'该混合溶液中浓度大小顺序正确的是？',options:['c(Na⁺)＞c(CH₃COO⁻)','c(CH₃COO⁻)＞c(Na⁺)＞c(CH₃COOH)＞c(H⁺)＞c(OH⁻)','c(CH₃COOH)＞c(CH₃COO⁻)','c(OH⁻)＞c(H⁺)'],answer:1,explain:'醋酸电离程度大于醋酸根水解，c(CH₃COO⁻) 最大。'},
  {id:'k489',module:'选择性必修1·反应原理',q:'等浓度 NH₃·H₂O 与 NH₄Cl 混合，溶液呈？',options:['中性','酸性','无法判断','碱性'],answer:3,explain:'等浓度混合溶液呈碱性。'},
  {id:'k490',module:'选择性必修1·反应原理',q:'等浓度 NaCN 与 HCN 混合，溶液呈？',options:['碱性','中性','酸性','无法判断'],answer:0,explain:'等浓度混合溶液呈碱性（[c(HCN)≤c(NaCN)] 时仍碱性）。'},
  {id:'k491',module:'选择性必修1·反应原理',q:'Mg(OH)₂ 饱和溶液加水稀释，c(Mg²⁺)？',options:['变为零','增大','减小','不变'],answer:3,explain:'加水稀释仍饱和，c(Mg²⁺)、c(OH⁻) 均不变。'},
  {id:'k492',module:'选择性必修1·反应原理',q:'向 Mg(OH)₂ 沉淀中加盐酸，平衡？',options:['无法判断','正向移动','不移动','逆向移动'],answer:1,explain:'H⁺ 消耗 OH⁻，平衡正向移动使沉淀溶解。'},
  {id:'k493',module:'选择性必修1·反应原理',q:'溶度积 Ksp 的大小只与什么有关？',options:['难溶电解质本身的性质和温度','溶液中离子浓度','压强','沉淀的量'],answer:0,explain:'Ksp 只与难溶电解质本身性质和温度有关。'},
  {id:'k494',module:'选择性必修1·反应原理',q:'当离子积 Q＞Ksp 时，溶液？',options:['饱和、处于平衡','过饱和、有沉淀析出','无沉淀','无法判断'],answer:1,explain:'Q＞Ksp 过饱和，有沉淀析出直至饱和。'},
  {id:'k495',module:'选择性必修1·反应原理',q:'原电池中发生氧化反应（失电子、化合价升高）的电极是？',options:['阳极','正极','负极','阴极'],answer:2,explain:'负极失电子发生氧化。'},
  {id:'k496',module:'选择性必修1·反应原理',q:'根据外电路电子流向，电子流出的一极是？',options:['负极','无法判断','正极','阳极'],answer:0,explain:'电子由负极流出经导线流向正极。'},
  {id:'k497',module:'选择性必修1·反应原理',q:'原电池工作后 X 极质量增加，说明 X 极是？',options:['阳极','无法判断','正极','负极'],answer:2,explain:'阳离子在 X 极放电析出金属使质量增加，X 为正极（活泼性弱）。'},
  {id:'k498',module:'选择性必修1·反应原理',q:'两种金属组成的电极，通常较活泼的金属作？',options:['阳极','阴极','正极','负极'],answer:3,explain:'较活泼金属更易失电子，作负极。'},
  {id:'k499',module:'选择性必修1·反应原理',q:'锂离子电池（石墨嵌锂负极）的负极反应通式为？',options:['LiCₓ－xe⁻＝xLi⁺＋C₆','LiCₓ＋xe⁻＝xLi＋C₆','Li⁺＋e⁻＝Li','Li－e⁻＝Li⁺'],answer:0,explain:'嵌锂碳失电子生成 Li⁺ 与 C₆。'},
  {id:'k500',module:'选择性必修1·反应原理',q:'磷酸铁锂电池的正极反应是？',options:['Li－e⁻＝Li⁺','Fe－2e⁻＝Fe²⁺','FePO₄＋e⁻＝PO₄³⁻','FePO₄＋Li⁺＋e⁻＝LiFePO₄'],answer:3,explain:'正极 FePO₄ 得电子生成 LiFePO₄。'},
  {id:'k501',module:'选择性必修1·反应原理',q:'各类锂电池负极反应均生成？',options:['电子','金属 Li','C₆','Li⁺'],answer:3,explain:'负极 Li（或嵌锂碳）失电子均生成 Li⁺。'},
  {id:'k502',module:'选择性必修1·反应原理',q:'锂电池总反应本质上是 Li 元素？',options:['无法判断','价态不变','被还原（＋1→0）','被氧化（0→＋1）'],answer:3,explain:'Li 从 0 价升至 ＋1 价，在负极被氧化。'},
  {id:'k503',module:'选择性必修1·反应原理',q:'电解池是将什么能转化为什么能的装置？',options:['光能→电能','电能→化学能','热能→电能','化学能→电能'],answer:1,explain:'电解池把电能转化为化学能。'},
  {id:'k504',module:'选择性必修1·反应原理',q:'与直流电源负极相连的电极是？',options:['无法判断','阳极','阴极','正极'],answer:2,explain:'阴极与电源负极相连，发生还原反应。'},
  {id:'k505',module:'选择性必修1·反应原理',q:'电解池中阳离子在电解质溶液里移向？',options:['阴极','无法判断','正极','阳极'],answer:0,explain:'阳离子移向阴极（得电子）。'},
  {id:'k506',module:'选择性必修1·反应原理',q:'电解池的阳极发生？',options:['还原反应','不反应','中和','氧化反应'],answer:3,explain:'阳极与电源正极相连，失电子发生氧化反应。'},
  {id:'k511',module:'选择性必修1·反应原理',q:'用 Ag 作电极电解稀盐酸，总反应产物包括？',options:['AgCl 和 Cl₂','Ag 和 H₂','AgCl 和 H₂','Ag 和 Cl₂'],answer:2,explain:'阳极 Ag 溶解得 Ag⁺ 与 Cl⁻ 生成 AgCl 沉淀，阴极放 H₂。'},
  {id:'k512',module:'选择性必修1·反应原理',q:'电解饱和食盐水时阳极产物是？',options:['NaOH','O₂','Cl₂','H₂'],answer:2,explain:'阳极 Cl⁻ 失电子：2Cl⁻－2e⁻＝Cl₂↑。'},
  {id:'k513',module:'选择性必修1·反应原理',q:'电解饱和食盐水时阴极反应是？',options:['4OH⁻－4e⁻＝O₂','2Na⁺＋2e⁻＝2Na','2H⁺＋2e⁻＝H₂','2Cl⁻－2e⁻＝Cl₂'],answer:2,explain:'阴极 H⁺（水电离）得电子：2H⁺＋2e⁻＝H₂↑。'},
  {id:'k514',module:'选择性必修1·反应原理',q:'电镀时，镀层金属应作为？',options:['阳极（连正极）','阴极（连负极）','不接入电路','任意电极'],answer:0,explain:'镀层金属作阳极连正极，溶解提供金属离子。'},
  {id:'k515',module:'选择性必修1·反应原理',q:'电镀过程中，电镀液（镀层金属离子浓度）？',options:['无法判断','保持不变','逐渐减小','逐渐增大'],answer:1,explain:'阳极溶解与阴极析出等量，电镀液浓度保持不变。'},
  {id:'k516',module:'选择性必修1·反应原理',q:'电解饱和食盐水的总反应（化学方程式）生成物是？',options:['NaOH、H₂、Cl₂','NaCl、H₂','NaOH、O₂','NaCl、Cl₂'],answer:0,explain:'2NaCl＋2H₂O＝电解＝2NaOH＋H₂↑＋Cl₂↑。'},
    {id:'k517',module:'选择性必修2·物质结构与性质',q:'多电子原子按核外电子能量差异，将电子分为不同能层。第一、二、三、四、五、六、七能层依次用哪组符号表示？',options:['1、2、3、4、5、6、7','K、L、M、N、O、P、Q','A、B、C、D、E、F、G','K、L、M、N、O、P、R'],answer:1,explain:'能层序数一～七分别对应 K、L、M、N、O、P、Q。'},
    {id:'k518',module:'选择性必修2·物质结构与性质',q:'关于各能层能量高低，下列顺序正确的是？',options:['E(K) < E(L) < E(M) < E(N) < E(O) < E(P) < E(Q)','各能层能量相等','E(K) > E(L) > E(M) > …','与能层序数无关'],answer:0,explain:'能层越高，电子能量越高，顺序为 E(K)<E(L)<…<E(Q)。'},
    {id:'k519',module:'选择性必修2·物质结构与性质',q:'原子核外每一能层最多可容纳的电子数与能层序数 n 的关系是？',options:['2n','8','2n²','n²'],answer:2,explain:'各能层最多容纳电子数为 2n²。'},
    {id:'k520',module:'选择性必修2·物质结构与性质',q:'下列用来表示"能级"的是？',options:['3s','K','M','N'],answer:0,explain:'能级用相应能层序数和字母 s、p、d、f 等表示，如 3s；K、M、N 是能层符号。'},
    {id:'k521',module:'选择性必修2·物质结构与性质',q:'铬(Cr)的基态原子电子排布式是？',options:['[Ar]3d⁶4s⁰','[Ar]3d⁵4s¹','[Ar]3d⁴4s²','[Ar]3d⁹4s¹'],answer:1,explain:'Cr 半满稳定，基态为 [Ar]3d⁵4s¹。'},
    {id:'k522',module:'选择性必修2·物质结构与性质',q:'铜(Cu)的基态原子电子排布式是？',options:['[Ar]3d¹⁰4s¹','[Ar]4s²3d⁹','[Ar]3d⁹4s²','[Ar]3d⁸4s²'],answer:0,explain:'Cu 全满稳定，基态为 [Ar]3d¹⁰4s¹。'},
    {id:'k523',module:'选择性必修2·物质结构与性质',q:'基态原子是指？',options:['电子全满的原子','处于最低能量状态的原子','激发后的原子','吸收能量后电子跃迁到较高能级的原子'],answer:1,explain:'基态原子是处于最低能量状态的原子；吸收能量跃迁到较高能级变为激发态。'},
    {id:'k524',module:'选择性必修2·物质结构与性质',q:'s 电子的原子轨道呈什么形状？',options:['球形','哑铃形','平面三角形','直线形'],answer:0,explain:'s 电子原子轨道呈球形；p 电子原子轨道呈哑铃形。'},
    {id:'k525',module:'选择性必修2·物质结构与性质',q:'泡利原理指出：每个原子轨道里最多容纳的电子数及自旋方向是？',options:['2 个，自旋方向相同','1 个，任意方向','4 个，两两相反','2 个，自旋方向相反'],answer:3,explain:'每个原子轨道最多容纳 2 个电子，且自旋方向必须相反。'},
    {id:'k526',module:'选择性必修2·物质结构与性质',q:'能量最低原理的内容是：构建基态原子时，电子将尽可能？',options:['占据最高能级','占据能量最低的原子轨道','任意占据','占据最外层轨道'],answer:1,explain:'电子尽可能占据能量最低的轨道，使整个原子能量最低。'},
    {id:'k527',module:'选择性必修2·物质结构与性质',q:'铁(Fe)的简化电子排布式是？',options:['[Ar]3d⁵4s¹','[Ar]3d⁷','[Ar]3d⁶4s²','[Ar]4s²'],answer:2,explain:'Fe 原子序数 26，[Ar]3d⁶4s²。'},
    {id:'k528',module:'选择性必修2·物质结构与性质',q:'铜(Cu)的外围电子排布式是？',options:['3d¹⁰4s¹','4s¹','3d⁹4s²','3d¹⁰'],answer:0,explain:'Cu 外围（价层）电子为 3d¹⁰4s¹。'},
    {id:'k529',module:'选择性必修2·物质结构与性质',q:'原子(核素)符号中，元素符号左下方标明的是？',options:['中子数','质量数','电子数','质子数'],answer:3,explain:'左下方标质子数，左上方标质量数。'},
    {id:'k530',module:'选择性必修2·物质结构与性质',q:'电子式是用"·"或"×"表示元素原子的？',options:['内层电子','最外层电子','所有电子','价电子层全部'],answer:1,explain:'电子式在元素符号周围用·或×表示原子的最外层电子。'},
    {id:'k531',module:'选择性必修2·物质结构与性质',q:'简化电子排布式中，如 K 的 [Ar]4s¹，方括号 [Ar] 表示？',options:['最外层电子','内层达到稀有气体原子结构的部分','价电子','全部电子'],answer:1,explain:'把内层达到稀有气体结构的部分用相应稀有气体符号加方括号表示。'},
    {id:'k532',module:'选择性必修2·物质结构与性质',q:'对主族元素而言，价电子排布式是指？',options:['全部电子排布式','次外层电子排布式','最外层电子排布式','内层电子排布式'],answer:2,explain:'主族元素的价层电子即最外层电子，价电子排布式即最外层电子排布式。'},
    {id:'k533',module:'选择性必修2·物质结构与性质',q:'"三看"法比较微粒半径，当电子能层数不同时？',options:['能层数越多，半径越大','与能层数无关','核电荷数越大，半径越大','电子数越多，半径越小'],answer:0,explain:'一看能层数：能层数越多，半径一般越大。'},
    {id:'k534',module:'选择性必修2·物质结构与性质',q:'同周期元素的第一电离能从左到右总体上？',options:['逐渐增大（原子越来越难失电子）','先增后减','保持不变','逐渐减小'],answer:0,explain:'同周期第一电离能总体呈增大趋势，原子越来越难失去电子。'},
    {id:'k535',module:'选择性必修2·物质结构与性质',q:'同周期第 IIA 族与第 IIIA 族元素相比，第一电离能 I₁ 的大小是？',options:['第 IIA 族大于第 IIIA 族','第 IIA 族小于第 IIIA 族','二者相等','无法比较'],answer:0,explain:'IIA 族 ns 全满稳定，I₁ 大于 IIIA 族。'},
    {id:'k536',module:'选择性必修2·物质结构与性质',q:'同周期元素自左向右，电负性变化是？',options:['先增后减','逐渐增大，非金属性增强','逐渐减小','不变'],answer:1,explain:'同周期自左向右电负性逐渐增大，非金属性增强、金属性减弱。'},
    {id:'k537',module:'选择性必修2·物质结构与性质',q:'共价键是原子间通过什么形成的相互作用？',options:['得失电子','金属阳离子与自由电子','静电吸引','共用电子对'],answer:3,explain:'共价键是原子间通过共用电子对所形成的相互作用。'},
    {id:'k538',module:'选择性必修2·物质结构与性质',q:'共价键的成键微粒一般为？',options:['非金属原子与非金属原子','金属与阴离子','阳离子与阴离子','金属原子与金属原子'],answer:0,explain:'成键微粒一般为非金属原子与非金属原子。'},
    {id:'k539',module:'选择性必修2·物质结构与性质',q:'下列金属与非金属原子结合可形成共价键的是？',options:['AlCl₃ 和 BeCl₂','仅 AlCl₃','仅 BeCl₂','NaCl'],answer:0,explain:'部分金属与非金属结合也可形成共价键，如 AlCl₃、BeCl₂。'},
    {id:'k540',module:'选择性必修2·物质结构与性质',q:'σ 键是两个原子轨道沿键轴方向以什么方式重叠形成的？',options:['面对面','头碰头','平行','肩并肩'],answer:1,explain:'σ 键沿键轴"头碰头"重叠，具轴对称特征。'},
    {id:'k541',module:'选择性必修2·物质结构与性质',q:'π 键是两个原子的电子以什么方式发生轨道重叠形成的？',options:['直线','肩并肩','重叠','头碰头'],answer:1,explain:'π 键以"肩并肩"方式重叠，具镜面对称特征。'},
    {id:'k542',module:'选择性必修2·物质结构与性质',q:'关于 σ 键，下列说法正确的是？',options:['双键中不含 σ 键','共价单键为 σ 键','σ 键可单独旋转不破坏','π 键比 σ 键牢固'],answer:1,explain:'共价单键为 σ 键，双键、三键中均含一个 σ 键。'},
    {id:'k543',module:'选择性必修2·物质结构与性质',q:'关于 π 键，下列说法正确的是？',options:['通常存在于双键或三键中','比 σ 键牢固','可单独旋转不破坏','具轴对称特征'],answer:0,explain:'π 键通常存在于双键或三键中；其重叠程度小于 σ 键，不如 σ 键牢固，且不能旋转。'},
    {id:'k544',module:'选择性必修2·物质结构与性质',q:'CO₂ 分子的空间结构是？',options:['三角锥形','V 形','直线形（键角 180°）','正四面体形'],answer:2,explain:'CO₂ 为直线形，键角 180°。'},
    {id:'k545',module:'选择性必修2·物质结构与性质',q:'NH₃ 分子的空间结构是？',options:['V 形','直线形','三角锥形（键角约 107°）','平面三角形'],answer:2,explain:'NH₃ 为三角锥形，键角约 107°。'},
    {id:'k546',module:'选择性必修2·物质结构与性质',q:'H₂O 分子的空间结构是？',options:['V 形（键角约 105°）','正四面体形','直线形','三角锥形'],answer:0,explain:'H₂O 为 V 形，键角约 105°。'},
    {id:'k547',module:'选择性必修2·物质结构与性质',q:'CH₄ 分子的空间结构是？',options:['平面三角形','三角锥形','正四面体形（键角 109°28′）','V 形'],answer:2,explain:'CH₄ 为正四面体形，键角 109°28′。'},
    {id:'k548',module:'选择性必修2·物质结构与性质',q:'公式 孤电子对数 = 1/2(a − xb) 中，对主族元素来说 a 表示？',options:['中心原子最外层电子数','中心原子最外层加电荷','中心原子价电子数减电荷','原子序数'],answer:0,explain:'对主族元素 a = 原子最外层电子数；阳离子 a = 价电子−电荷，阴离子 a = 价电子+电荷。'},
    {id:'k549',module:'选择性必修2·物质结构与性质',q:'SO₂ 中中心原子 S 的孤电子对数为？',options:['3','0','2','1'],answer:3,explain:'a=6, x=2, b=2，1/2(6−2×2)=1。'},
    {id:'k550',module:'选择性必修2·物质结构与性质',q:'NH₄⁺ 中中心原子 N 的孤电子对数为？',options:['1','2','0','3'],answer:2,explain:'阳离子 a=5−1=4, x=4, b=1，1/2(4−4)=0。'},
    {id:'k551',module:'选择性必修2·物质结构与性质',q:'CO₃²⁻ 中中心原子 C 的孤电子对数为？',options:['1','3','2','0'],answer:3,explain:'阴离子 a=4+2=6, x=3, b=2，1/2(6−6)=0。'},
    {id:'k552',module:'选择性必修2·物质结构与性质',q:'价层电子对数为 2、孤电子对数为 0 时，分子空间结构为？',options:['三角锥形','V 形','平面三角形','直线形'],answer:3,explain:'2 对、0 孤对 → 直线形（如 CO₂、BeCl₂）。'},
    {id:'k553',module:'选择性必修2·物质结构与性质',q:'价层电子对数为 3、孤电子对数为 1 时，分子空间结构为？',options:['直线形','V 形','三角锥形','平面三角形'],answer:1,explain:'3 对、1 孤对 → V 形（如 SO₂）。'},
    {id:'k554',module:'选择性必修2·物质结构与性质',q:'价层电子对数为 4、孤电子对数为 1 时，分子空间结构为？',options:['三角锥形','平面三角形','V 形','正四面体形'],answer:0,explain:'4 对、1 孤对 → 三角锥形（如 NH₃）。'},
    {id:'k555',module:'选择性必修2·物质结构与性质',q:'价层电子对数为 4、孤电子对数为 0 时，分子空间结构为？',options:['直线形','三角锥形','正四面体形','V 形'],answer:2,explain:'4 对、0 孤对 → 正四面体形（如 CH₄）。'},
    {id:'k556',module:'选择性必修2·物质结构与性质',q:'氢键是由已经与电负性很强的原子形成共价键的氢原子与另一个电负性很强的原子之间的作用力。这里"电负性很强的原子"通常指？',options:['Na、Cl、S','N、O、F','C、H、O','任意原子'],answer:1,explain:'氢键通常存在于与 N、O、F 相连的 H 与另一 N、O、F 之间。'},
    {id:'k557',module:'选择性必修2·物质结构与性质',q:'关于氢键的本质，下列说法正确的是？',options:['氢键比分子间作用力强，但仍属于分子间作用力范畴','氢键是一种化学键','氢键只存在于分子内','氢键与范德华力无关'],answer:0,explain:'氢键不是化学键，而是一种较强的分子间作用力（也可分子内），属于分子间作用力范畴。'},
    {id:'k558',module:'选择性必修2·物质结构与性质',q:'当形成分子间氢键时，物质的熔、沸点通常？',options:['不变','升高','无法确定','降低'],answer:1,explain:'如 HF、H₂O、NH₃ 因分子间氢键熔沸点反常升高。'},
    {id:'k559',module:'选择性必修2·物质结构与性质',q:'关于氢键对密度的影响，下列说法正确的是？',options:['液态水密度大于固态冰','液态水密度小于固态冰','氢键不影响密度','气体密度减小'],answer:0,explain:'氢键使液态水密度 > 固态冰密度（冰中氢键使结构疏松）。'},
    {id:'k560',module:'选择性必修2·物质结构与性质',q:'极性共价键是指？',options:['共用电子对不发生偏移的共价键','金属键','阴阳离子间的键','共用电子对发生偏移（电荷分布不均匀）的共价键'],answer:3,explain:'共用电子对发生偏移的共价键称为极性键。'},
    {id:'k561',module:'选择性必修2·物质结构与性质',q:'非极性共价键是指？',options:['共用电子对发生偏移的共价键','极性分子的键','共用电子对不发生偏移（电荷分布均匀）的共价键','离子键'],answer:2,explain:'共用电子对不发生偏移的共价键称为非极性键（如 Cl₂、O₂）。'},
    {id:'k562',module:'选择性必修2·物质结构与性质',q:'下列分子属于非极性分子的是？',options:['SO₂','NH₃','H₂O','CH₄'],answer:3,explain:'ABn 型分子中，中心原子 A 上无孤电子对则为非极性分子；CH₄ 中心 C 无孤对电子，为非极性分子。'},
    {id:'k563',module:'选择性必修2·物质结构与性质',q:'判断 ABn 型分子极性时，"A 上有无孤电子对"决定？',options:['与分子极性无关','A 上无孤对电子→非极性分子；有孤对电子→极性分子','有孤对电子→非极性分子','仅由键的极性决定'],answer:1,explain:'ABn 型分子，中心原子无孤对电子一般为非极性分子，有孤对电子一般为极性分子。'},
    {id:'k564',module:'选择性必修2·物质结构与性质',q:'相似相溶规律指？',options:['非极性溶质易溶于非极性溶剂，极性溶质易溶于极性溶剂','极性溶质易溶于非极性溶剂','溶解度与分子极性无关','所有物质都易溶于水'],answer:0,explain:'非极性溶质一般溶于非极性溶剂，极性溶质一般溶于极性溶剂。'},
    {id:'k565',module:'选择性必修2·物质结构与性质',q:'一般来说，温度对固体物质溶解度的影响是？',options:['温度越高，固体溶解度越小','温度越高，固体溶解度越大（Ca(OH)₂ 除外）','无影响','仅压强影响'],answer:1,explain:'多数固体溶解度随温度升高而增大，Ca(OH)₂ 反常随温度升高而减小。'},
    {id:'k566',module:'选择性必修2·物质结构与性质',q:'影响气体溶解度的主要外界因素是？',options:['与压强无关','压强越大、温度越低，气体溶解度越大','仅温度','仅浓度'],answer:1,explain:'压强越大气体溶解度越大，温度越高溶解度越小。'},
    {id:'k567',module:'选择性必修2·物质结构与性质',q:'乙醇与水互溶，而戊醇在水中溶解度明显减小，主要原因是？',options:['乙醇与水的分子结构更相似','乙醇不形成氢键','戊醇分子量更小','戊醇极性更强'],answer:0,explain:'分子结构相似性越大溶解性越大；乙醇与水结构相似且能形成氢键，故互溶。'},
    {id:'k568',module:'选择性必修2·物质结构与性质',q:'手性异构体是指？',options:['组成不同的一对分子','同分异构体总称','能叠合的镜像分子','组成和原子排列完全相同、互为镜像却不能在三维空间叠合的一对分子'],answer:3,explain:'手性异构体（对映异构体）组成和原子排列完全相同、互为镜像但不能叠合。'},
    {id:'k569',module:'选择性必修2·物质结构与性质',q:'有手性异构体的分子称为？',options:['手性原子','非极性分子','极性分子','手性分子'],answer:3,explain:'有手性异构体的分子叫手性分子。'},
    {id:'k570',module:'选择性必修2·物质结构与性质',q:'判断有机物是否具有手性异构体，关键是看？',options:['分子量大小','是否含羟基','是否含连有 4 个不同原子或原子团的碳原子（手性碳）','是否含双键'],answer:2,explain:'有机物分子中是否存在手性碳原子（连有 4 个不同原子或原子团的碳）是判断手性的关键。'},
    {id:'k571',module:'选择性必修2·物质结构与性质',q:'晶体是内部粒子在三维空间按一定规律怎样排列构成的固体？',options:['周期性重复排列','杂乱无章分布','随机排列','单层排列'],answer:0,explain:'晶体内部粒子在三维空间呈周期性重复排列。'},
    {id:'k572',module:'选择性必修2·物质结构与性质',q:'下列属于非晶体的是？',options:['干冰','金刚石','玻璃','金属铜'],answer:2,explain:'玻璃、松香、橡胶、沥青等是非晶体；金刚石、干冰、金属铜是晶体。'},
    {id:'k573',module:'选择性必修2·物质结构与性质',q:'获得晶体的途径不包括？',options:['溶质从溶液中析出','熔融态物质凝固','非晶态直接压缩','气态物质凝华'],answer:2,explain:'获得晶体途径：熔融态凝固、气态凝华、溶质从溶液析出。'},
    {id:'k574',module:'选择性必修2·物质结构与性质',q:'晶体区别于非晶体的本质特征是？',options:['导电','透明','结构微粒周期性有序排列','有颜色'],answer:2,explain:'本质区别是结构微粒周期性有序排列。'},
    {id:'k575',module:'选择性必修2·物质结构与性质',q:'晶体具有自范性，而下列性质中晶体表现为？',options:['各向同性','无固定熔沸点','各向异性','无规则外形'],answer:2,explain:'晶体有自范性、固定熔沸点、各向异性；非晶体各向同性。'},
    {id:'k576',module:'选择性必修2·物质结构与性质',q:'科学区分晶体与非晶体的方法是？',options:['看颜色','测密度','看是否有固定熔沸点（间接）','对固体进行 X-射线衍射实验'],answer:3,explain:'科学方法是 X-射线衍射实验；看固定熔沸点只是间接方法。'},
    {id:'k577',module:'选择性必修2·物质结构与性质',q:'关于晶胞与晶体的关系，"无隙并置"是指？',options:['晶胞取向随机','晶胞间有空隙','相邻晶胞无间隙、平行排列取向相同','晶胞大小不同'],answer:2,explain:'晶胞"无隙并置"：相邻晶胞无任何间隙，平行排列且取向相同。'},
    {id:'k578',module:'选择性必修2·物质结构与性质',q:'长方体晶胞中，处于顶点上的粒子，每个粒子属于该晶胞的份额是？',options:['1/4','1/8','1/2','1'],answer:1,explain:'顶点粒子同时为 8 个晶胞共有，每个占 1/8。'},
    {id:'k579',module:'选择性必修2·物质结构与性质',q:'长方体晶胞中，处于棱边上的粒子，每个粒子属于该晶胞的份额是？',options:['1','1/2','1/8','1/4'],answer:3,explain:'棱边粒子为 4 个晶胞共有，每个占 1/4。'},
    {id:'k580',module:'选择性必修2·物质结构与性质',q:'长方体晶胞中，处于晶面上的粒子，每个粒子属于该晶胞的份额是？',options:['1/8','1','1/4','1/2'],answer:3,explain:'晶面粒子为 2 个晶胞共有，每个占 1/2。'},
    {id:'k581',module:'选择性必修2·物质结构与性质',q:'六方晶胞中，位于顶角上的粒子属于该晶胞的份额是？',options:['1/3','1/8','1/2','1/6'],answer:3,explain:'六方晶胞顶角粒子每个占 1/6。'},
    {id:'k582',module:'选择性必修2·物质结构与性质',q:'六方晶胞中，位于棱上的粒子属于该晶胞的份额是？',options:['1/6','1/2','1/3','1/4'],answer:2,explain:'六方晶胞棱上粒子每个占 1/3。'},
    {id:'k583',module:'选择性必修2·物质结构与性质',q:'六方晶胞（如石墨、六方最密堆积）中所含粒子数目计算为 12×1/6 + 3 + 2×1/2 = ？',options:['4','8','5','6'],answer:3,explain:'12×1/6=2，2×1/2=1，加上内部 3，共 2+3+1=6 个粒子。'},
    {id:'k584',module:'选择性必修2·物质结构与性质',q:'分子晶体是只含什么微粒的晶体？',options:['分子','电子','离子','原子'],answer:0,explain:'分子晶体由分子构成，微粒间以分子间作用力结合。'},
    {id:'k585',module:'选择性必修2·物质结构与性质',q:'干冰（固态 CO₂）晶体中，CO₂ 分子之间是否存在氢键？',options:['只存在范德华力，不存在氢键','存在氢键','既存在氢键又存在范德华力','存在共价键网络'],answer:0,explain:'干冰中 CO₂ 分子间只存在范德华力，不存在氢键（CO₂ 不含与 N/O/F 相连的 H）。'},
    {id:'k586',module:'选择性必修2·物质结构与性质',q:'干冰晶胞中每个顶点和面心各有一个 CO₂ 分子，每个晶胞含有的 CO₂ 分子数是？',options:['12','6','4','8'],answer:2,explain:'8×1/8 + 6×1/2 = 1 + 3 = 4 个。'},
    {id:'k587',module:'选择性必修2·物质结构与性质',q:'在干冰晶体中，每个 CO₂ 分子周围离它最近且距离相等的 CO₂ 分子有？',options:['12 个','4 个','6 个','8 个'],answer:0,explain:'干冰为面心立方，每个 CO₂ 周围有 12 个最近邻 CO₂ 分子。'},
    {id:'k588',module:'选择性必修2·物质结构与性质',q:'比较分子晶体熔沸点时，应优先考虑？',options:['颜色','是否含氢键（先氢键，后范德华力，最后极性）','密度','分子量大小'],answer:1,explain:'先氢键→后范德华力→再分子极性；含分子间氢键者熔沸点更高。'},
    {id:'k589',module:'选择性必修2·物质结构与性质',q:'结构相似、不含氢键的分子晶体，其熔沸点随相对分子质量增大而？',options:['降低','不变','先升后降','升高'],answer:3,explain:'如 I₂ > Br₂ > Cl₂ > F₂，随相对分子质量增大熔沸点升高。'},
    {id:'k590',module:'选择性必修2·物质结构与性质',q:'相对分子质量相近时，极性分子构成的分子晶体熔沸点一般比非极性分子？',options:['无法比较','更低','相等','更高（如 CO > N₂）'],answer:3,explain:'CO 与 N₂ 相对分子质量相近，CO 为极性分子，熔沸点高于非极性的 N₂。'},
    {id:'k591',module:'选择性必修2·物质结构与性质',q:'同分异构体中，支链越多则分子间作用力越弱，熔沸点？',options:['越低（正戊烷 > 异戊烷 > 新戊烷）','越高','随机','不变'],answer:0,explain:'支链越多熔沸点越低：正戊烷 > 异戊烷 > 新戊烷。'},
    {id:'k592',module:'选择性必修2·物质结构与性质',q:'共价晶体（原子晶体）是指相邻原子间以什么结合形成空间立体网状结构的晶体？',options:['分子间作用力','共价键','离子键','金属键'],answer:1,explain:'共价晶体中相邻原子以共价键结合成空间网状结构。'},
    {id:'k593',module:'选择性必修2·物质结构与性质',q:'下列物质中属于共价晶体的是？',options:['干冰、冰','金刚石、晶体硅、SiO₂','钠、铁','NaCl、KBr'],answer:1,explain:'常见共价晶体有金刚石、晶体硅、晶体锗、SiC、SiO₂、BN 等。'},
    {id:'k594',module:'选择性必修2·物质结构与性质',q:'关于金刚石，下列说法不正确的是？',options:['原子半径 r 与晶胞边长 a 关系为 a = 8r','金刚石是分子晶体','每个 C 与周围 4 个 C 成键','C—C—C 夹角为 109°28′'],answer:1,explain:'金刚石是典型共价晶体，不是分子晶体。'},
    {id:'k595',module:'选择性必修2·物质结构与性质',q:'金刚石中每个碳原子与周围紧邻的碳原子以共价键结合成？',options:['平面三角形','八面体','直线形','正四面体结构，向空间伸展成网状'],answer:3,explain:'每个 C 与 4 个相邻 C 形成正四面体结构，构成空间网状。'},
    {id:'k596',module:'选择性必修2·物质结构与性质',q:'金刚石中碳原子采取的杂化方式及键角是？',options:['sp³，109°28′','sp²，120°','sp³d，90°','sp，180°'],answer:0,explain:'金刚石中 C 为 sp³ 杂化，C—C—C 夹角 109°28′。'},
    {id:'k597',module:'选择性必修2·物质结构与性质',q:'每个金刚石晶胞含有的碳原子数是？',options:['6','4','12','8'],answer:3,explain:'晶胞顶点 8×1/8 + 面心 6×1/2 + 内部 4 = 1+3+4 = 8 个 C 原子。'},
    {id:'k598',module:'选择性必修2·物质结构与性质',q:'关于金刚石的最小碳环，下列说法正确的是？',options:['最小环由 4 个碳原子组成','最小环共面','最小环由 6 个碳原子组成，且不在同一平面','最小环由 12 个碳原子组成'],answer:2,explain:'金刚石最小环为 6 元环，6 个 C 不在同一平面内（椅式结构）。'},
    {id:'k599',module:'选择性必修2·物质结构与性质',q:'晶体硅的结构与下列哪种晶体相同，可看作将其晶胞中的 C 换成 Si？',options:['NaCl','干冰','石墨','金刚石'],answer:3,explain:'晶体硅与金刚石结构相同，将金刚石晶胞中 C 全换成 Si 即得晶体硅晶胞。'},
    {id:'k600',module:'选择性必修2·物质结构与性质',q:'每个硅晶胞中含有的硅原子数是？',options:['6','4','12','8'],answer:3,explain:'同金刚石，每个硅晶胞含 8 个 Si 原子。'},
    {id:'k601',module:'选择性必修2·物质结构与性质',q:'关于 Si 与 Si—Si 键数目之比，1 mol 晶体硅中含共价键的物质的量为？',options:['Si : Si—Si = 1:4，含 4 mol 共价键','Si : Si—Si = 2:1，含 0.5 mol 共价键','Si : Si—Si = 1:2，含 2 mol 共价键','Si : Si—Si = 1:1，含 1 mol 共价键'],answer:2,explain:'硅原子数与 Si—Si 键数之比为 1:2，1 mol Si 含 2 mol 共价键。'},
    {id:'k602',module:'选择性必修2·物质结构与性质',q:'SiO₂ 晶体中最小的环是几元环，由哪些原子组成？',options:['12 元环，6 个 Si 和 6 个 O','8 元环，4 Si 4 O','6 元环，6 个 Si','4 元环，2 Si 2 O'],answer:0,explain:'SiO₂ 最小环为 12 元环，含 6 个 Si 和 6 个 O。'},
    {id:'k603',module:'选择性必修2·物质结构与性质',q:'SiO₂ 晶体中，正四面体之间的 Si—O—Si 夹角约为？',options:['120°','104°30′','109°28′','180°'],answer:1,explain:'正四面体内 O—Si—O 为 109°28′，正四面体之间 Si—O—Si 为 104°30′。'},
    {id:'k604',module:'选择性必修2·物质结构与性质',q:'SiO₂ 晶体中硅原子与氧原子的个数比是？',options:['1:4','1:1','1:2','2:1'],answer:2,explain:'每个 Si 连 4 个 O，每个 O 被 2 个 Si 共有，Si:O = 1:2。'},
    {id:'k605',module:'选择性必修2·物质结构与性质',q:'每个 SiO₂ 晶胞中含有的 Si 原子数和 O 原子数分别是？',options:['4 个 Si，8 个 O','8 个 Si，16 个 O','4 个 Si，4 个 O','8 个 Si，8 个 O'],answer:1,explain:'每个 SiO₂ 晶胞含 8 个 Si 原子、16 个 O 原子。'},
    {id:'k606',module:'选择性必修2·物质结构与性质',q:'每个 SiC 晶胞含有的原子组成是？',options:['4 个 Si 和 4 个 C','8 个 Si 和 8 个 C','4 个 Si 和 8 个 C','2 个 Si 和 2 个 C'],answer:0,explain:'SiC 晶胞与金刚石相似，含 4 个 Si 和 4 个 C。'},
    {id:'k607',module:'选择性必修2·物质结构与性质',q:'SiC 晶体中最小碳环的组成是？',options:['12 个原子','6 个 C','4 个 C 和 4 个 Si','6 个原子，含 3 个 C 和 3 个 Si'],answer:3,explain:'最小碳环由 6 个原子组成且不在同一平面，含 3 个 C 和 3 个 Si。'},
    {id:'k608',module:'选择性必修2·物质结构与性质',q:'若 Si 与 C 最近距离为 d，则 SiC 晶胞边长 a 与 d 的关系是？',options:['a = 4d','3a = 4d','a = 2d','√3 a = 4d'],answer:1,explain:'SiC 中 3a = 4d（a 为晶胞边长，d 为 Si—C 最近距离）。'},
    {id:'k609',module:'选择性必修2·物质结构与性质',q:'判断晶体类型时，组成共价晶体的粒子及作用力是？',options:['分子、分子间作用力','原子、共价键','离子、离子键','金属阳离子、金属键'],answer:1,explain:'共价晶体由原子构成，粒子间作用力为共价键。'},
    {id:'k610',module:'选择性必修2·物质结构与性质',q:'下列物质中属于共价晶体的是？',options:['NaCl、MgO','金刚石、晶体硅、SiO₂、SiC、BN','钠、铜','干冰、冰、I₂'],answer:1,explain:'金刚石、晶体硅、SiO₂、SiC、BN、AlN 等通常为共价晶体。'},
    {id:'k611',module:'选择性必修2·物质结构与性质',q:'依据熔点判断：共价晶体熔沸点常在什么范围？',options:['常在数百摄氏度以下','都低于 0 ℃','常在 1000 ℃ 以上','与分子晶体相同'],answer:2,explain:'共价晶体熔沸点高，常在 1000 ℃ 以上；分子晶体常在数百摄氏度以下。'},
    {id:'k612',module:'选择性必修2·物质结构与性质',q:'常温下呈气态或液态的物质，其固态时一般属于？',options:['金属晶体','共价晶体','离子晶体','分子晶体'],answer:3,explain:'常温下气态或液态的单质与化合物，固态时多属于分子晶体。'},
    {id:'k613',module:'选择性必修2·物质结构与性质',q:'金属晶体是通过什么作用形成的晶体？',options:['离子键','金属阳离子与自由电子之间的较强作用（金属键）','分子间作用力','共价键'],answer:1,explain:'金属晶体由金属阳离子与自由电子通过金属键结合。'},
    {id:'k614',module:'选择性必修2·物质结构与性质',q:'金属键的强弱主要取决于？',options:['相对分子质量','氢键','原子半径和价电子数（半径越小、价电子越多，金属键越强）','颜色'],answer:2,explain:'原子半径越小、价电子数越多，金属键越强。'},
    {id:'k615',module:'选择性必修2·物质结构与性质',q:'离子晶体是由什么构成的晶体？',options:['分子','原子','阴、阳离子通过离子键结合','金属阳离子与自由电子'],answer:2,explain:'离子晶体由阴、阳离子通过离子键结合而成。'},
    {id:'k616',module:'选择性必修2·物质结构与性质',q:'离子晶体熔化时破坏的作用力是？',options:['金属键','分子间作用力','离子键','共价键'],answer:2,explain:'离子晶体熔化（或溶于水）时离子键被削弱/断裂，破坏的是离子键。'},
    {id:'k617',module:'选择性必修2·物质结构与性质',q:'离子晶体常温下一般为固态，具有怎样熔沸点？',options:['较低','极低','不固定','较高（离子键强，需消耗较多能量）'],answer:3,explain:'离子晶体有较强离子键，熔沸点较高、难挥发。'},
    {id:'k618',module:'选择性必修2·物质结构与性质',q:'离子晶体熔沸点高低的比较规律是？',options:['半径越大越高','电荷越小越高','阴、阳离子电荷数越大、离子半径越小，离子键越强，熔沸点越高','与电荷、半径无关'],answer:2,explain:'电荷越大、半径越小，离子键越强，熔沸点越高。'},
    {id:'k619',module:'选择性必修2·物质结构与性质',q:'不同类型晶体熔沸点一般规律是？',options:['共价晶体 > 离子晶体 > 分子晶体','离子晶体 > 共价晶体 > 分子晶体','分子晶体 > 离子晶体 > 共价晶体','三者无明显规律'],answer:0,explain:'一般规律：共价晶体 > 离子晶体 > 分子晶体。'},
    {id:'k620',module:'选择性必修2·物质结构与性质',q:'金刚石熔点比 NaCl 高的原因是？',options:['二者均为分子晶体','金刚石是分子晶体','金刚石是共价晶体，NaCl 是离子晶体','NaCl 是共价晶体'],answer:2,explain:'金刚石为共价晶体，NaCl 为离子晶体，共价晶体熔点通常更高。'},
    {id:'k621',module:'选择性必修2·物质结构与性质',q:'配位键是成键原子一方提供什么、另一方提供什么形成的共价键？',options:['提供空轨道；提供孤电子对','得失电子','各提供 1 个电子','提供孤电子对；提供空轨道'],answer:3,explain:'配位键由一方提供孤电子对、另一方提供空轨道形成。'},
    {id:'k622',module:'选择性必修2·物质结构与性质',q:'下列能作为配位键"提供孤电子对"一方的是？',options:['仅过渡金属离子','H⁺、Al³⁺','Na⁺','NH₃、H₂O、CO、Cl⁻'],answer:3,explain:'能提供孤电子对的如 NH₃、H₂O、HF、CO、Cl⁻、OH⁻、CN⁻、SCN⁻ 等。'},
    {id:'k623',module:'选择性必修2·物质结构与性质',q:'配位键常用 A→B 表示，其中 A 和 B 分别是？',options:['A 提供空轨道，B 提供孤电子对','A、B 各提供 1 电子','A 提供孤电子对，B 接受孤电子对','A 为阳离子'],answer:2,explain:'A→B 中 A 是提供孤电子对的原子，B 是接受孤电子对的原子。'},
    {id:'k624',module:'选择性必修2·物质结构与性质',q:'关于过渡金属形成配位键的数目，下列说法正确的是？',options:['都随时间变化','都为 1 个','与原子无关','Ag⁺ 形成 2 个配位键，Cu²⁺ 形成 4 个配位键'],answer:3,explain:'多数过渡金属配位数基本固定，如 Ag⁺ 形成 2 个配位键、Cu²⁺ 形成 4 个配位键。'},
    {id:'k625',module:'选择性必修3·有机化学',q:'依据碳原子组成的分子骨架，有机化合物主要分为哪两类？',options:['烃和烃的衍生物','烷烃和烯烃','链状化合物和环状化合物','脂肪族化合物和芳香族化合物'],answer:2,explain:'按碳骨架分为链状化合物（脂肪族）和环状化合物（脂环+芳香族）。'},
    {id:'k626',module:'选择性必修3·有机化学',q:'下列关于链状化合物的说法，正确的是？',options:['链状化合物又称脂肪族化合物，最初从油脂中发现','链状化合物均溶于水','链状化合物都不含双键','链状化合物只含烷烃'],answer:0,explain:'链状化合物因最初从油脂中发现又称脂肪族化合物，包括脂肪烃及衍生物，可含双键（如烯烃）。'},
    {id:'k627',module:'选择性必修3·有机化学',q:'下列物质中属于芳香族化合物的是？',options:['苯','环己烯','环己烷','环戊烷'],answer:0,explain:'含一个或多个苯环的化合物为芳香族化合物，苯含苯环属此类；环烷烃、环烯烃不含苯环，属脂环化合物。'},
    {id:'k628',module:'选择性必修3·有机化学',q:'脂肪烃一般包括下列哪几类？',options:['烷烃、烯烃、炔烃','卤代烃、羧酸、酯','脂环烃和芳香烃','醇、酚、醛'],answer:0,explain:'脂肪烃指不含苯环的链状烃，包括烷烃、烯烃、炔烃。'},
    {id:'k629',module:'选择性必修3·有机化学',q:'决定有机化合物特性的原子或原子团称为？',options:['同系物','官能团','取代基','烃基'],answer:1,explain:'官能团是决定有机物特性的原子或原子团，如—OH、—COOH。'},
    {id:'k630',module:'选择性必修3·有机化学',q:'烃的衍生物是指？',options:['烃分子中 H 被其他原子或原子团取代得到的物质','高分子化合物','仅含 C、H 的化合物','含苯环的化合物'],answer:0,explain:'烃的衍生物是烃分子中氢原子被其他原子或原子团取代所得，如 CH3Cl、CH3CH2OH。'},
    {id:'k631',module:'选择性必修3·有机化学',q:'乙醇的官能团名称和结构简式分别是？',options:['羧基，—COOH','醚键，—O—','醛基，—CHO','羟基，—OH'],answer:3,explain:'乙醇（CH3CH2OH）官能团为羟基，结构简式—OH。'},
    {id:'k632',module:'选择性必修3·有机化学',q:'下列官能团与物质对应正确的是？',options:['乙醛—酮羰基','乙酰胺—氨基','乙酸乙酯—羧基','溴乙烷—碳卤键'],answer:3,explain:'溴乙烷（CH3CH2Br）官能团为碳卤键；乙醛官能团是醛基，乙酸乙酯是酯基，乙酰胺是酰胺基。'},
    {id:'k633',module:'选择性必修3·有机化学',q:'同分异构体是指？',options:['结构相同、分子式不同的化合物','相差一个 CH2 的化合物','分子式相同、结构不同的化合物','同种元素形成的不同单质'],answer:2,explain:'同分异构体=相同分子式+不同结构；B 不存在，C 为同素异形体，D 为同系物。'},
    {id:'k634',module:'选择性必修3·有机化学',q:'正丁烷与异丁烷的异构属于？',options:['顺反异构','位置异构','碳架异构','官能团异构'],answer:2,explain:'二者分子式相同、碳链骨架不同，属碳架异构。'},
    {id:'k635',module:'选择性必修3·有机化学',q:'乙醇与二甲醚互为同分异构体，属于哪类异构？',options:['构象异构','官能团异构','位置异构','碳架异构'],answer:1,explain:'乙醇（醇）与二甲醚（醚）官能团类别不同，属官能团异构。'},
    {id:'k636',module:'选择性必修3·有机化学',q:'戊烷的同分异构体数目是？',options:['2','3','4','5'],answer:1,explain:'戊烷有正戊烷、异戊烷、新戊烷共 3 种碳架异构。'},
    {id:'k637',module:'选择性必修3·有机化学',q:'下列关于结构简式的书写，正确的是？',options:['醛基可简写为—CHO，羧基可简写为—COOH','碳碳双键、三键可省略','乙烷结构简式为 CH2CH2','结构简式中不写任何官能团'],answer:0,explain:'结构简式中 C=C、C≡C 不能省略；醛基—CHO、羧基—COOH 为约定简写；乙烷为 CH3CH3。'},
    {id:'k638',module:'选择性必修3·有机化学',q:'能反映分子空间构型（立体形状）的表示方法是？',options:['球棍模型/比例模型','实验式','结构式','结构简式'],answer:0,explain:'球棍模型与比例模型用于表示分子空间结构；结构式/简式只反映连接顺序不表空间构型。'},
    {id:'k639',module:'选择性必修3·有机化学',q:'乙烯的实验式（最简式）是？',options:['C2H4','C2H2','CH','CH2'],answer:3,explain:'乙烯分子式 C2H4，各元素最简整数比为 CH2。'},
    {id:'k640',module:'选择性必修3·有机化学',q:'蒸馏法分离液态有机混合物的原理是利用各组分的？',options:['密度不同','溶解度不同','沸点不同','分子量不同'],answer:2,explain:'蒸馏利用互溶液体混合物中各组分沸点不同进行分离，一般要求沸点差 >30℃。'},
    {id:'k641',module:'选择性必修3·有机化学',q:'选择萃取剂的原则不包括？',options:['萃取剂与溶质不反应','溶质在萃取剂中溶解度远大于原溶剂','萃取剂与原溶剂互不相溶且不反应','萃取剂沸点必须高于水'],answer:3,explain:'萃取剂三原则：溶解度大、与原溶剂不互溶不反应、与溶质不反应；对沸点无此要求。'},
    {id:'k642',module:'选择性必修3·有机化学',q:'重结晶法提纯固体有机物，所选溶剂应满足？',options:['被提纯物在热溶剂中溶解度大、冷溶剂中溶解度小','被提纯物在任何温度下均不溶','溶剂必须与水互溶','杂质溶解度与被提纯物相同'],answer:0,explain:'重结晶利用溶解度随温度变化大来析出晶体，杂质溶解度应很大或很小易于除去。'},
    {id:'k643',module:'选择性必修3·有机化学',q:'色谱法分离混合物的依据是？',options:['沸点差异','样品不同组分在两相（流动相/固定相）间分配不同','密度差异','颜色差异'],answer:1,explain:'色谱法因各组分在流动相与固定相间分配不同而实现分离。'},
    {id:'k644',module:'选择性必修3·有机化学',q:'确定有机物实验式（最简式）常用的方法是？',options:['元素分析（燃烧法测各元素质量分数）','质谱法','红外光谱','核磁共振氢谱'],answer:0,explain:'元素分析通过燃烧定量测定 C、H、N 等产物质量，推得各元素最简整数比即实验式。'},
    {id:'k645',module:'选择性必修3·有机化学',q:'质谱图中相对分子质量由什么确定？',options:['化学位移','红外吸收频率','吸收峰面积','质荷比最大的分子离子峰'],answer:3,explain:'质谱图最右侧分子离子峰（最大质荷比）对应样品相对分子质量。'},
    {id:'k646',module:'选择性必修3·有机化学',q:'红外光谱的主要作用是？',options:['测定氢原子种类和数目','确定相对分子质量','确定晶体结构','初步判断含有的化学键或官能团'],answer:3,explain:'不同化学键/官能团红外吸收频率不同，红外光谱可初步判断其存在。'},
    {id:'k647',module:'选择性必修3·有机化学',q:'核磁共振氢谱中，吸收峰的数目与面积比分别代表？',options:['碳原子种类数、碳氢比','氢原子总数、氢的种类数','氢原子种类数、各类氢原子个数比','官能团数目、分子量'],answer:2,explain:'峰数目=氢原子类型数；峰面积比=各类氢原子个数比。'},
    {id:'k648',module:'选择性必修3·有机化学',q:'X 射线衍射可用于？',options:['确定相对分子质量','判断官能团','测定氢原子种类','获得键长、键角等分子结构数据'],answer:3,explain:'X 射线衍射可获得键长、键角等结构数据，尤其用于晶体结构测定。'},
    {id:'k649',module:'选择性必修3·有机化学',q:'甲烷的分子构型是？',options:['直线形','平面正方形','平面三角形','正四面体'],answer:3,explain:'CH4 为正四面体，C 在中心、4 个 H 在顶点，键角 109°28′。'},
    {id:'k650',module:'选择性必修3·有机化学',q:'甲烷与氯气在光照下的反应属于？',options:['取代反应','加成反应','氧化反应','消去反应'],answer:0,explain:'CH4 中 H 被 Cl 取代生成 CH3Cl 等，属取代反应。'},
    {id:'k651',module:'选择性必修3·有机化学',q:'下列关于甲烷化学性质的描述，正确的是？',options:['能与强碱反应','易与溴水发生加成','通常较稳定，不与强酸、强碱、强氧化剂反应','能使酸性 KMnO4 褪色'],answer:2,explain:'甲烷化学性质稳定，一般不与强酸、强碱、高锰酸钾等强氧化剂反应。'},
    {id:'k652',module:'选择性必修3·有机化学',q:'甲烷分子中碳原子的杂化方式是？',options:['不杂化','sp3','sp2','sp'],answer:1,explain:'甲烷 C 形成 4 个 σ 键，采取 sp3 杂化。'},
    {id:'k653',module:'选择性必修3·有机化学',q:'烷烃系统命名时，选主链的原则是？',options:['任选一条碳链','选碳原子数最少的','选含支链最多的碳链','选最长碳链；等长时选支链最多的'],answer:3,explain:'系统命名选最长碳链为主链，等长时取支链最多者。'},
    {id:'k654',module:'选择性必修3·有机化学',q:'编号时使支链位次最小，若两端距支链同近且支链不同，应？',options:['从较复杂支链一端编号','从中间编号','随意编号','从较简单支链一端编号'],answer:3,explain:'两端同近且支链不同，从较简单支链一端开始编号。'},
    {id:'k655',module:'选择性必修3·有机化学',q:'下列烃基位号书写正确的是？',options:['2—乙基','3—丙基','2,3—二甲基','1—甲基'],answer:2,explain:'烷烃命名中不会出现"1—甲基、2—乙基、3—丙基"（主链选错）；相同取代基合并用中文数字，位号间用逗号。'},
    {id:'k657',module:'选择性必修3·有机化学',q:'同系物是指？',options:['结构相似，分子组成相差一个或若干个 CH2 的化合物','分子式相同、结构不同的物质','同种元素形成的不同单质','质子数相同中子数不同的原子'],answer:0,explain:'同系物=结构相似+相差 n 个 CH2；A 为同分异构体，C 为同素异形体，D 为同位素。'},
    {id:'k658',module:'选择性必修3·有机化学',q:'下列各组中互为同系物的是？',options:['金刚石与石墨','乙烯与环丙烷','甲烷与乙烷','正丁烷与异丁烷'],answer:2,explain:'甲烷、乙烷均为烷烃，相差 CH2，互为同系物；乙烯与环丙烷结构不相似，正丁烷与异丁烷为同分异构体，金刚石与石墨为同素异形体。'},
    {id:'k659',module:'选择性必修3·有机化学',q:'关于同位素、同素异形体、同系物、同分异构体的对象，正确的是？',options:['同系物对象为无机物','同位素对象为原子；同素异形体对象为单质','同分异构体对象仅为无机物','同素异形体对象为化合物'],answer:1,explain:'同位素对象原子，同素异形体对象单质，同系物对象有机化合物，同分异构体对象无机/有机化合物均可。'},
    {id:'k660',module:'选择性必修3·有机化学',q:'乙烯分子中碳原子的杂化方式及空间构型是？',options:['sp，直线形','sp3，正四面体','sp2，正四面体','sp2，所有原子共平面'],answer:3,explain:'乙烯 C 为 sp2 杂化，键角约 120°，6 个原子共平面。'},
    {id:'k662',module:'选择性必修3·有机化学',q:'乙烯燃烧产生黑烟的原因是？',options:['乙烯密度大','乙烯中碳的质量分数大（约 85.7%），燃烧不完全产生碳粒','乙烯含氮','乙烯含氧量高'],answer:1,explain:'乙烯含碳量高，燃烧不完全产生碳微粒致黑烟。'},
    {id:'k663',module:'选择性必修3·有机化学',q:'乙烯的用途不包括？',options:['衡量石油化工发展水平的标志','直接作高能燃料','合成高分子材料的原料','植物果实催熟剂'],answer:1,explain:'乙烯是重要化工原料、催熟剂、石化水平标志，一般不直接作高能燃料。'},
    {id:'k664',module:'选择性必修3·有机化学',q:'乙烯与溴的四氯化碳溶液反应的产物是？',options:['CH2Br—CH2Br','CH≡CH','CHBr2—CH3','CH3CH2Br'],answer:0,explain:'乙烯与 Br2 发生加成生成 1,2-二溴乙烷（CH2Br—CH2Br），使溴的 CCl4 溶液褪色。'},
    {id:'k665',module:'选择性必修3·有机化学',q:'实验室中可用乙烯与下列哪种试剂加成来制取纯净的氯乙烷？',options:['Cl2','H2O','H2','HCl'],answer:3,explain:'CH2=CH2 + HCl → CH3CH2Cl，可得纯净氯乙烷；与 Cl2 加成得 1,2-二氯乙烷。'},
    {id:'k666',module:'选择性必修3·有机化学',q:'乙烯在一定条件下与水加成可制取？',options:['乙酸','氯乙烷','乙醇','乙醛'],answer:2,explain:'CH2=CH2 + H2O → CH3CH2OH（乙醇），工业制乙醇方法之一。'},
    {id:'k667',module:'选择性必修3·有机化学',q:'由不饱和小分子通过加成结合成高分子的反应称为？',options:['酯化反应','消去反应','加成聚合反应（加聚反应）','取代反应'],answer:2,explain:'加聚反应是不饱和单体经加成形成高分子的反应，如乙烯加聚成聚乙烯。'},
    {id:'k668',module:'选择性必修3·有机化学',q:'烯烃燃烧的通式中，CnH2n 完全燃烧产物系数为？',options:['nCO2 + (n-1)H2O','2nCO2 + nH2O','nCO2 + nH2O','nCO2 + (n+1)H2O'],answer:2,explain:'CnH2n + 3n/2 O2 → nCO2 + nH2O。'},
    {id:'k669',module:'选择性必修3·有机化学',q:'1,3-丁二烯与溴水按 1:1 反应时，可生成？',options:['仅 1,4-加成产物','1,2-加成或 1,4-加成产物','不发生反应','仅 1,2-加成产物'],answer:1,explain:'共轭二烯烃与 Br2 1:1 加成可发生 1,2-加成（活泼键断裂）或 1,4-加成（双键一起断裂并新生双键）。'},
    {id:'k670',module:'选择性必修3·有机化学',q:'烯烃的物理性质递变规律，正确的是？',options:['密度均大于水','均易溶于水','相同分子式，支链越多熔沸点越低','碳原子数增多，熔沸点降低'],answer:2,explain:'同碳数烯烃支链越多熔沸点越低；碳原子数增多熔沸点升高；烯烃难溶于水、密度比水小。'},
    {id:'k671',module:'选择性必修3·有机化学',q:'丙烯与 HCl 加成，主产物可能是？',options:['不反应','仅 CH3CHClCH3','仅 CH3CH2CH2Cl','CH3CHClCH3 或 CH3CH2CH2Cl'],answer:3,explain:'不对称烯烃与 HCl 加成可因 H 加在不同碳上得两种产物（符合马氏规则通常以 2-氯丙烷为主，但题目考两种可能性）。'},
    {id:'k672',module:'选择性必修3·有机化学',q:'烯烃系统命名时，主链必须？',options:['含有双键的最长碳链','不含支链','任取一条碳链','含碳原子数最多即可，不必含双键'],answer:0,explain:'烯烃命名主链须含双键且最长，编号从离双键最近端开始。'},
    {id:'k673',module:'选择性必修3·有机化学',q:'产生顺反异构的条件不包括？',options:['双键可自由旋转','双键每个碳原子连接不同原子或原子团','分子具有碳碳双键','双键不能旋转'],answer:0,explain:'顺反异构源于双键不能旋转 + 每个双键碳连不同基团；双键不能自由旋转是条件之一，"可自由旋转"错误。'},
    {id:'k674',module:'选择性必修3·有机化学',q:'顺式结构是指两个相同原子或原子团？',options:['排列在双键两侧','不相连','位于同一碳上','排列在双键同一侧'],answer:3,explain:'顺式=相同基团在双键同侧；反式=在两侧。'},
    {id:'k675',module:'选择性必修3·有机化学',q:'乙炔分子中碳原子的杂化方式及空间构型是？',options:['sp3，正四面体','sp2，平面','不杂化，V 形','sp，直线形'],answer:3,explain:'乙炔 C 为 sp 杂化，键角 180°，4 原子共线，直线形分子。'},
    {id:'k676',module:'选择性必修3·有机化学',q:'乙炔燃烧火焰温度可达 3000℃ 以上，常用于？',options:['制塑料','消毒','催熟果实','切割或焊接金属'],answer:3,explain:'氧炔焰温度高，常用于金属切割与焊接。'},
    {id:'k677',module:'选择性必修3·有机化学',q:'乙炔与溴的四氯化碳溶液反应，最终可生成？',options:['仅 1,2-二溴乙烯','不反应','CHBr=CHBr（1,2-二溴乙烯）','CHBr2—CHBr2（1,1,2,2-四溴乙烷）'],answer:3,explain:'乙炔先与 1 mol Br2 成 1,2-二溴乙烯，再与第 2 mol Br2 加成得 1,1,2,2-四溴乙烷。'},
    {id:'k678',module:'选择性必修3·有机化学',q:'乙炔能使下列哪种溶液褪色？',options:['酸性 KMnO4','两者均可','两者均不可','溴水'],answer:1,explain:'乙炔含 C≡C，能与 Br2 加成、被酸性 KMnO4 氧化，均褪色。'},
    {id:'k679',module:'选择性必修3·有机化学',q:'炔烃的官能团及通式（单炔烃）是？',options:['碳碳三键，CnH2n+2','苯环，CnH2n-6','碳碳双键，CnH2n','碳碳三键，CnH2n-2'],answer:3,explain:'炔烃含 C≡C，单炔烃通式 CnH2n-2，化学性质与乙炔相似。'},
    {id:'k680',module:'选择性必修3·有机化学',q:'丙炔燃烧的化学方程式（配平）是？',options:['C3H4 + 4O2 → 3CO2 + 2H2O','2C3H4 + 5O2 → 6CO2 + 4H2O  （注：丙炔 C3H4）','2C3H4 + 6O2 → 6CO2 + 4H2O','2C3H4 + 4O2 → 6CO2 + 2H2O'],answer:1,explain:'2CH3C≡CH + 4O2 → 6CO2 + 2H2O（丙炔分子式 C3H4），A 配平正确。'},
    {id:'k682',module:'选择性必修3·有机化学',q:'苯分子中碳碳键的特点是？',options:['6 个碳碳单键','3 个双键、3 个单键交替','6 个键长完全相等，介于单双键之间的特殊键，含大 π 键','全为双键'],answer:2,explain:'苯 6 个 C 均 sp2 杂化形成 σ 骨架，p 轨道重叠成离域大 π 键，6 个键长相等（139 pm）。'},
    {id:'k683',module:'选择性必修3·有机化学',q:'苯与溴在 FeBr3 催化下发生的反应类型是？',options:['加成反应','取代反应（生成溴苯）','消去反应','氧化反应'],answer:1,explain:'苯环上 H 被 Br 取代生成溴苯，属取代反应，FeBr3 作催化剂。'},
    {id:'k684',module:'选择性必修3·有机化学',q:'下列关于苯化学性质的描述，正确的是？',options:['不能使酸性 KMnO4 褪色，较为稳定','能使酸性 KMnO4 褪色','不能与浓硝酸反应','不能与 H2 加成'],answer:0,explain:'苯较稳定，不能被酸性 KMnO4 氧化（不褪色），可在催化剂、加热下与 H2 加成、与混酸硝化。'},
    {id:'k685',module:'选择性必修3·有机化学',q:'苯的空间构型是？',options:['平面正六边形，12 个原子共面','直线形','正四面体','三角锥形'],answer:0,explain:'苯为平面正六边形，6 C + 6 H 共 12 个原子同平面，对位 4 原子共线。'},
    {id:'k686',module:'选择性必修3·有机化学',q:'苯的同系物通式（n≥7）为？',options:['CnH2n-2','CnH2n+2','CnH2n','CnH2n-6'],answer:3,explain:'苯同系物为一个苯环 + 烷基侧链，通式 CnH2n-6（n≥7，如甲苯 C7H8）。'},
    {id:'k687',module:'选择性必修3·有机化学',q:'苯的同系物能使酸性 KMnO4 褪色，原因是？',options:['苯环对侧链的影响，使侧链（与苯环直接相连的碳上有 H）被氧化为羧基','烷基被取代','苯环被氧化','发生加成'],answer:0,explain:'苯环影响侧链，与苯环直接相连的碳上有 H 时，侧链被 KMnO4 氧化为 —COOH（紫褪）。'},
    {id:'k688',module:'选择性必修3·有机化学',q:'甲苯与 Cl2 反应时，光照条件与 Fe 催化条件的主要区别是？',options:['两者均只在侧链','两者均只在苯环','光照发生在苯环上取代，催化发生在侧链','光照发生在侧链取代，催化发生在苯环上取代'],answer:3,explain:'光照下 Cl2 取代侧链 H；Fe 催化下取代苯环上 H（苯环上取代）。'},
    {id:'k689',module:'选择性必修3·有机化学',q:'甲苯硝化的产物（三硝基取代）中，硝基主要位于甲基的？',options:['任意位置','邻、对位','仅邻位','间位'],answer:1,explain:'甲基为邻对位定位基，甲苯硝化硝基主要在甲基邻、对位。'},
    {id:'k690',module:'选择性必修3·有机化学',q:'有机物分子中出现一个饱和碳原子时，结论是？',options:['所有原子可能共面','分子中所有原子不可能共面','至少 4 原子共线','至少 6 原子共面'],answer:1,explain:'饱和 C 连 4 个原子成四面体，分子中所有原子不可能共面（甲烷型）。'},
    {id:'k691',module:'选择性必修3·有机化学',q:'每出现一个碳碳双键，分子中至少有多少个原子共面？',options:['3','12','6','4'],answer:2,explain:'乙烯型，C=C 不能旋转，6 个原子（双键碳及所连 4 原子）共面。'},
    {id:'k692',module:'选择性必修3·有机化学',q:'每出现一个苯环，分子中至少有多少个原子共面？',options:['4','12','6','3'],answer:1,explain:'苯型 12 个原子共平面，对位 4 原子共线。'},
    {id:'k693',module:'选择性必修3·有机化学',q:'碳碳三键使分子中至少有多少个原子共线？',options:['4','6','3','12'],answer:0,explain:'乙炔型 4 个原子（C≡C 及所连 2 原子）共线。'},
    {id:'k694',module:'选择性必修3·有机化学',q:'石油分馏的原理是？',options:['利用烃的沸点不同，逐步升温气化再冷凝分离','利用烃的密度不同','利用烃的溶解度不同','利用烃的颜色不同'],answer:0,explain:'分馏利用各烃沸点不同，升温使不同馏分先后气化冷凝，馏分为混合物。'},
    {id:'k695',module:'选择性必修3·有机化学',q:'石油裂化的主要目的是？',options:['制备焦炭','获得乙烯等短链气态烃','获得芳香烃','提高轻质油（尤其汽油）产量'],answer:3,explain:'裂化将大分子断为小分子，提高汽油等轻质油产量；裂解才主要获乙烯丙烯。'},
    {id:'k696',module:'选择性必修3·有机化学',q:'石油裂解的主要目的是？',options:['获乙烯、丙烯等短链不饱和气态烃','获汽油','获沥青','获润滑油'],answer:0,explain:'裂解即深度裂化，主获乙烯、丙烯等短链气态不饱和烃。'},
    {id:'k697',module:'选择性必修3·有机化学',q:'催化重整的作用是？',options:['制备焦炭','链状烃转化为环状烃，获得芳香烃','提高汽油产量','脱硫'],answer:1,explain:'催化重整使链状烃结构调整转化为环状烃，获苯、甲苯等芳烃。'},
    {id:'k698',module:'选择性必修3·有机化学',q:'煤的干馏是指？',options:['通氧气燃烧','加氢液化','隔绝空气加强热使有机物分解','与水混合'],answer:2,explain:'煤干馏=隔绝空气加强热分解（焦化），得焦炭、煤焦油、焦炉气、粗氨水等。'},
    {id:'k699',module:'选择性必修3·有机化学',q:'煤的气化主要反应是？',options:['C + O2 → CO2','C + 2H2 → CH4','CO + H2 → CH3OH','C + H2O(g) → CO + H2'],answer:3,explain:'煤的气化将煤转可燃性气体，主反应 C(s)+H2O(g)=CO+H2（水煤气）。'},
    {id:'k700',module:'选择性必修3·有机化学',q:'煤的间接液化是先气化为合成气，再在催化剂作用下合成？',options:['焦炭','甲醇等','苯','甲烷'],answer:1,explain:'间接液化经合成气（CO、H2）在催化剂下合成甲醇等液体燃料。'},
    {id:'k702',module:'选择性必修3·有机化学',q:'酚的定义是？',options:['羟基连在脂肪烃基上','羟基连在侧链碳上','羟基与苯环碳原子直接相连','含两个羟基'],answer:2,explain:'酚=羟基直接与苯环碳相连（如苯酚 C6H5OH）；羟基连侧链碳为醇（如苯甲醇）。'},
    {id:'k703',module:'选择性必修3·有机化学',q:'纯净苯酚的颜色及在空气中变化是？',options:['无色晶体，易被空气氧化呈粉红色','黄色液体','红色晶体','无色，不变化'],answer:0,explain:'纯净苯酚为无色晶体，酚羟基易被氧化，露置空气变粉红，需密封保存。'},
    {id:'k704',module:'选择性必修3·有机化学',q:'苯酚与 FeCl3 溶液显色反应的现象是？',options:['蓝色','黄色','白色沉淀','显紫色'],answer:3,explain:'苯酚遇 FeCl3 溶液显紫色，是酚的显色反应（可检验酚羟基）。'},
    {id:'k705',module:'选择性必修3·有机化学',q:'常温下苯酚在水中的溶解度特点是？',options:['不溶于水也不溶于有机溶剂','易溶于水','任意比例溶于水','溶解度较小（约 9.3 g），65℃ 以上可与水混溶'],answer:3,explain:'常温苯酚水中溶解度小（S≈9.3g）呈浊液；>65℃ 可与水混溶，易溶于乙醇等有机溶剂。'},
    {id:'k706',module:'选择性必修3·有机化学',q:'醛的官能团及饱和一元醛通式是？',options:['—COOH，CnH2nO2','—OH，CnH2n+1OH','—CO—，CnH2nO','—CHO（醛基），CnH2nO'],answer:3,explain:'醛由烃基/氢与醛基（—CHO）相连，饱和一元醛通式 CnH2nO。'},
    {id:'k707',module:'选择性必修3·有机化学',q:'乙醛能被下列哪种弱氧化剂氧化（产生特征现象）？',options:['稀硫酸','乙醇','新制 Cu(OH)2（蓝色→砖红色）和银氨溶液（银镜）','食盐水'],answer:2,explain:'醛基有还原性，能被新制 Cu(OH)2 氧化（砖红 Cu2O）、与银氨溶液发生银镜反应。'},
    {id:'k708',module:'选择性必修3·有机化学',q:'乙醛催化加氢（还原）的生成物是？',options:['乙醇','乙酸','乙烯','乙醚'],answer:0,explain:'CH3CHO + H2 →(Ni,△) CH3CH2OH（乙醇），加氢还原为醇。'},
    {id:'k709',module:'选择性必修3·有机化学',q:'关于酮（如丙酮）的性质，正确的是？',options:['不能被银氨溶液、新制 Cu(OH)2 等弱氧化剂氧化，但能催化加氢成醇','能使 KMnO4 褪色','能被银氨溶液、新制 Cu(OH)2 氧化','不能发生任何反应'],answer:0,explain:'酮羰基无醛基的 H，不被银氨/新制 Cu(OH)2 氧化，但可催化加氢生成醇。'},
    {id:'k710',module:'选择性必修3·有机化学',q:'酯的结构通式及乙酸乙酯的官能团是？',options:['R—OH；羟基','R—CHO；醛基','RCOOR′；酯基（—COO—）','R—COOH；羧基'],answer:2,explain:'酯为羧酸羧基 —OH 被 —OR′ 取代，官能团酯基 —COO—。'},
    {id:'k711',module:'选择性必修3·有机化学',q:'酯在酸性条件下水解的特点是？',options:['可逆反应（如稀硫酸催化）','只生成羧酸','不可逆','不水解'],answer:0,explain:'酸性水解可逆，生成羧酸+醇；碱性水解不可逆生成羧酸盐+醇。'},
    {id:'k712',module:'选择性必修3·有机化学',q:'酯在碱性条件下水解（如 NaOH 溶液）的产物是？',options:['羧酸 + 醇','羧酸盐 + 醇','酮 + 醇','醛 + 醇'],answer:1,explain:'碱性水解不可逆，生成的酸与碱成盐，得羧酸盐+醇。'},
    {id:'k713',module:'选择性必修3·有机化学',q:'油脂的化学本质是？',options:['蛋白质','糖类','高级脂肪酸与甘油形成的酯（甘油三酯）','烃类'],answer:2,explain:'油脂=一分子甘油与三分子高级脂肪酸脱水形成的甘油三酯，属酯类。'},
    {id:'k714',module:'选择性必修3·有机化学',q:'常温下呈液态、含较多不饱和脂肪酸甘油酯的称为？',options:['磷脂','脂肪（如牛油）','蜡','油（如花生油、大豆油）'],answer:3,explain:'油=液态、含较多不饱和酸（花生油等）；脂肪=固态、含较多饱和酸（牛油等）。'},
    {id:'k715',module:'选择性必修3·有机化学',q:'按 R1、R2、R3 是否相同，油脂可分为？',options:['油和脂肪','单甘油酯（相同）和混合甘油酯（不同）','天然与合成','饱和与不饱和'],answer:1,explain:'R1=R2=R3 为简单（单）甘油酯；不完全相同为混合甘油酯。'},
    {id:'k716',module:'选择性必修3·有机化学',q:'油脂在碱性条件下的水解反应称为？',options:['裂解','皂化反应（制肥皂和甘油）','氢化反应','酯化反应'],answer:1,explain:'油脂碱性水解（皂化）生成高级脂肪酸盐（肥皂）和甘油。'},
    {id:'k717',module:'选择性必修3·有机化学',q:'油脂兼有烯烃性质的原因是？',options:['含苯环','含羟基','高级脂肪酸中含不饱和键，可发生加成','含醛基'],answer:2,explain:'许多油脂含不饱和脂肪酸甘油酯，含 C=C 可发生加成（如氢化制硬化油）。'},
    {id:'k718',module:'选择性必修3·有机化学',q:'酰胺（RCONH2）在碱性条件下水解产物是？',options:['ROH + NH3','RCOONa + NH3↑','RCOOH + NH3','RCHO + NH3'],answer:1,explain:'RCONH2 + NaOH → RCOONa + NH3↑（碱性水解，逸出氨气）。'},
    {id:'k719',module:'选择性必修3·有机化学',q:'关于酰胺，错误的是？',options:['可在酸或碱中加热水解','常用作溶剂（如 DMF）','不能发生水解','由羧酸分子羟基被氨基取代得到'],answer:2,explain:'酰胺可在酸/碱中加热水解（C 错），如 DMF 是良好溶剂。'},
    {id:'k720',module:'选择性必修3·有机化学',q:'有机合成的主要任务包括？',options:['仅增加碳原子数','构建碳骨架和引入官能团','仅去除官能团','只做取代反应'],answer:1,explain:'有机合成利用反应构建碳骨架、引入/转化官能团，得目标分子。'},
    {id:'k721',module:'选择性必修3·有机化学',q:'有机合成原则不包括？',options:['原料廉价易得、低毒低污染','步骤尽量少、副反应少、产率高','尽量臆造不存在的反应以简化路线','符合绿色化学、条件温和'],answer:2,explain:'合成须按真实反应规律，不能臆造不存在的反应；A/B/C 均为原则。'},
    {id:'k722',module:'选择性必修3·有机化学',q:'引入官能团时应注意？',options:['顺序任意，无需保护','一次完成','按反应顺序规律引入，注意先后顺序及对先引入官能团的保护','只引入一个官能团'],answer:2,explain:'多步合成需按顺序引入官能团，必要时保护先引入的基团（如氧化敏感基团先保护）。'},
    {id:'k723',module:'选择性必修3·有机化学',q:'糖类的组成与俗称，正确的是？',options:['糖都不含氧','多数糖分子中 H:O=2:1，可用通式 Cm(H2O)n 表示，称碳水化合物','糖只含 C','糖类只含 C、H，称碳水化合物'],answer:1,explain:'糖类一般 C、H、O，且 H:O=2:1，组成常写作 Cm(H2O)n，故又称碳水化合物（并非真含水分子）。'},
    {id:'k724',module:'选择性必修3·有机化学',q:'不能水解的糖称为？',options:['二糖','单糖（如葡萄糖、果糖）','寡糖','多糖'],answer:1,explain:'单糖不能水解；二糖水解 2 单糖，多糖水解≥10 单糖。'},
    {id:'k725',module:'选择性必修3·有机化学',q:'葡萄糖属于？',options:['酮糖','多糖','醛糖（含醛基和五个羟基）','二糖'],answer:2,explain:'葡萄糖含一个醛基、五个羟基，属醛糖（还原性糖），可被银氨/新制 Cu(OH)2 氧化。'},
    {id:'k726',module:'选择性必修3·有机化学',q:'葡萄糖与果糖的关系是？',options:['同分异构体（分子式均为 C6H12O6）','同系物','同种物质','同素异形体'],answer:0,explain:'葡萄糖（醛糖）与果糖（酮糖）分子式均为 C6H12O6、结构不同，互为同分异构体。'},
    {id:'k727',module:'选择性必修3·有机化学',q:'核糖与脱氧核糖属于？',options:['六碳糖（己糖）','二糖','五碳糖（戊糖），均为醛糖，具还原性','多糖'],answer:2,explain:'二者均为含 5 个碳的单糖（戊糖），是 RNA/DNA 组分，均为醛糖、有还原性。'},
    {id:'k728',module:'选择性必修3·有机化学',q:'手性碳原子是指？',options:['双键碳','连有 4 个不同原子或原子团的碳（不对称碳）','苯环上的碳','连有 4 个相同原子或原子团的碳'],answer:1,explain:'手性碳=连 4 个不同原子/基团的碳，使分子有对映异构体（手性分子）。'},
    {id:'k729',module:'选择性必修3·有机化学',q:'天然氨基酸主要属于？',options:['芳香氨基酸','α-氨基酸（氨基连在 α-碳上）','β-氨基酸','γ-氨基酸'],answer:1,explain:'天然蛋白质氨基酸多为 α-氨基酸（—NH2 与 —COOH 连在同一碳上），除甘氨酸外多为手性分子。'},
    {id:'k730',module:'选择性必修3·有机化学',q:'氨基酸分子中含有的酸、碱基团使其为？',options:['仅碱性','中性','两性化合物（能与酸、碱成盐）','仅酸性'],answer:2,explain:'氨基酸含 —COOH（酸）和 —NH2（碱），是两性化合物，与酸、碱均成盐。'},
    {id:'k731',module:'选择性必修3·有机化学',q:'蛋白质的盐析与变性，下列描述正确的是？',options:['盐析可逆（物理变化），变性不可逆（化学变化）','两者均不可逆','盐析不可逆','两者均可逆'],answer:0,explain:'盐析（浓轻金属盐/铵盐）是溶解度降低、可逆物理变化；变性（加热、强酸强碱、重金属盐等）结构改变、不可逆。'},
    {id:'k732',module:'选择性必修3·有机化学',q:'可用浓硝酸鉴别含苯环蛋白质，现象是？',options:['无变化','变红','白色沉淀，加热变黄','变蓝'],answer:2,explain:'含苯环蛋白质遇浓硝酸产生白色沉淀、加热变黄（显色反应，黄蛋白反应）。'},
    {id:'k733',module:'选择性必修3·有机化学',q:'鉴别毛料（蛋白质）与合成纤维可用？',options:['灼烧闻烧焦羽毛气味','溶于水','测密度','看颜色'],answer:0,explain:'蛋白质灼烧有烧焦羽毛气味，可鉴别毛料与合成纤维。'},
    {id:'k734',module:'选择性必修3·有机化学',q:'蛋白质水解的最终产物是？',options:['氨基酸','葡萄糖','脂肪酸','甘油'],answer:0,explain:'蛋白质在酸/碱/酶作用下逐步水解，最终得氨基酸。'},
  ],
  experiment: [
    {id:'e1',module:'必修一',q:'关于钠与水反应的现象，下列说法错误的是？',options:['钠浮在水面上','熔化成闪亮小球','在水面上四处游动','反应后产生白色沉淀'],answer:3,explain:'钠与水反应生成 NaOH 和 H₂，现象为浮、熔、游、响，溶液呈碱性（加酚酞变红），不产生白色沉淀。'},
    {id:'e2',module:'必修一',q:'铝热反应（如铝粉与氧化铁）常用于？',options:['焊接铁轨','制取氧气','净水','漂白'],answer:0,explain:'铝热反应放出大量热，可使生成的铁熔化，用于焊接铁轨（铝热焊）。'},
    {id:'e3',module:'必修一',q:'焰色试验中，钠元素火焰呈什么颜色？',options:['黄色','紫色（透过蓝色钴玻璃）','砖红色','绿色'],answer:0,explain:'钠的焰色为黄色；钾为紫色（需透过蓝色钴玻璃滤去钠的黄光）。'},
    {id:'e4',module:'选择性必修1',q:'用已知浓度的 NaOH 溶液滴定未知浓度盐酸，通常选用的指示剂是？',options:['酚酞','石蕊','无需指示剂','淀粉'],answer:0,explain:'强酸强碱滴定常用酚酞或甲基橙；酚酞终点由无色变为粉红色，便于观察。'},
    {id:'e5',module:'必修一',q:'实验室制取 NH₃ 常用的反应物是？',options:['氯化铵与氢氧化钙共热','加热硝酸铵','电解水','燃烧氢气'],answer:0,explain:'2NH₄Cl+Ca(OH)₂=CaCl₂+2NH₃↑+2H₂O，是实验室制氨气的标准方法。'},
    {id:'e6',module:'选择性必修1',q:'MnO₂ 与浓盐酸共热制取 Cl₂，浓盐酸在反应中表现的性质是？',options:['仅酸性','仅还原性','酸性和还原性','氧化性'],answer:2,explain:'浓盐酸提供 H⁺（表现酸性）和 Cl⁻（被氧化为 Cl₂，表现还原性）。'},
    {id:'e7',module:'必修一',q:'制取 Fe(OH)₂ 时，白色沉淀迅速变成灰绿色，最后变成红褐色，原因是？',options:['被空气中的 O₂ 氧化','被还原','受热分解','水解'],answer:0,explain:'Fe(OH)₂ 极易被空气中氧气氧化：4Fe(OH)₂+O₂+2H₂O=4Fe(OH)₃。'},
    {id:'e8',module:'必修一',q:'向蔗糖中滴加浓硫酸，蔗糖变黑并膨胀，主要体现浓硫酸的？',options:['吸水性','脱水性','强氧化性','酸性'],answer:1,explain:'浓硫酸按水的组成比脱去蔗糖中的 H、O 使其炭化变黑，体现脱水性。'},
    {id:'e9',module:'必修一',q:'用 CCl₄ 从溴水中萃取溴，分层后的现象是？',options:['上层呈橙红色','下层呈橙红色','不分层','溶液变无色'],answer:1,explain:'CCl₄ 密度比水大，溴在 CCl₄ 中溶解度大，故下层（CCl₄ 层）呈橙红色。'},
    {id:'e10',module:'必修一',q:'实验中少量浓硫酸溅到皮肤上，正确的处理是？',options:['立即用 NaOH 中和','直接用大量水冲洗即可','先用干布拭去，再用大量水冲洗，最后涂碳酸氢钠','涂上碳酸氢钠粉末'],answer:2,explain:'浓硫酸遇水放热，应先迅速用干布拭去，再用大量水冲洗，最后用 3%~5% NaHCO₃ 溶液处理。'},
    {id:'e11',module:'选择性必修2',q:'向 CuSO₄ 溶液中逐滴加入过量氨水，观察到的现象是？',options:['立即生成黑色沉淀','先产生蓝色沉淀，后沉淀溶解得到深蓝色溶液','无明显变化','产生白色沉淀'],answer:1,explain:'Cu²⁺ 先与氨水生成蓝色 Cu(OH)₂ 沉淀；过量氨水时形成 [Cu(NH₃)₄]²⁺ 深蓝色配离子，使沉淀溶解。'},
    {id:'e12',module:'选择性必修2',q:'下列事实能说明某固体属于分子晶体的是？',options:['熔点很高','熔融态不导电且熔点较低/易升华','硬度极大','固态能导电'],answer:1,explain:'分子晶体靠分子间作用力结合，熔点低、熔融态不导电；原子晶体/离子晶体熔点高，金属晶体可导电。'},
    {id:'e13',module:'必修一',q:'配制一定物质的量浓度的溶液，定容时俯视刻度线，所配溶液浓度将？',options:['偏高','偏低','无影响','无法判断'],answer:0,explain:'俯视使读数偏大，实际加水量偏少，溶液体积偏小，故浓度偏高。'},
    {id:'e14',module:'必修一',q:'除去 CO₂ 中混有的少量 HCl 气体，应选用的试剂是？',options:['NaOH 溶液','饱和 NaHCO₃ 溶液','水','澄清石灰水'],answer:1,explain:'饱和 NaHCO₃ 与 HCl 反应生成 CO₂，且不吸收 CO₂；NaOH、澄清石灰水都会吸收 CO₂。'},
    {id:'e15',module:'必修一',q:'关于容量瓶的构造，下列说法正确的是？',options:['细颈、梨形、平底玻璃瓶，瓶口配有磨口塞或塑料塞','粗颈、广口、圆底玻璃瓶','与普通烧杯形状相同，只是带刻度','没有瓶塞，靠橡胶塞封口'],answer:0,explain:'容量瓶为细颈、梨形、平底玻璃瓶，瓶口配有磨口塞或塑料塞，用于精确配制一定体积的溶液。'},
    {id:'e16',module:'必修一',q:'配制 100 mL 1.00 mol/L NaCl 溶液，理论上需 NaCl 5.85 g，用托盘天平实际应称取？',options:['5.85 g','5.9 g','5.8 g','6.0 g'],answer:1,explain:'托盘天平读数精确到 0.1 g，5.85 g 应四舍五入称取 5.9 g。'},
    {id:'e17',module:'必修一',q:'将烧杯中溶液注入容量瓶前，为什么要待溶液恢复室温？',options:['防止热溶液使容量瓶体积不准确（热胀冷缩）','加快固体溶解','防止液体暴沸','便于洗涤烧杯'],answer:0,explain:'热溶液体积偏大，若趁热定容，冷却后体积缩小，导致所配浓度偏高；且容量瓶不能受热，故须恢复室温后再转移。'},
    {id:'e18',module:'必修一',q:'转移后洗涤烧杯内壁和玻璃棒 2~3 次，并将洗涤液注入容量瓶，目的是？',options:['保证溶质全部转移到容量瓶','清洗实验仪器','稀释所配溶液','加快溶解'],answer:0,explain:'烧杯壁和玻璃棒上残留溶质，洗涤并将洗涤液并入容量瓶可保证溶质全部转移，避免浓度偏低。'},
    {id:'e19',module:'必修一',q:'定容时，当液面接近刻度线应如何操作？',options:['直接倾倒蒸馏水至刻度线','液面距刻度线 1~2 cm 处，改用胶头滴管滴加至凹液面最低处与刻度线相切','用玻璃棒引流加水','先摇匀再定容'],answer:1,explain:'定容时先加水至距刻线 1~2 cm，再改用胶头滴管逐滴加至凹液面最低处恰好与刻度线相切。'},
    {id:'e20',module:'必修一',q:'用固体 NaCl 配制 100 mL 1.00 mol/L 溶液，下列仪器中不需要的是？',options:['量筒','100 mL 容量瓶','玻璃棒','胶头滴管'],answer:0,explain:'用固体溶质配制时，仪器为托盘天平、药匙、烧杯、玻璃棒、容量瓶、胶头滴管、试剂瓶，不需要量筒（量筒用于量取浓溶液）。'},
    {id:'e21',module:'必修一',q:'下列关于容量瓶使用的说法，正确的是？',options:['可直接在容量瓶中溶解固体或稀释浓溶液','可长期在容量瓶中贮存溶液','不能配制任意体积的溶液','可加入过热或过冷的液体'],answer:2,explain:'容量瓶"四不能"：不能在瓶中直接溶解/稀释、不能加入过冷过热液体、不能作为反应容器或长期贮存、不能配制任意体积的溶液。故 C 正确。'},
    {id:'e22',module:'必修一',q:'配制 950 mL 1 mol/L NaCl 溶液，应选用容量瓶规格及计算依据是？',options:['950 mL 容量瓶，按 0.95 L 计算','1000 mL 容量瓶，按 1 L 计算','500 mL 容量瓶，分两次配制','任意规格均可'],answer:1,explain:'按"大而近"原则，无 950 mL 规格应选 1000 mL 容量瓶，计算溶质用量时按 1 L 计。'},
    {id:'e23',module:'必修一',q:'定容时仰视容量瓶刻度线，所配溶液浓度将？',options:['偏高','偏低','无影响','无法判断'],answer:1,explain:'仰视使读数偏小，实际加水量偏多，溶液体积偏大，故浓度偏低。'},
    {id:'e24',module:'必修一',q:'溶液未冷却至室温就转入容量瓶并定容，所配溶液浓度将？',options:['偏高','偏低','无影响','取决于溶质种类'],answer:0,explain:'热溶液体积偏大，冷却后体积缩小，定容时加水量相对偏少，浓度偏高。'},
    {id:'e25',module:'必修一',q:'容量瓶中有少量蒸馏水（定容前未倒出），对所配溶液浓度的影响是？',options:['偏高','偏低','无影响','无法判断'],answer:2,explain:'定容时仍要加水至刻度，瓶内原有少量水不改变最终溶质的量和溶液体积，故无影响。'},
    {id:'e26',module:'必修一',q:'转移后未洗涤烧杯和玻璃棒，所配溶液浓度将？',options:['偏高','偏低','无影响','无法判断'],answer:1,explain:'部分溶质残留在烧杯和玻璃棒上未转移，溶质偏少，浓度偏低。'},
    {id:'e27',module:'必修一',q:'定容摇匀后液面低于刻度线，又加水至刻度，所配溶液浓度将？',options:['偏高','偏低','无影响','无法判断'],answer:1,explain:'摇匀后液面下降是因为部分溶液留在瓶塞与瓶颈处，属正常；再加水会使体积偏大，浓度偏低。'},
    {id:'e28',module:'必修一',q:'用 MnO₂ 与浓盐酸加热制取 Cl₂，该反应中的氧化剂是？',options:['MnO₂','HCl','Cl₂','H₂O'],answer:0,explain:'MnO₂ + 4HCl(浓) → MnCl₂ + Cl₂↑ + 2H₂O，Mn 元素化合价由 +4 降至 +2，MnO₂ 作氧化剂。'},
    {id:'e29',module:'必修一',q:'用 MnO₂ 固体与浓盐酸在加热条件下制 Cl₂，气体发生装置属于？',options:['固 + 固加热','固 + 液加热','液 + 液加热','固 + 液不加热'],answer:1,explain:'反应物为固体（MnO₂）与液体（浓盐酸）且需加热，属"固 + 液加热"制气装置。'},
    {id:'e30',module:'必修一',q:'除去 Cl₂ 中混有的少量 HCl 气体，应选用的试剂是？',options:['饱和食盐水','浓硫酸','NaOH 溶液','水'],answer:0,explain:'Cl₂ 在饱和食盐水中溶解度小，而 HCl 极易溶于水，故用饱和食盐水除去 HCl；浓硫酸用于除水蒸气。'},
    {id:'e31',module:'必修一',q:'实验室收集 Cl₂，可采用的方法是？',options:['排水法','向下排空气法','向上排空气法或排饱和食盐水法','排 NaOH 溶液法'],answer:2,explain:'Cl₂ 密度比空气大且能溶于水，可用向上排空气法；又因在饱和食盐水中溶解度小，也可用排饱和食盐水法收集。'},
    {id:'e32',module:'必修一',q:'吸收 Cl₂ 尾气通常用 NaOH 溶液而不用 Ca(OH)₂ 溶液，原因是？',options:['Ca(OH)₂ 溶解度小、溶液浓度低，吸收不完全','Ca(OH)₂ 不与 Cl₂ 反应','NaOH 成本更低','Ca(OH)₂ 会与 Cl₂ 爆炸'],answer:0,explain:'Ca(OH)₂ 微溶，饱和溶液浓度很低，吸收 Cl₂ 不完全，故尾气用 NaOH 溶液吸收。'},
    {id:'e33',module:'必修一',q:'检验 Cl₂ 是否集满，可用湿润的淀粉-KI 试纸靠近瓶口，现象是？',options:['试纸变蓝','试纸变红','试纸褪色','无明显变化'],answer:0,explain:'Cl₂ 氧化 I⁻ 生成 I₂，I₂ 遇淀粉显蓝色，故试纸变蓝表示已集满。'},
    {id:'e34',module:'必修一',q:'用湿润的蓝色石蕊试纸检验 Cl₂ 是否集满，现象是？',options:['试纸立即褪色','试纸先变红后褪色','试纸变蓝','试纸不变色'],answer:1,explain:'Cl₂ 与水生成盐酸（使石蕊变红）和次氯酸（强氧化性使红色褪去），故先变红后褪色表示已集满。'},
  {id:'e35',module:'必修二',q:'检验混合气体中是否同时含有 CO₂ 和 SO₂，合理的装置连接顺序是？',options:['澄清石灰水 → 品红 → KMnO₄ → 品红','KMnO₄ → 品红 → 石灰水 → 品红','品红 → 石灰水 → KMnO₄ → 品红','品红 → KMnO₄(酸) → 品红 → 澄清石灰水'],answer:3,explain:'先用品红检验 SO₂，再用酸性 KMnO₄ 除去 SO₂，再用品红确认 SO₂ 除尽，最后用石灰水检验 CO₂（避免 SO₂ 干扰）。'},
  {id:'e36',module:'必修二',q:'上述装置中，酸性 KMnO₄ 溶液的作用是？',options:['检验 SO₂','检验 SO₂ 是否除尽','除去 SO₂','检验 CO₂'],answer:2,explain:'酸性 KMnO₄ 将 SO₂ 氧化除去，防止其使石灰水变浑浊而干扰 CO₂ 的检验。'},
  {id:'e37',module:'必修二',q:'为什么要设置第二个品红溶液？',options:['检验 SO₂','检验 SO₂ 是否除尽','除去 SO₂','吸收 CO₂'],answer:1,explain:'确认 SO₂ 已被 KMnO₄ 完全除去，避免残留 SO₂ 进入石灰水造成误判。'},
  {id:'e38',module:'必修二',q:'SO₂ 和 CO₂ 都能使澄清石灰水变浑浊，因此检验 CO₂ 前必须？',options:['先除去 SO₂','先干燥','先点燃','先加热'],answer:0,explain:'两者均使石灰水变浑浊，须先除尽 SO₂ 才能用石灰水检验 CO₂。'},
  {id:'e39',module:'必修二',q:'下列气体中，不能用浓硫酸干燥的是？',options:['O₂','CO₂','Cl₂','NH₃'],answer:3,explain:'浓硫酸不能干燥碱性气体（如 NH₃）和除 SO₂ 外的还原性气体（如 H₂S、HI）；NH₃ 会被酸吸收。'},
  {id:'e40',module:'必修二',q:'向蔗糖中滴入浓硫酸，蔗糖变黑、体积膨胀呈疏松多孔的炭，主要体现浓硫酸的？',options:['吸水性','强氧化性','酸性','脱水性'],answer:3,explain:'脱水性将蔗糖中 H、O 按 2:1 脱去生成炭（变黑、膨胀）；强氧化性在后续将 C 氧化为 CO₂ 并放出 SO₂，但“变黑”主因是脱水性。'},
  {id:'e41',module:'必修二',q:'铜与浓硫酸共热：Cu + 2H₂SO₄(浓) = CuSO₄ + SO₂↑ + 2H₂O，浓硫酸的作用是？',options:['只作氧化剂','只作酸','氧化性和酸性','还原性和酸性'],answer:2,explain:'生成 SO₂ 体现氧化性，生成 CuSO₄ 体现酸性。'},
  {id:'e42',module:'必修二',q:'下列气体能用浓硫酸干燥的是？',options:['HCl','H₂S','NH₃','HI'],answer:0,explain:'HCl 是酸性且非还原性气体，可被浓硫酸干燥；H₂S、HI 有还原性会被氧化，NH₃ 为碱性。'},
  {id:'e43',module:'必修二',q:'实验室制取 H₂S 的原料通常是？',options:['Na₂S 与浓 H₂SO₄','FeS 与稀 H₂SO₄ 或稀 HCl','Fe 与 HCl','CuS 与 HCl'],answer:1,explain:'FeS + 2HCl = FeCl₂ + H₂S↑ 或 FeS + H₂SO₄ = FeSO₄ + H₂S↑。'},
  {id:'e44',module:'必修二',q:'收集 H₂S 气体应采用？',options:['排水法','向下排空气法','排饱和食盐水','向上排空气法'],answer:3,explain:'H₂S 密度比空气大且能溶于水，用向上排空气法收集。'},
  {id:'e45',module:'必修二',q:'检验 H₂S 气体常用的试纸是？',options:['湿润的醋酸铅试纸（变黑）','湿润的品红试纸','澄清石灰水','淀粉-KI 试纸'],answer:0,explain:'H₂S 与 Pb(Ac)₂ 生成黑色 PbS，使醋酸铅试纸变黑，是特征检验。'},
  {id:'e46',module:'必修二',q:'常温下硅的化学性质不活泼，只与下列哪些物质反应？',options:['O₂、Cl₂','H₂O','F₂、HF、强碱（如 NaOH）','所有酸'],answer:2,explain:'常温下 Si 仅与 F₂、HF、强碱反应。'},
  {id:'e47',module:'必修二',q:'硅与 NaOH 溶液：Si + 2NaOH + H₂O = Na₂SiO₃ + 2H₂↑，H₂O 的作用是？',options:['还原剂','催化剂','溶剂','氧化剂'],answer:3,explain:'H₂O 中 H 由 +1 降到 0 生成 H₂，作氧化剂。'},
  {id:'e48',module:'必修二',q:'硅与氢氟酸：Si + 4HF = SiF₄↑ + 2H₂↑，该反应中 HF 用于？',options:['制冷剂','刻蚀玻璃的反应物之一','干燥剂','燃料'],answer:1,explain:'刻蚀玻璃的反应是 SiO₂ + 4HF = SiF₄↑ + 2H₂O，HF 是关键试剂。'},
  {id:'e49',module:'必修二',q:'工业制粗硅：SiO₂ + 2C = Si(粗) + 2CO↑，C 表现？',options:['氧化性','酸性','还原性','漂白性'],answer:2,explain:'C 由 0 升到 +2（CO），作还原剂。'},
  {id:'e50',module:'必修二',q:'SiO₂ 能与 NaOH 反应：SiO₂ + 2NaOH = Na₂SiO₃ + H₂O，说明 SiO₂ 是？',options:['碱性氧化物','酸性氧化物、硅酸的酸酐','两性氧化物','不成盐氧化物'],answer:1,explain:'SiO₂ 是硅酸的酸酐，属酸性氧化物，难溶于水。'},
  {id:'e51',module:'必修二',q:'用氢氟酸刻蚀玻璃的反应是？',options:['SiO₂ + 2NaOH = Na₂SiO₃ + H₂O','SiO₂ + 4HF = SiF₄↑ + 2H₂O','SiO₂ + CaO = CaSiO₃','SiO₂ + C = Si + 2CO'],answer:1,explain:'HF 是唯一能与 SiO₂ 反应的酸，可用于刻蚀玻璃。'},
  {id:'e52',module:'必修二',q:'向 Na₂SiO₃ 溶液中通入 CO₂ 生成白色胶状沉淀（H₂SiO₃），说明？',options:['硅酸酸性强于碳酸','碳酸酸性强于硅酸','不反应','CO₂ 是碱性氧化物'],answer:1,explain:'强酸制弱酸，证明 H₂CO₃ 酸性 > H₂SiO₃。'},
  {id:'e53',module:'必修二',q:'SiO₂ 与 CaO 反应：SiO₂ + CaO = CaSiO₃，体现 SiO₂ 的？',options:['酸性氧化物通性','弱氧化性','强氧化性','还原性'],answer:0,explain:'酸性氧化物与碱性氧化物化合生成盐，是酸性氧化物通性。'},
  {id:'e54',module:'必修二',q:'甲烷燃烧：CH₄ + 2O₂ = CO₂ + 2H₂O，燃烧时观察到的火焰是？',options:['明亮火焰且伴有黑烟','苍白色火焰','淡蓝色火焰','黄色火焰'],answer:2,explain:'甲烷含碳量相对低、燃烧充分，呈淡蓝色火焰；乙烯（含碳量高）才明亮伴黑烟。'},
  {id:'e55',module:'必修二',q:'甲烷与 Cl₂ 在光照下发生取代反应，观察到的现象是？',options:['无明显现象','气体颜色变浅、试管内壁有油状液滴、液面上升','发生爆炸','生成白色沉淀'],answer:1,explain:'光照下 CH₄ 与 Cl₂ 取代，Cl₂ 消耗使颜色变浅，生成油状氯代烷，气体体积减小使液面上升。'},
  {id:'e56',module:'必修二',q:'甲烷的氯代产物中，常温常压下为气态的是？',options:['一氯甲烷（CH₃Cl）','二氯甲烷','三氯甲烷（氯仿）','四氯化碳'],answer:0,explain:'CH₃Cl 常温下为气体，CH₂Cl₂、CHCl₃、CCl₄ 均为液体。'},
  {id:'e57',module:'必修二',q:'CH₄ + Cl₂ → CH₃Cl + HCl，该反应类型是？',options:['加成反应','取代反应','氧化反应','化合反应'],answer:1,explain:'氢原子被氯原子替代，属取代反应。'},
  {id:'e58',module:'必修二',q:'酯化反应是酸与醇生成酯和水的反应，属于？',options:['加成反应','氧化反应','消去反应','取代反应'],answer:3,explain:'酸脱羟基、醇脱氢，属取代反应（也是可逆反应）。'},
  {id:'e59',module:'必修二',q:'制备乙酸乙酯时，饱和 Na₂CO₃ 溶液的作用不包括？',options:['催化反应','中和挥发出的乙酸','溶解挥发出的乙醇','降低酯的溶解度便于分层'],answer:0,explain:'催化剂是浓硫酸；Na₂CO₃ 起中和、溶解、降低酯溶解度的作用。'},
  {id:'e60',module:'必修二',q:'乙酸乙酯制备中浓硫酸的作用是？',options:['只作催化剂','只作吸水剂','催化剂和吸水剂','氧化剂'],answer:2,explain:'浓硫酸加快反应速率（催化）并吸水使平衡右移（吸水剂）。'},
  {id:'e61',module:'必修二',q:'导管末端不能插入饱和 Na₂CO₃ 溶液中，目的是？',options:['加快反应','提高温度','防止暴沸','防止倒吸'],answer:3,explain:'挥发出的乙酸、乙醇溶于水使局部压强降低，插入液面下会倒吸。'},
  {id:'e62',module:'选择性必修1',q:'原电池是将什么能转化为什么能的装置？',options:['光能→电能','电能→化学能','热能→电能','化学能→电能'],answer:3,explain:'原电池将化学能转化为电能，反应本质是氧化还原反应。'},
  {id:'e63',module:'选择性必修1',q:'Zn—Cu—稀 H₂SO₄ 原电池中，Cu 片上的现象是？',options:['铜片质量减小','铜片表面有气泡','锌片溶解','无明显变化'],answer:1,explain:'H⁺ 在 Cu 片表面得电子生成 H₂，故 Cu 片有气泡。'},
  {id:'e64',module:'选择性必修1',q:'原电池外电路中电子的流向是？',options:['负极→正极','阳极→阴极','无定向','正极→负极'],answer:0,explain:'电子由负极流出，经导线流向正极。'},
  {id:'e65',module:'选择性必修1',q:'原电池电解质溶液中，阳离子移向？',options:['阳极','无','正极','负极'],answer:2,explain:'阳离子移向正极，阴离子移向负极。'},
  {id:'e66',module:'选择性必修1',q:'构成原电池的条件不包括？',options:['两个活泼性不同的电极','电解质溶液','闭合回路','外接直流电源'],answer:3,explain:'原电池依靠自发的氧化还原反应，不需外接电源（那是电解池）。'},
  {id:'e67',module:'选择性必修1',q:'Zn—Cu 原电池中 Zn 片是？',options:['负极，逐渐溶解','正极','质量增加','得电子的电极'],answer:0,explain:'Zn 较活泼作负极，失电子溶解。'},
  {id:'e68',module:'选择性必修1',q:'电解精炼铜时，阴极材料是？',options:['阳极','粗铜','纯铜','任意'],answer:2,explain:'纯铜作阴极，粗铜作阳极，CuSO₄ 溶液作电解液。'},
  {id:'e69',module:'选择性必修1',q:'阳极泥的形成是因为 Ag、Au 等杂质？',options:['比 Cu 活泼而溶解','失电子能力比 Cu 弱，不溶解而沉积','与 Cu 一起析出','无法判断'],answer:1,explain:'Ag、Au 失电子能力比 Cu 弱，难在阳极溶解，以单质沉积成阳极泥。'},
  {id:'e70',module:'选择性必修1',q:'阴极上析出的金属是？',options:['Zn','Cu','Ag','Fe'],answer:1,explain:'只有 Cu²⁺ 在阴极得电子析出纯铜（其他离子得电子能力更弱）。'},
  {id:'e71',module:'选择性必修1',q:'电解精炼过程中，电解质溶液 Cu²⁺ 浓度？',options:['保持不变','无法判断','有所减小','增大'],answer:2,explain:'阳极比 Cu 活泼的杂质溶解、阴极只析 Cu，故 Cu²⁺ 浓度有所减小，需定期除杂。'},
  {id:'e72',module:'选择性必修1',q:'阳极减少的质量与阴极增加的质量？',options:['无法判断','无关','相等','不相等'],answer:3,explain:'阳极溶解含多种金属，阴极只析 Cu，二者质量不相等；但得失电子总数相等。'},
  {id:'e73',module:'选择性必修1',q:'精炼镍时，比镍不活泼的铜会？',options:['沉积','溶解','不反应','无法判断'],answer:0,explain:'比精炼金属不活泼的杂质会沉积（如精炼镍时 Cu 沉积）。'},
    {id:'e74',module:'选择性必修3',q:'有机化合物中，单键、双键、三键所含 σ 键和 π 键的数目关系，正确的是？',options:['单键：1σ；双键：1σ1π；三键：1σ2π','单键：1σ；双键：1σ2π；三键：1σ3π','单键：1σ；双键：2σ；三键：3σ','单键：0σ1π；双键：1σ1π；三键：1σ2π'],answer:0,explain:'单键全是σ键；双键含1σ1π；三键含1σ2π。'},
    {id:'e75',module:'选择性必修3',q:'含有 π 键的有机物容易发生哪类反应？',options:['消去反应','加成反应','酯化反应','取代反应'],answer:1,explain:'π键较活泼，含π键的有机物（如烯烃、炔烃）易发生加成反应；含 C—H σ 键可发取代。'},
    {id:'e76',module:'选择性必修3',q:'【实验】乙醇与蒸馏水分别与金属钠反应的实验现象，正确的是？',options:['二者均无气泡','乙醇不反应、水反应剧烈','二者均剧烈反应，乙醇更剧烈','乙醇反应缓慢、水反应剧烈，两烧杯均有气泡产生'],answer:3,explain:'乙醇与水均能与 Na 反应放出 H2（有气泡），但乙醇中 O—H 极性弱于水，反应更缓慢。'},
    {id:'e77',module:'选择性必修3',q:'【实验】乙醇与钠反应比水与钠反应缓慢，原因是？',options:['钠不溶于乙醇','乙醇分子中 O—H 键极性比水弱','乙醇分子中 C—H 键极性更强','乙醇沸点更高'],answer:1,explain:'基团间相互影响使官能团化学键极性改变，乙醇 O—H 极性弱于水，故反应更缓。'},
    {id:'e78',module:'选择性必修3',q:'乙炔的实验室制法所用主要原料是？',options:['苯和液溴','电石（CaC2）和饱和食盐水','乙醇和浓硫酸','甲烷和氯气'],answer:1,explain:'CaC2 + 2H2O → C2H2↑ + Ca(OH)2（不需加热），用饱和食盐水减缓速率。'},
    {id:'e79',module:'选择性必修3',q:'【实验】电石中常含 CaS、Ca3P2 等杂质，制得的乙炔会混有 H2S、PH3 等，净化时应通过？',options:['蒸馏水','碱石灰','浓硫酸','盛 NaOH 或 CuSO4 溶液的洗气瓶'],answer:3,explain:'H2S、PH3 可被 NaOH 或 CuSO4 溶液吸收除去。'},
    {id:'e80',module:'选择性必修3',q:'【实验】乙炔的收集装置通常用？',options:['直接通入碱液','向下排空气法','排水法','向上排空气法'],answer:2,explain:'乙炔微溶于水，用排水法收集（不用排空气法，因其密度与空气接近且可燃）。'},
    {id:'e81',module:'选择性必修3',q:'【实验】电石与水反应的制气类型属于？',options:['液+液—加热','固+固—加热','固+液—不加热（气）','固+固—不加热'],answer:2,explain:'CaC2（固）+ H2O（液）→ 气体，不需加热，属固+液—气型，用分液漏斗+圆底烧瓶。'},
    {id:'e82',module:'选择性必修3',q:'【实验】CaC2 与水反应的主反应方程式是？',options:['CaC2 + 2H2O → C2H2↑ + Ca(OH)2','CaC2 + H2O → CaO + C2H2','CaC2 + 2HCl → C2H2 + CaCl2','CaC2 + CO2 → C2H2 + CaCO3'],answer:0,explain:'主反应 CaC2 + 2H2O = C2H2↑ + Ca(OH)2。'},
    {id:'e83',module:'选择性必修3',q:'卤代烃的官能团及饱和一卤代烃通式是？',options:['醛基，CnH2nO','羧基，CnH2nO2','碳卤键（—X），CnH2n+1X','羟基，CnH2n+1OH'],answer:2,explain:'卤代烃官能团为碳卤键，R—X，饱和一卤代烃通式 CnH2n+1X。'},
    {id:'e84',module:'选择性必修3',q:'溴乙烷水解反应（取代）的条件是？',options:['NaOH 乙醇溶液、加热','浓硫酸、加热','NaOH 水溶液、加热','光照'],answer:2,explain:'卤代烃水解（取代）用 NaOH 水溶液加热：CH3CH2Br + NaOH → CH3CH2OH + NaBr。'},
    {id:'e85',module:'选择性必修3',q:'溴乙烷的消去反应条件是？',options:['NaOH 水溶液、加热','浓硫酸','光照','强碱的乙醇溶液、加热'],answer:3,explain:'消去反应用强碱乙醇溶液加热：CH3CH2Br + NaOH(醇) → CH2=CH2↑ + NaBr + H2O。'},
    {id:'e86',module:'选择性必修3',q:'【实验】检验卤代烃中卤素原子，正确步骤是？',options:['加 NaOH 乙醇溶液 → 直接加 AgNO3','加水加热后加 AgNO3','直接加 AgNO3 溶液','加 NaOH 水溶液加热 → 冷却加稀硝酸酸化 → 加 AgNO3 溶液'],answer:3,explain:'卤素以共价键结合不能直检，需先 NaOH 水解，再稀硝酸中和至酸性，后加 AgNO3；沉淀颜色判断卤素（白=Cl、浅黄=Br、黄=I）。'},
    {id:'e87',module:'选择性必修3',q:'【实验】上题中出现黄色沉淀，说明卤代烃中含有？',options:['I⁻','Br⁻','Cl⁻','F⁻'],answer:0,explain:'AgI 为黄色沉淀，AgBr 浅黄，AgCl 白。'},
    {id:'e88',module:'选择性必修3',q:'醇的官能团及饱和一元醇通式是？',options:['—X，CnH2n+1X','—OH（羟基），CnH2n+1OH','—CHO，CnH2nO','—COOH，CnH2nO2'],answer:1,explain:'醇为羟基连烃基/苯环侧链碳，饱和一元醇通式 CnH2n+1OH（n≥1）。'},
    {id:'e89',module:'选择性必修3',q:'相对分子质量相近时，醇的沸点远高于烷烃，原因是？',options:['醇有双键','烷烃有氢键','醇分子量更大','醇分子间形成氢键'],answer:3,explain:'醇分子含 —OH 可形成分子间氢键，故沸点显著高于相近分子量烷烃。'},
    {id:'e90',module:'选择性必修3',q:'医疗上常用作消毒剂的乙醇溶液体积分数是？',options:['100%','95%','75%','50%'],answer:2,explain:'体积分数 75% 的乙醇溶液杀菌效果最佳，常用于消毒。'},
    {id:'e91',module:'选择性必修3',q:'【实验】钠与乙醇、水反应对比，正确的是？',options:['钠沉于乙醇底部不熔化、浮于水面熔成小球；乙醇反应慢、水反应剧烈','钠与乙醇不反应','钠与水反应缓慢、与乙醇剧烈','二者均浮于液面熔化'],answer:0,explain:'ρ(Na)<ρ(H2O) 浮于水面熔球剧烈游动；ρ(Na)>ρ(C2H5OH) 沉底不熔缓慢消失；水反应更剧烈（羟基氢更活泼）。'},
    {id:'e92',module:'选择性必修3',q:'【实验】钠与乙醇、水反应实质的相同点是？',options:['均生成氧气','均置换出碳上的氢','均发生加成','均置换出羟基上的氢（H 被置换）'],answer:3,explain:'二者都是羟基（或水中的）氢被 Na 置换放出 H2；乙醇为羟基氢、水为水分子氢。'},
    {id:'e93',module:'选择性必修3',q:'【实验】乙烯的实验室制法：在圆底烧瓶中加入乙醇和浓硫酸（体积比约 1:3），迅速加热至？',options:['170℃','200℃以上','140℃','100℃'],answer:0,explain:'CH3CH2OH 在浓硫酸、170℃ 消去生成乙烯；140℃ 生成乙醚（副产物），需加碎瓷片防暴沸。'},
    {id:'e94',module:'选择性必修3',q:'【实验】检验生成的乙烯，可将气体通入？',options:['仅水','溴的四氯化碳溶液和酸性 KMnO4 溶液（均褪色）','仅 NaOH 溶液','仅食盐水'],answer:1,explain:'乙烯使溴的 CCl4 溶液和酸性 KMnO4 均褪色，用以验证消去生成乙烯。'},
    {id:'e95',module:'选择性必修3',q:'【实验】乙醇催化氧化（Cu 或 Ag 催化）：将灼烧至红热的铜丝插入乙醇，铜丝立即变红，说明？',options:['乙醇被氧化，Cu 被还原（红色的 Cu），生成有刺激性气味的乙醛','铜被氧化','乙醇被还原为乙醛','不反应'],answer:0,explain:'2CH3CH2OH + O2 →(Cu/Ag,△) 2CH3CHO + 2H2O；红热 CuO 被乙醇还原为红色 Cu，乙醇氧化为乙醛（刺激性气味）。'},
    {id:'e96',module:'选择性必修3',q:'乙醇与乙酸的酯化反应机理是？',options:['醇脱羟基、酸脱氢','酸脱羟基、醇脱氢','两者均脱羟基','两者均脱氢'],answer:1,explain:'酯化反应"酸脱羟基醇脱氢"，生成酯和水。'},
    {id:'e97',module:'选择性必修3',q:'乙醇在浓硫酸 140℃ 条件下分子间脱水生成？',options:['乙酸','乙醛','乙烯','乙醚'],answer:3,explain:'2C2H5OH →(浓 H2SO4,140℃) C2H5OC2H5 + H2O（乙醚），一个脱羟基一个脱氢。'},
    {id:'e98',module:'选择性必修3',q:'羧酸的官能团及乙酸的酸性强弱比较，正确的是？',options:['—COOH；乙酸不具酸性','—CHO；乙酸是强酸','—COOH；乙酸酸性比 H2CO3 强','—OH；乙酸酸性比 H2CO3 弱'],answer:2,explain:'羧酸官能团 —COOH；乙酸为一元弱酸，但酸性强于 H2CO3（可制 CO2）。'},
    {id:'e99',module:'选择性必修3',q:'酯化反应（羧酸+醇）属于哪类反应、机理是？',options:['加成反应；酸脱氢醇脱羟基','氧化反应','取代反应；酸脱羟基醇脱氢','消去反应'],answer:2,explain:'酯化=取代反应，机理"酸脱羟基醇脱氢"，生成酯和水，可逆。'},
    {id:'e100',module:'选择性必修3',q:'【实验】乙酸乙酯制备实验中，将蒸气通到饱和 Na2CO3 溶液液面上，现象及目的是？',options:['液面有透明油状液体、闻到果香；饱和 Na2CO3 吸收醇/中和酸、降低酯溶解度','溶液变红','无明显现象；吸收乙醇','生成白色沉淀'],answer:0,explain:'饱和 Na2CO3 吸收挥发的乙醇、中和乙酸，降低乙酸乙酯溶解度，便于分层观察油状液体（果香）。'},
    {id:'e101',module:'选择性必修3',q:'【实验】乙酸乙酯制备中，加入碎瓷片的作用是？',options:['中和','防止暴沸','吸水','催化'],answer:1,explain:'加热液体混合物加碎瓷片（或沸石）提供汽化中心，防止暴沸。'},
    {id:'e102',module:'必修一',q:'【实验】粗盐提纯（杂质含 CaCl₂、MgCl₂、Na₂SO₄ 等），下列试剂加入顺序合理的是？',options:['BaCl₂溶液→NaOH溶液→Na₂CO₃溶液→过滤→适量盐酸','Na₂CO₃溶液→BaCl₂溶液→NaOH溶液→过滤→适量盐酸','BaCl₂溶液→Na₂CO₃溶液→NaOH溶液→过滤→适量硫酸','NaOH溶液→Na₂CO₃溶液→BaCl₂溶液→过滤→适量盐酸'],answer:0,explain:'关键：Na₂CO₃ 必须在 BaCl₂ 之后加入，用于除去过量 Ba²⁺；过滤后加适量盐酸除去过量 CO₃²⁻ 和 OH⁻。B 中 Na₂CO₃ 在前无法除过量 Ba²⁺；C 最后加硫酸引入 SO₄²⁻；D 中最后加的 BaCl₂ 过量部分无法除去。'},
    {id:'e103',module:'必修一',q:'【实验】蒸馏操作中，温度计水银球（感温泡）的正确位置是？',options:['插入蒸馏烧瓶内的液体中','位于蒸馏烧瓶支管口处','伸入液面以下且靠近瓶底','悬在支管口上方'],answer:1,explain:'蒸馏测定的是馏分蒸气的温度，温度计水银球应与支管口处齐平；插入液体中测的是液体温度。加热前须加碎瓷片防暴沸，冷凝水下口进上口出。'},
    {id:'e104',module:'必修一',q:'【实验】用萃取法提取碘水中的碘，下列不能作萃取剂的是？',options:['四氯化碳','汽油（分馏产物）','酒精（乙醇）','苯'],answer:2,explain:'萃取剂须与水互不相溶、不与被萃取物反应、溶质在其中溶解度远大于在水中的溶解度。酒精与水互溶，无法分层，不能作萃取剂；CCl₄、苯、汽油均可。'},
    {id:'e105',module:'必修一',q:'【实验】向碘水中加入四氯化碳，振荡、静置分层后的现象是？',options:['上层呈紫红色，下层接近无色','下层呈紫红色，上层颜色变浅接近无色','上下两层均无色','产生白色沉淀'],answer:1,explain:'CCl₄ 密度比水大且不溶于水，碘在 CCl₄ 中溶解度远大于水中，故下层 CCl₄ 层呈紫红色，上层水层颜色变浅。分液时下层液体从下口放出，上层从上口倒出。'},
    {id:'e106',module:'必修一',q:'【实验】用容量瓶配制一定物质的量浓度的 NaCl 溶液，下列操作正确的是？',options:['在容量瓶中直接溶解 NaCl 固体','将容量瓶放入烘箱烘干后再转移溶液','转移后洗涤烧杯和玻璃棒 2~3 次，洗涤液一并转入容量瓶','定容时俯视刻度线，使浓度更准确'],answer:2,explain:'容量瓶不能用于溶解（应在烧杯中溶解、冷却至室温后转移），不能加热烘干、不能久存溶液；转移后必须洗涤烧杯和玻璃棒并将洗涤液转入，否则溶质损失使浓度偏低。俯视定容实际加水偏少，浓度偏大。'},
    {id:'e107',module:'必修一',q:'【实验】焰色试验中，观察钾元素火焰颜色所需的操作是？',options:['透过蓝色钴玻璃观察','透过黄色玻璃观察','直接用肉眼观察','需将铂丝换成铜丝'],answer:0,explain:'钠的黄色火焰会掩盖钾的紫色，透过蓝色钴玻璃可滤去黄光，观察到钾的紫色火焰。操作前铂丝（或铁丝）需用盐酸洗净并灼烧至无色；铜丝会引入黄色焰色，不能替代。'},
    {id:'e108',module:'必修一',q:'【实验】实验室用 MnO₂ 与浓盐酸共热制取纯净干燥的 Cl₂，装置连接顺序正确的是？',options:['发生装置→盛饱和食盐水的洗气瓶→盛浓硫酸的洗气瓶→向上排空气法收集→NaOH 尾气吸收','发生装置→盛浓硫酸的洗气瓶→盛饱和食盐水的洗气瓶→向上排空气法收集','发生装置→排水法收集→NaOH 尾气吸收','发生装置→直接用排空气法收集→无需尾气处理'],answer:0,explain:'制得的 Cl₂ 混有 HCl 和水蒸气：先经饱和食盐水除 HCl，再经浓硫酸干燥（顺序不能颠倒，否则气体重新带水）；Cl₂ 密度比空气大且能溶于水，用向上排空气法收集；尾气用 NaOH 溶液吸收防止污染。'},
    {id:'e109',module:'必修一',q:'【实验】检验某溶液中是否含有 Cl⁻，正确的操作是？',options:['滴加 AgNO₃ 溶液，看是否产生白色沉淀','先加足量稀硝酸酸化，再滴加 AgNO₃ 溶液，看是否产生不溶于稀硝酸的白色沉淀','先加盐酸酸化，再滴加 AgNO₃ 溶液','滴加酚酞观察颜色变化'],answer:1,explain:'先加足量稀硝酸排除 CO₃²⁻、SO₃²⁻ 等干扰，再加 AgNO₃ 产生不溶于稀硝酸的白色沉淀（AgCl）才能证明含 Cl⁻；盐酸会引入 Cl⁻ 造成干扰；酚酞与 Cl⁻ 无反应。'},
    {id:'e110',module:'必修一',q:'【实验】制备并观察白色的 Fe(OH)₂ 沉淀，为防止其被氧化，应采取的措施是？',options:['用沸水配制 FeSO₄ 溶液','新配 FeSO₄ 和 NaOH 溶液并煮沸除氧，将吸有 NaOH 的胶头滴管尖嘴伸入 FeSO₄ 液面以下再挤出','向 FeSO₄ 溶液中通入 Cl₂ 后再加 NaOH','敞口充分搅拌使反应完全'],answer:1,explain:'Fe(OH)₂ 极易被 O₂ 氧化（白色→灰绿色→红褐色）。新配溶液并煮沸赶走溶解氧、滴管插入液面以下隔绝空气，才能观察到白色沉淀。通 Cl₂ 会把 Fe²⁺ 氧化为 Fe³⁺，得不到 Fe(OH)₂。'},
    {id:'e111',module:'必修一',q:'【实验】除去 FeCl₃ 溶液中混有的少量 FeCl₂，最合适的方法是？',options:['通入足量氯气','加入足量铁粉','加入酸性 KMnO₄ 溶液','加入足量 NaOH 溶液后过滤'],answer:0,explain:'足量 Cl₂ 将 Fe²⁺ 氧化为 Fe³⁺ 且不引入新杂质；铁粉会把 Fe³⁺ 还原为 Fe²⁺（方向相反）；KMnO₄ 会引入 K⁺、Mn²⁺ 等杂质；NaOH 使 Fe³⁺ 一并沉淀。'},
    {id:'e112',module:'必修一',q:'【实验】将 SO₂ 通入品红溶液使其褪色，再将液体加热，现象是？',options:['红色不复现','恢复红色','变成黄色','产生白色沉淀'],answer:1,explain:'SO₂ 与有色物质化合生成不稳定的无色物质，加热后分解，红色恢复——其漂白具有可逆性，可用于鉴别 SO₂。与氯水（HClO）的氧化漂白不同，HClO 漂白不可逆，加热不复色。'},
    {id:'e113',module:'必修一',q:'【实验】氨气喷泉实验能形成喷泉的根本原因是？',options:['氨气密度比空气小','氨气极易溶于水，烧瓶内气压骤减，外界大气压将水压入烧瓶','氨气与水反应放热使瓶内压强增大','烧瓶容积大'],answer:1,explain:'挤入少量水后氨气大量溶解，瓶内压强急剧减小，内外压强差将烧杯中的水（含酚酞，进入后变红）压入烧瓶形成喷泉。凡气体极易溶于液体或能与之反应（如 HCl、NH₃）均可形成喷泉。'},
    {id:'e114',module:'必修二',q:'【实验】铜锌原电池（稀硫酸作电解质溶液）工作时的现象是？',options:['锌片溶解，铜片上有气泡产生，电流表指针偏转','铜片溶解，锌片上有气泡产生','两电极均无变化','锌片表面产生大量气泡'],answer:0,explain:'Zn 为负极失电子被氧化而溶解（Zn−2e⁻=Zn²⁺）；H⁺ 在正极铜片上得电子生成 H₂ 气泡（2H⁺+2e⁻=H₂↑）；电子经导线由锌流向铜，化学能转化为电能。'},
    {id:'e115',module:'必修二',q:'【实验】下列盛稀硫酸的装置中，能构成原电池的是？',options:['两块铜片作电极并用导线连接','锌片与铜片直接接触后浸入溶液','锌片和铜片作电极，用导线连接形成闭合回路','锌片和石墨棒作电极，回路断开'],answer:2,explain:'原电池构成条件：两个活泼性不同的电极、电解质溶液、形成闭合回路、能发生自发的氧化还原反应。A 两电极相同；B 电子不经外电路；D 回路断开；只有 C 符合。'},
    {id:'e116',module:'必修二',q:'【实验】向盛少量无水乙醇的试管中加入一小块金属钠，观察到的现象是？',options:['钠浮在液面上并快速游动','钠沉于乙醇底部，缓慢产生气泡','剧烈爆炸','无任何现象'],answer:1,explain:'钠密度大于乙醇沉在底部；乙醇羟基氢的活泼性远弱于水，反应平缓放出 H₂：2C₂H₅OH+2Na→2C₂H₅ONa+H₂↑。该反应证明乙醇分子中羟基（—OH）上的氢可被置换，是推断乙醇结构的重要依据。'},
    {id:'e117',module:'必修二',q:'【实验】检验葡萄糖的还原性，向其溶液中加入新制 Cu(OH)₂ 并加热，现象是？',options:['产生蓝色沉淀','产生砖红色沉淀','无明显现象','溶液变为紫红色'],answer:1,explain:'葡萄糖含醛基，在碱性条件下加热能还原新制 Cu(OH)₂ 生成砖红色 Cu₂O 沉淀。银氨溶液水浴加热同样可检验（光亮银镜）。蔗糖无还原性，无此现象。'},
    {id:'e118',module:'必修二',q:'【实验】鉴别棉织品（纤维素）和羊毛织品（蛋白质），最简便的方法是？',options:['滴加碘水','灼烧并闻气味','滴加酚酞试液','观察外观颜色'],answer:1,explain:'蛋白质灼烧有烧焦羽毛的气味，纤维素灼烧只有类似烧纸的气味，此法最简便。蛋白质遇浓硝酸显黄色（颜色反应）也可用于鉴别。'},
    {id:'e119',module:'必修二',q:'【实验】淀粉在稀硫酸中水解后，检验水解产物葡萄糖的正确操作是？',options:['取水解液直接加入银氨溶液水浴加热','取水解液先加 NaOH 中和至碱性，再加入银氨溶液水浴加热','取水解液滴加碘水观察是否变蓝','取水解液直接加入新制 Cu(OH)₂ 振荡'],answer:1,explain:'银镜反应和与新制 Cu(OH)₂ 的反应都必须在碱性条件下进行，水解液中的稀硫酸会破坏试剂，必须先用 NaOH 中和。碘水只能检验是否残留淀粉，不能检验葡萄糖。'},
    {id:'e120',module:'选择性必修1',q:'【实验】测定中和热时，量热计中酸碱溶液的合理组合是？',options:['50 mL 0.50 mol/L 盐酸与 50 mL 0.55 mol/L NaOH 溶液','50 mL 0.50 mol/L 盐酸与 50 mL 0.50 mol/L 醋酸溶液','50 mL 1.0 mol/L 盐酸与 5 mL 0.50 mol/L NaOH 溶液','50 mL 浓硫酸与 50 mL NaOH 溶液'],answer:0,explain:'测定强酸强碱稀溶液的中和热（约 57.3 kJ/mol）：碱稍过量保证 H⁺ 完全被中和；醋酸电离吸热使结果偏低；酸碱体积悬殊不能保证完全反应；浓硫酸溶解放热大量放热，不能用于中和热测定。'},
    {id:'e121',module:'选择性必修1',q:'【实验】中和热测定值明显偏小，最可能的原因是？',options:['使用了环形玻璃搅拌棒轻轻搅动','量热计隔热层破损，热量散失','碱液稍过量','以最高温度作为末温读数'],answer:1,explain:'隔热不良导致热量散失，测得温差偏小，中和热数值偏小。搅拌使温度均匀、碱稍过量保证反应完全、读最高温度都是正确操作，不会导致偏小。'},
    {id:'e122',module:'选择性必修1',q:'【实验】用标准盐酸滴定待测 NaOH 溶液（酚酞作指示剂），下列会使测定结果偏大的是？',options:['酸式滴定管用蒸馏水洗净后直接注入标准盐酸','锥形瓶用蒸馏水洗净后直接盛待测液','滴定前排除滴定管尖嘴处的气泡','滴至红色褪去且半分钟不恢复即停止滴定'],answer:0,explain:'滴定管水洗后未用标准液润洗，标准盐酸被残留水稀释，消耗体积偏大，测得浓度偏大。锥形瓶不能用待测液润洗，但水洗无影响（溶质的量不变）；排气泡和正确判断终点都是规范操作。'},
    {id:'e123',module:'选择性必修1',q:'【实验】探究浓度对化学反应速率的影响，最合适的对照实验是？',options:['不同浓度的 Na₂S₂O₃ 溶液分别与相同浓度的稀硫酸反应，比较出现浑浊的时间','不同温度下同浓度 H₂O₂ 的分解速率比较','同浓度盐酸分别与镁片和铁片反应','加入 FeCl₃ 催化剂前后 H₂O₂ 分解速率比较'],answer:0,explain:'对照实验只能改变一个变量：A 只改变 Na₂S₂O₃ 浓度，出现浑浊（S）时间越短速率越快。B 的变量是温度；C 中金属活泼性本身不同；D 的变量是催化剂，均不能单独研究浓度的影响。'},
    {id:'e124',module:'选择性必修1',q:'【实验】向 FeCl₃ 与 KSCN 的平衡混合液（红色）中滴加少量浓 FeCl₃ 溶液，现象及原因是？',options:['红色变浅，平衡逆向移动','红色加深，平衡正向移动','颜色不变','产生红褐色沉淀'],answer:1,explain:'Fe³⁺+3SCN⁻⇌Fe(SCN)₃（红色）。增大反应物 Fe³⁺ 浓度，平衡正向移动，Fe(SCN)₃ 浓度增大，红色加深。若改加 NaOH 消耗 Fe³⁺，则红色变浅。'},
    {id:'e125',module:'选择性必修1',q:'【实验】向盛有白色 AgCl 悬浊液的试管中滴加 KI 溶液并振荡，观察到的现象是？',options:['白色沉淀转变为黄色沉淀','沉淀完全溶解消失','产生大量气泡','沉淀颜色不变'],answer:0,explain:'沉淀总向溶解度更小的方向转化：AgCl（白）+I⁻→AgI（黄）+Cl⁻。同理难溶物可转化为更难溶的 ZnS→CuS（黑色）等。'},
    {id:'e126',module:'选择性必修1',q:'【实验】配制 FeCl₃ 溶液时，为抑制 Fe³⁺ 水解得到澄清溶液，应采取的措施是？',options:['先将溶液加热煮沸','将其溶于较浓的盐酸中，再加水稀释至所需浓度','加入足量 NaOH 溶液','用蒸馏水直接配制并长期放置'],answer:1,explain:'Fe³⁺+3H₂O⇌Fe(OH)₃+3H⁺，加热或稀释都促进水解使溶液浑浊；先溶于较浓盐酸增大 c(H⁺) 可抑制水解，再稀释到所需浓度。配制 CuSO₄、AlCl₃ 等强酸弱碱盐溶液同理。'},
    {id:'e127',module:'选择性必修2',q:'【实验】比较钠、镁、铝的金属性强弱，可依据的实验事实是？',options:['钠与冷水剧烈反应，镁与热水缓慢反应，铝与热水几乎不反应','三者与同浓度盐酸反应速率相同','铝与冷水反应最剧烈','镁与冷水剧烈反应放出大量氢气'],answer:0,explain:'金属与水（或酸）反应越剧烈，金属性越强。Na 与冷水剧烈反应，Mg 需热水才缓慢反应，Al 最弱，故金属性 Na＞Mg＞Al，符合同周期从左到右金属性减弱的规律。'},
    {id:'e128',module:'选择性必修2',q:'【实验】向 NaBr 溶液中滴加少量新制氯水，再加入四氯化碳振荡静置，现象和结论是？',options:['下层呈橙色，说明氧化性 Cl₂＞Br₂','上层呈紫色，说明生成 I₂','无现象，说明二者不反应','产生白色沉淀'],answer:0,explain:'Cl₂+2NaBr=2NaCl+Br₂，生成的 Br₂ 被密度比水大的 CCl₄ 萃取到下层呈橙色，证明氧化性 Cl₂＞Br₂。同理，氯水滴入 KI 淀粉溶液变蓝可证明 Cl₂＞I₂。'},
    {id:'e129',module:'选择性必修2',q:'【实验】将绿豆大小的钠、钾分别投入盛水的烧杯中，比较现象可得出？',options:['钾与水反应比钠剧烈得多，说明同主族从上到下金属性增强','钠与水反应更剧烈','两者现象完全相同','钾不与水反应'],answer:0,explain:'K 与水反应比 Na 剧烈得多（熔成小球快速游动、可能燃烧），说明 K 失电子能力更强，验证碱金属同主族从上到下金属性逐渐增强的递变规律。'},
    {id:'e130',module:'选择性必修3',q:'【实验】重结晶提纯苯甲酸时，趁热过滤的目的是？',options:['加快过滤速度','防止苯甲酸冷却结晶析出而随不溶杂质一起被丢弃','除去可溶性杂质','防止液体暴沸'],answer:1,explain:'苯甲酸在热水中溶解度大，趁热过滤可防止其在滤纸上提前结晶损失；滤液冷却后苯甲酸结晶析出，可溶性杂质留在母液中。活性炭用于吸附脱色。'},
    {id:'e131',module:'选择性必修3',q:'【实验】苯与液溴在铁屑（FeBr₃）催化下发生取代反应，下列说法正确的是？',options:['苯也能与溴水反应而使溴水褪色','导管口出现的白雾是 HBr 遇水蒸气形成的，可用硝酸银溶液检验','该反应不需要催化剂，加热即可','产物是邻、间、对多种二溴苯的混合物'],answer:1,explain:'苯与溴水不反应（萃取褪色是物理过程），与液溴在 FeBr₃ 催化下发生取代：C₆H₆+Br₂→C₆H₅Br+HBr。HBr 遇水蒸气成白雾，硝酸银溶液中产生淡黄色 AgBr 沉淀可检验。一元取代产物只有一溴苯一种。'},
    {id:'e132',module:'选择性必修3',q:'【实验】实验室制硝基苯（苯的硝化反应），控制反应温度的正确方法是？',options:['直接加热至沸腾','50~60 ℃ 水浴加热','冰水浴冷却','常温长时间放置'],answer:1,explain:'硝化用浓硫酸与浓硝酸的混合液，需 50~60 ℃ 水浴控温：温度过高副反应增多（生成二取代物），过低反应太慢。产物硝基苯密度比水大，有苦杏仁气味。'},
    {id:'e133',module:'选择性必修3',q:'【实验】只用一种试剂区分乙醇、乙酸、乙醛三种无色液体，最合适的是？',options:['新制 Cu(OH)₂ 悬浊液','紫色石蕊试液','金属钠','酚酞试液'],answer:0,explain:'加入新制 Cu(OH)₂：乙酸使其溶解得蓝色溶液（酸性）；乙醛加热后产生砖红色沉淀（还原性）；乙醇无现象。一种试剂三种不同现象即可区分。石蕊只能区分出乙酸；钠遇乙醇、乙酸都放气泡。'},
    {id:'e134',module:'选择性必修3',q:'【实验】做银镜反应要得到光亮银镜，正确的操作是？',options:['试管内壁必须洁净光滑，水浴加热，反应过程中不振荡','酒精灯直接加热并剧烈振荡','试管内壁保留油污有利于银附着','银氨溶液提前一天配好备用'],answer:0,explain:'试管须用热碱液洗净油污，水浴温热、静置不振荡，银才能均匀附着形成光亮银镜，否则得到黑色疏松沉淀。银氨溶液必须现配现用，久置会产生易爆物质。'},
    {id:'e135',module:'选择性必修3',q:'【实验】由工业酒精（约 95% 的乙醇）制取无水乙醇，应采用的方法是？',options:['直接反复蒸馏','加入生石灰后蒸馏','加入无水硫酸铜后过滤','加入浓硫酸加热'],answer:1,explain:'生石灰与水反应生成不挥发、不与乙醇反应的 Ca(OH)₂，再蒸馏即得无水乙醇；是否还含水可用无水硫酸铜检验（变蓝则含水）。直接蒸馏受共沸限制最高只能得约 95.6% 的乙醇。'},
    {id:'e136',module:'选择性必修3',q:'【实验】油脂在 NaOH 溶液中加热皂化的实验里，加入乙醇的作用是？',options:['作催化剂','增大油脂在反应液中的溶解度，使反应充分进行','防止暴沸','中和生成的甘油'],answer:1,explain:'油脂与碱液分层、接触面小，水解慢且不完全；乙醇能同时溶解油脂和碱液，使反应充分均相进行。皂化完成后加食盐细粒盐析，上层得高级脂肪酸钠（肥皂主要成分）。'},
  ]
};
